/// Whether a currently-missing config should be framed as an ordinary
/// first run rather than a possible problem: only when this session has
/// never once seen the config file present and readable. Kept as its own
/// pure predicate (mirroring `library_table_message`/
/// `gamer_empty_list_guidance`) so the distinction is directly testable
/// without an `egui::Ui`.
fn missing_config_is_first_run(config_previously_confirmed: bool) -> bool {
    !config_previously_confirmed
}

fn show_setup_diagnostics(
    ui: &mut egui::Ui,
    state: &DiagnosticsState,
    action_running: bool,
    feedback: Option<&ActionFeedback>,
    refresh_error: Option<&str>,
    has_last_snapshot: bool,
    config_previously_confirmed: bool,
) -> Option<DiagnosticsUiAction> {
    let mut action = None;
    ui.heading("Setup / Diagnostics");
    ui.label("Check configuration, folders, and required system tools before using EmuWiz.");
    ui.add_space(8.0);
    if let Some(error) = refresh_error {
        ui.colored_label(
            ui.visuals().error_fg_color,
            format!("Archive refresh failed: {error}"),
        );
        ui.label("Diagnostics are being refreshed from the current configuration.");
        if has_last_snapshot
            && ui
                .add_enabled(
                    !action_running,
                    egui::Button::new("View Last Known Snapshot"),
                )
                .clicked()
        {
            return Some(DiagnosticsUiAction::ViewLastSnapshot);
        }
        ui.add_space(8.0);
    }
    if let DiagnosticsState::Error { message, .. } = state {
        ui.colored_label(ui.visuals().error_fg_color, message);
        ui.label("Select Refresh Diagnostics to try again.");
        if ui
            .add_enabled(!action_running, egui::Button::new("Refresh Diagnostics"))
            .clicked()
        {
            return Some(DiagnosticsUiAction::Refresh);
        }
        return None;
    }
    let DiagnosticsState::Ready { report, .. } = state else {
        ui.spinner();
        ui.label("Running diagnostics in the background...");
        ui.add_enabled(false, egui::Button::new("Continue to EmuWiz"));
        return None;
    };
    if report.config_missing && report.config_path_error.is_none() {
        if missing_config_is_first_run(config_previously_confirmed) {
            egui::Frame::group(ui.style()).show(ui, |ui| {
                ui.strong("Welcome to EmuWiz");
                ui.label(
                    "EmuWiz is not configured yet - that is expected on a fresh install, not \
                     an error. Select Create Starter Config below to begin, then add a source \
                     folder on the Sources page.",
                );
                ui.label(
                    "DAT Sources and Cheat Sources live on their own pages and start empty; \
                     both are optional. RomM is optional too. Audits are always read-only: \
                     EmuWiz will not rename, move or delete any ROM without a later, \
                     explicit, reviewed action.",
                );
            });
        } else {
            // Not a first run: this session already saw the config file
            // present and readable, and it is now gone. That can be an
            // intentional removal, but it can just as easily mean a real
            // problem (deleted by accident, an unmounted drive, a bug) -
            // so this is never dressed up as an ordinary welcome.
            egui::Frame::group(ui.style()).show(ui, |ui| {
                ui.colored_label(theme::WARNING, "Configuration file is no longer found");
                ui.label(
                    "EmuWiz found your configuration earlier in this session, and it is no \
                     longer present. If you did not remove it intentionally, check whether it \
                     was deleted, moved, or is on a drive that is no longer mounted, before \
                     creating a new one below.",
                );
            });
        }
        ui.add_space(8.0);
    }
    ui.horizontal_wrapped(|ui| {
        ui.strong("Config path:");
        match &report.config_path {
            Some(path) => {
                ui.monospace(path.display().to_string());
                if ui
                    .add_enabled(!action_running, egui::Button::new("Copy Config Path"))
                    .clicked()
                {
                    action = Some(DiagnosticsUiAction::CopyConfigPath);
                }
                if ui
                    .add_enabled(!action_running, egui::Button::new("Open Config Folder"))
                    .clicked()
                {
                    action = Some(DiagnosticsUiAction::OpenConfigFolder);
                }
            }
            None => {
                ui.colored_label(
                    ui.visuals().error_fg_color,
                    report
                        .config_path_error
                        .as_deref()
                        .unwrap_or("Config path could not be resolved."),
                );
            }
        }
    });
    ui.horizontal_wrapped(|ui| {
        if starter_config_available(report)
            && ui
                .add_enabled(!action_running, egui::Button::new("Create Starter Config"))
                .clicked()
        {
            action = Some(DiagnosticsUiAction::CreateStarterConfig);
        }
        if report.can_create_mount_root
            && ui
                .add_enabled(!action_running, egui::Button::new("Create Mount Root"))
                .clicked()
        {
            action = Some(DiagnosticsUiAction::CreateMountRoot);
        }
        if ui
            .add_enabled(!action_running, egui::Button::new("Refresh Diagnostics"))
            .clicked()
        {
            action = Some(DiagnosticsUiAction::Refresh);
        }
        if ui
            .add_enabled(
                !action_running && diagnostics_state_can_continue(state),
                egui::Button::new("Continue to EmuWiz"),
            )
            .clicked()
        {
            action = Some(DiagnosticsUiAction::Continue);
        }
        if action_running {
            ui.spinner();
            ui.label("Setup action running...");
        }
    });
    if let Some(feedback) = feedback {
        ui.colored_label(
            if feedback.succeeded {
                egui::Color32::from_rgb(70, 170, 90)
            } else {
                ui.visuals().error_fg_color
            },
            &feedback.message,
        );
    }
    ui.separator();
    egui::ScrollArea::vertical()
        .id_salt("setup_diagnostics_checks")
        .show(ui, |ui| {
            for check in &report.checks {
                let (state_label, color) = match check.status {
                    SetupDiagnosticStatus::Ready => ("Ready", egui::Color32::from_rgb(70, 170, 90)),
                    // Neither a pass nor a problem: the check did not run.
                    SetupDiagnosticStatus::NotChecked => ("Not checked", theme::muted(ui)),
                    // Expected on a fresh install - informational, not red.
                    SetupDiagnosticStatus::NotConfigured => ("Not configured", theme::muted(ui)),
                    SetupDiagnosticStatus::Warning => {
                        ("Warning", egui::Color32::from_rgb(220, 170, 40))
                    }
                    SetupDiagnosticStatus::Error => ("Error", ui.visuals().error_fg_color),
                };
                egui::Frame::group(ui.style()).show(ui, |ui| {
                    ui.horizontal(|ui| {
                        ui.colored_label(color, state_label);
                        ui.strong(&check.name);
                    });
                    ui.label(&check.detail);
                    if check.status != SetupDiagnosticStatus::Ready {
                        ui.label(format!("Why it matters: {}", check.why_it_matters));
                        ui.label(format!("Next step: {}", check.next_step));
                    }
                });
                ui.add_space(4.0);
            }
        });
    action
}
enum ActivityPanelAction {
    ShowRelatedArchive(PathBuf),
}

fn activity_outcome_tone(outcome: ActivityOutcome) -> widgets::StatusTone {
    match outcome {
        ActivityOutcome::Completed => widgets::StatusTone::Success,
        ActivityOutcome::Failed | ActivityOutcome::Rejected => widgets::StatusTone::Blocked,
        ActivityOutcome::OfflineUsable => widgets::StatusTone::Info,
        ActivityOutcome::Started | ActivityOutcome::Retried | ActivityOutcome::Confirmed => {
            widgets::StatusTone::Active
        }
        ActivityOutcome::Offered | ActivityOutcome::Skipped | ActivityOutcome::Cancelled => {
            widgets::StatusTone::Pending
        }
    }
}

fn activity_summary_entry(history: &OperationHistory) -> Option<&HistoryEntry> {
    history
        .entries()
        .find(|entry| {
            matches!(
                entry.outcome,
                ActivityOutcome::Failed | ActivityOutcome::Rejected
            )
        })
        .or_else(|| history.entries().next())
}

fn show_activity_panel(
    context: &egui::Context,
    history: &mut OperationHistory,
    expanded: &mut bool,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<ActivityPanelAction> {
    let mut action = None;
    // Root cause of the bottom-clipping bug: `TopBottomPanel::bottom` picks
    // this frame's panel height by loading `PanelState` persisted under
    // its *own id* from the previous frame (egui's `panel.rs`), and only
    // falls back to a fresh default the very first time that id is ever
    // shown. Collapsed and expanded here render wildly different content
    // heights (one status row vs. a history list up to ~220px tall plus a
    // button row), but previously both used the *same* id ("activity") -
    // so the frame right after toggling from collapsed to expanded loaded
    // the collapsed height, squeezed the expanded content into it (that
    // content's own clip rect is the panel rect: see egui's `panel.rs`,
    // "If we overflow, don't do so visibly"), and only corrected itself
    // one frame later. A user's screenshot taken in that window - or
    // rendered while the app is between reactive repaints - shows exactly
    // "one line of content" jammed near the screen edge. Giving each
    // visual state its own id keeps their persisted heights from ever
    // contaminating each other, so there is no longer a wrong state to
    // render even transiently.
    let (panel_id, default_height) = if *expanded {
        ("activity_expanded", ACTIVITY_PANEL_EXPANDED_DEFAULT_HEIGHT)
    } else {
        (
            "activity_collapsed",
            ACTIVITY_PANEL_COLLAPSED_DEFAULT_HEIGHT,
        )
    };
    let maximum_height = if *expanded {
        (context.input(|input| input.screen_rect().height()) * 0.28)
            .clamp(120.0, ACTIVITY_PANEL_EXPANDED_DEFAULT_HEIGHT)
    } else {
        ACTIVITY_PANEL_COLLAPSED_DEFAULT_HEIGHT
    };
    egui::TopBottomPanel::bottom(panel_id)
        .resizable(*expanded)
        .default_height(default_height)
        .height_range(ACTIVITY_PANEL_COLLAPSED_DEFAULT_HEIGHT..=maximum_height)
        .show(context, |ui| {
            ui.horizontal(|ui| {
                if widgets::action_button(
                    ui,
                    if *expanded {
                        "Hide activity"
                    } else {
                        "Show activity"
                    },
                    widgets::ActionStyle::Quiet,
                    true,
                )
                .clicked()
                {
                    *expanded = !*expanded;
                }
                widgets::status_badge(
                    ui,
                    format!("{} events", history.entries.len()),
                    widgets::StatusTone::Info,
                );
                if !*expanded && let Some(entry) = activity_summary_entry(history) {
                    widgets::status_badge(
                        ui,
                        entry.outcome.to_string(),
                        activity_outcome_tone(entry.outcome),
                    );
                    ui.add(egui::Label::new(&entry.message).truncate())
                        .on_hover_text(&entry.message);
                }
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    if *expanded
                        && widgets::action_button(
                            ui,
                            "Clear activity",
                            widgets::ActionStyle::Destructive,
                            !history.entries.is_empty(),
                        )
                        .clicked()
                    {
                        history.clear();
                    }
                });
            });
            if !*expanded {
                return;
            }
            ui.separator();

            if history.entries.is_empty() {
                ui.weak("No recent activity.");
                return;
            }
            egui::ScrollArea::vertical()
                .id_salt("activity_history")
                .max_height(220.0)
                .auto_shrink([false, false])
                .show(ui, |ui| {
                    // Collected as owned data *before* the loop, rather
                    // than iterating `history.entries()` directly, so a
                    // menu item can freely call `history.clear()`/
                    // `history.remove()` without fighting the borrow
                    // checker over a `history` still being iterated.
                    let rows: Vec<(
                        usize,
                        ActivityAction,
                        ActivityOutcome,
                        String,
                        Option<PathBuf>,
                    )> = history
                        .entries()
                        .enumerate()
                        .map(|(index, entry)| {
                            (
                                index,
                                entry.action,
                                entry.outcome,
                                entry.message.clone(),
                                entry.archive_path.clone(),
                            )
                        })
                        .collect();
                    let mut remove_index = None;
                    for (index, activity, outcome, text, archive_path) in &rows {
                        let response = widgets::card(ui, |ui| {
                            widgets::activity_row_header(
                                ui,
                                outcome.to_string(),
                                activity_outcome_tone(*outcome),
                                activity.to_string(),
                                None,
                                |_ui| {},
                            );
                            ui.add(
                                egui::Label::new(text)
                                    .selectable(true)
                                    .wrap()
                                    .sense(egui::Sense::click()),
                            )
                        });
                        ui.add_space(6.0);
                        response.context_menu(|ui| {
                            if ui.button("Copy message").clicked() {
                                let _ = clipboard.set_text(text.clone());
                                ui.close();
                            }
                            if let Some(archive_path) = archive_path {
                                if ui.button("Copy related path").clicked() {
                                    let _ = clipboard.set_text(archive_path.display().to_string());
                                    ui.close();
                                }
                                if ui.button("Show related archive").clicked() {
                                    action = Some(ActivityPanelAction::ShowRelatedArchive(
                                        archive_path.clone(),
                                    ));
                                    ui.close();
                                }
                            }
                            ui.separator();
                            if ui.button("Clear this entry").clicked() {
                                remove_index = Some(*index);
                                ui.close();
                            }
                            if ui.button("Clear all entries").clicked() {
                                history.clear();
                                ui.close();
                            }
                        });
                    }
                    // Deferred to after the loop: removing mid-iteration
                    // would shift every later index out from under `rows`.
                    if let Some(index) = remove_index {
                        history.remove(index);
                    }
                });
        });
    action
}
/// The only thing the Doctor page can ask for in Stage 1A. There is no
/// repair action here by design: findings are read-only, and no finding
/// renders a clickable fix.
#[derive(Clone, Debug, PartialEq, Eq)]
enum DoctorPageAction {
    RunScan,
    /// Open the confirmation screen. Never executes anything.
    ReviewRepair {
        action: DoctorRepairAction,
        finding_id: String,
        affected: Option<String>,
    },
    /// The only action that mutates, and only from the confirmation screen.
    ConfirmRepair,
    CancelRepair,
}

/// The read-only Doctor dashboard.
///
/// Shows severity counts, findings grouped by category, and an evidence
/// panel for the selected finding. Where a repair already exists elsewhere
/// in EmuWiz the finding *says so in words* and stops there - Stage 1A
/// exposes no repair control at all.
/// Draws the whole Doctor page. The parameter list is long because the page is
/// one cohesive screen; the mode flag (Gamer vs Advanced) is the only thing
/// this PR's cleanup adds to the existing seven.
#[allow(clippy::too_many_arguments)]
fn show_doctor_page(
    ui: &mut egui::Ui,
    state: &DoctorScanState,
    selected: &mut Option<String>,
    review: Option<&DoctorRepairReview>,
    repair_result: Option<&DoctorRepairOutcome>,
    repair_finished_at_unix_seconds: Option<i64>,
    clipboard: &mut dyn ClipboardBackend,
    gamer_view: bool,
) -> Option<DoctorPageAction> {
    let mut action = None;
    // The confirmation screen replaces the finding list while it is open, so
    // there is no way to trigger a second repair from behind it.
    if let Some(review) = review {
        return show_doctor_repair_review(ui, review);
    }
    let running = state.is_running();
    let displayed = state.displayed();

    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            match displayed {
                Some(outcome) if outcome.scan.is_healthy() => {
                    widgets::status_badge(ui, "Healthy", widgets::StatusTone::Success)
                }
                Some(outcome) => widgets::status_badge(
                    ui,
                    outcome.scan.overall_severity().label(),
                    doctor_severity_tone(outcome.scan.overall_severity()),
                ),
                None => widgets::status_badge(ui, "Not run yet", widgets::StatusTone::Pending),
            }
            if widgets::action_button(ui, "Run Doctor", widgets::ActionStyle::Primary, !running)
                .clicked()
            {
                action = Some(DoctorPageAction::RunScan);
            }
            if let Some(outcome) = displayed
                && widgets::action_button(ui, "Copy report", widgets::ActionStyle::Secondary, true)
                    .clicked()
            {
                let _ = clipboard.set_text(doctor_scan_report_text(outcome));
            }
        });
        ui.label(DOCTOR_READ_ONLY_NOTICE);
        match displayed {
            Some(outcome) => ui.weak(format!(
                "Last run: {}",
                format_unix_timestamp_utc(outcome.finished_at_unix_seconds)
            )),
            None => ui.weak("Last run: never"),
        };
        // The scan timestamp is retained; the repair timestamp is additional.
        if let Some(repaired_at) = repair_finished_at_unix_seconds {
            ui.weak(format!(
                "Last repair: {}",
                format_unix_timestamp_utc(repaired_at)
            ));
        }
        if running {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label(if displayed.is_some() {
                    "Re-checking… the previous result stays on screen until this finishes."
                } else {
                    "Checking…"
                });
            });
        }
    });

    let Some(outcome) = displayed else {
        ui.add_space(theme::SECTION_GAP);
        widgets::empty_state(
            ui,
            "No scan has run yet",
            "Run Doctor to check configuration, the mount root, source folders, the library, the catalogue database and recent installs. Nothing is changed.",
            None,
        );
        return action;
    };

    let scan = &outcome.scan;
    ui.add_space(theme::SECTION_GAP);
    ui.horizontal_wrapped(|ui| {
        for (severity, count) in scan.counts() {
            widgets::status_badge(
                ui,
                format!("{}: {count}", severity.label()),
                if count == 0 {
                    widgets::StatusTone::Pending
                } else {
                    doctor_severity_tone(severity)
                },
            );
        }
    });
    if scan.merged_duplicate_count > 0 {
        ui.weak(format!(
            "{} duplicate finding(s) reported by more than one check were merged.",
            scan.merged_duplicate_count
        ));
    }

    if let Some(outcome) = repair_result {
        ui.add_space(theme::SECTION_GAP);
        show_doctor_repair_result(ui, outcome);
    }

    if scan.is_healthy() {
        ui.add_space(theme::SECTION_GAP);
        widgets::banner(
            ui,
            "Healthy",
            "No problems detected by the available read-only checks.",
            widgets::StatusTone::Success,
        );
    }

    // Deliberately *not* a running draw-order counter: a compact group's
    // cards only exist on frames where that group is expanded, so a draw
    // counter would renumber every later card the moment one group opened
    // and hand it another card's expansion state. A finding's index in the
    // scan is fixed for as long as the scan is.
    let ordinals = DoctorFindingOrdinals::of(scan);

    if gamer_view {
        // Gamer View foregrounds what needs attention and summarises the rest.
        // A real scan can produce hundreds of informational findings; those are
        // counted exactly, summarised in one line, and kept fully reachable
        // behind "Technical details" - never silently dropped and never allowed
        // to bury the actionable findings.
        let mut info_count = 0usize;
        for (category, findings) in scan.by_category() {
            let actionable: Vec<&Finding> = findings
                .iter()
                .filter(|finding| finding.severity != DoctorSeverity::Info)
                .copied()
                .collect();
            info_count += findings.len() - actionable.len();
            if actionable.is_empty() {
                continue;
            }
            show_doctor_category_group(ui, category, &actionable, selected, &mut action, &ordinals);
        }
        if info_count > 0 {
            ui.add_space(theme::SECTION_GAP);
            widgets::banner(
                ui,
                &format!("{info_count} checks are informational or healthy"),
                "None of these need attention. The exported report keeps every detail, and the \
                 full list is one disclosure away.",
                widgets::StatusTone::Info,
            );
            widgets::technical_details(ui, "doctor-info-findings", |ui| {
                for (category, findings) in scan.by_category() {
                    let informational: Vec<&Finding> = findings
                        .iter()
                        .filter(|finding| finding.severity == DoctorSeverity::Info)
                        .copied()
                        .collect();
                    if informational.is_empty() {
                        continue;
                    }
                    show_doctor_category_group(
                        ui,
                        category,
                        &informational,
                        selected,
                        &mut action,
                        &ordinals,
                    );
                }
            });
        }
    } else {
        for (category, findings) in scan.by_category() {
            show_doctor_category_group(ui, category, &findings, selected, &mut action, &ordinals);
        }
    }

    ui.add_space(theme::SECTION_GAP);
    show_doctor_coverage(ui, scan);
    action
}

/// One category's findings inside a collapsible section, shared by both view
/// modes so the card rendering is identical wherever it appears.
fn show_doctor_category_group(
    ui: &mut egui::Ui,
    category: DoctorCategory,
    findings: &[&Finding],
    selected: &mut Option<String>,
    action: &mut Option<DoctorPageAction>,
    ordinals: &DoctorFindingOrdinals,
) {
    ui.add_space(theme::SECTION_GAP);
    egui::CollapsingHeader::new(format!("{} ({})", category.label(), findings.len()))
        .id_salt(("doctor-category", category.label()))
        .default_open(true)
        .show(ui, |ui| {
            for repeated in doctor_presentation_groups(findings) {
                if repeated_doctor_group_is_compact(&repeated) {
                    show_repeated_doctor_group(ui, &repeated, selected, action, ordinals);
                } else {
                    for finding in repeated {
                        show_doctor_finding_card(ui, finding, selected, action, ordinals);
                        ui.add_space(6.0);
                    }
                }
                ui.add_space(6.0);
            }
        });
}

const DOCTOR_REPEATED_GROUP_EXAMPLES: usize = 10;

fn doctor_presentation_groups<'a>(findings: &[&'a Finding]) -> Vec<Vec<&'a Finding>> {
    let mut positions = HashMap::<&str, usize>::new();
    let mut groups = Vec::<Vec<&Finding>>::new();
    for finding in findings {
        if let Some(position) = positions.get(finding.id.as_str()).copied() {
            groups[position].push(*finding);
        } else {
            positions.insert(finding.id.as_str(), groups.len());
            groups.push(vec![*finding]);
        }
    }
    groups
}

fn repeated_doctor_group_is_compact(findings: &[&Finding]) -> bool {
    findings.len() > DOCTOR_REPEATED_GROUP_EXAMPLES
        && findings.first().is_some_and(|finding| {
            matches!(
                finding.id.as_str(),
                "mounts.historical_failure"
                    | "mounts.not_required"
                    | "mounts.failure_evidence_incomplete"
            )
        })
}

fn repeated_doctor_group_heading(finding: &Finding, count: usize) -> String {
    match finding.id.as_str() {
        "mounts.historical_failure" => format!("Historical mount failures: {count}"),
        "mounts.not_required" => format!("{count} loose ROMs are healthy"),
        "mounts.failure_evidence_incomplete" => {
            format!("Mount results with insufficient evidence: {count}")
        }
        _ => format!("{}: {count}", finding.title),
    }
}

/// The friendly plain-language line shown for a compact repeated group, if it
/// has one. Technical detail stays in the individual findings and the "Show
/// all" expansion.
fn repeated_doctor_group_explanation(finding: &Finding) -> Option<&'static str> {
    match finding.id.as_str() {
        "mounts.not_required" => Some("These games can be used directly. Nothing needs fixing."),
        "mounts.historical_failure" => Some(
            "These were mount problems in the past. They are shown for reference; nothing is \
             broken right now.",
        ),
        "mounts.failure_evidence_incomplete" => Some(
            "Some earlier mount results did not record enough detail to be certain. They are \
             kept rather than guessed at.",
        ),
        _ => None,
    }
}

fn repeated_doctor_group_counts(findings: &[&Finding], key: &str) -> String {
    let mut counts = BTreeMap::<String, usize>::new();
    for finding in findings {
        if let Some(value) = finding.measurements.get(key) {
            *counts.entry(value.to_string()).or_default() += 1;
        }
    }
    counts
        .into_iter()
        .map(|(value, count)| format!("{value}: {count}"))
        .collect::<Vec<_>>()
        .join(", ")
}

/// A key that identifies one *rendered* finding card uniquely and stably.
///
/// `Finding::id` names the finding's **kind**, not the occurrence:
/// `doctor_presentation_groups` exists precisely because a real scan
/// produces hundreds of findings sharing one id (`library.unknown_platform`,
/// `mounts.not_required`, ...). Using that id as the expansion key meant
/// every card of a kind shared one piece of state, so "Details" on one card
/// expanded all of them - and every one of those cards then built its
/// "Measured values" disclosure with the *same* egui widget id. egui
/// resolved that clash by reporting "First use of widget ID …" over the
/// header and letting each colliding widget overwrite the previous one's
/// state within the frame, which is why clicking the triangle looked
/// completely inert.
///
/// The ordinal supplies the missing uniqueness. It is stable for as long as
/// a scan result is on screen, which is exactly as long as the expansion
/// state should survive; a new scan re-numbers, and the selection is
/// re-validated against the new findings when that happens.
fn doctor_finding_key(finding: &Finding, ordinal: usize) -> String {
    format!("{}#{ordinal}", finding.id)
}

/// Each finding's index in the scan that produced it.
///
/// Keyed by address rather than by content because two findings of the same
/// kind can legitimately carry identical content - and because the addresses
/// are those of the scan's own `findings` elements, which live as long as the
/// scan does. Nothing is ever dereferenced through these keys.
struct DoctorFindingOrdinals(HashMap<*const Finding, usize>);

impl DoctorFindingOrdinals {
    fn of(scan: &DoctorScan) -> Self {
        Self(
            scan.findings
                .iter()
                .enumerate()
                .map(|(index, finding)| (std::ptr::from_ref(finding), index))
                .collect(),
        )
    }

    /// A finding not drawn from this scan cannot collide with one that was,
    /// because no real index reaches `usize::MAX`.
    fn ordinal(&self, finding: &Finding) -> usize {
        self.0
            .get(&std::ptr::from_ref(finding))
            .copied()
            .unwrap_or(usize::MAX)
    }
}

/// The `Finding::id` part of a key built by `doctor_finding_key`.
///
/// The stored selection is a key, but the two places that invalidate it
/// (a fresh scan, and a completed repair) reason about finding *kinds*, so
/// they compare on this.
fn doctor_finding_key_id(key: &str) -> &str {
    key.rsplit_once('#').map_or(key, |(id, _)| id)
}

fn show_repeated_doctor_group(
    ui: &mut egui::Ui,
    findings: &[&Finding],
    selected: &mut Option<String>,
    action: &mut Option<DoctorPageAction>,
    ordinals: &DoctorFindingOrdinals,
) {
    let Some(first) = findings.first() else {
        return;
    };
    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            widgets::status_badge(
                ui,
                first.severity.label(),
                doctor_severity_tone(first.severity),
            );
            ui.label(
                egui::RichText::new(repeated_doctor_group_heading(first, findings.len())).strong(),
            );
        });
        ui.add(
            egui::Label::new(
                repeated_doctor_group_explanation(first).unwrap_or(&first.explanation),
            )
            .wrap(),
        );
        egui::CollapsingHeader::new("Show examples")
            .id_salt(("doctor-repeated-examples", first.id.as_str()))
            .default_open(false)
            .show(ui, |ui| {
                ui.strong(format!(
                    "First {} of {}",
                    DOCTOR_REPEATED_GROUP_EXAMPLES,
                    findings.len()
                ));
                for finding in findings.iter().take(DOCTOR_REPEATED_GROUP_EXAMPLES) {
                    if let Some(affected) = &finding.affected {
                        ui.add(egui::Label::new(format!("• {}", affected.display)).wrap());
                    }
                }
            });
        egui::CollapsingHeader::new("Show details")
            .id_salt(("doctor-repeated-details", first.id.as_str()))
            .default_open(false)
            .show(ui, |ui| {
                for (label, key) in [
                    ("By reason", "reason"),
                    ("By platform", "platform"),
                    ("By media kind", "media_kind"),
                    ("By evidence", "mount_failure_scope"),
                ] {
                    let counts = repeated_doctor_group_counts(findings, key);
                    if !counts.is_empty() {
                        ui.label(format!("{label}: {counts}"));
                    }
                }
                egui::CollapsingHeader::new(format!("Show all {} findings", findings.len()))
                    .id_salt(("doctor-repeated-group", first.id.as_str()))
                    .default_open(false)
                    .show(ui, |ui| {
                        for finding in findings {
                            show_doctor_finding_card(ui, finding, selected, action, ordinals);
                            ui.add_space(6.0);
                        }
                    });
                ui.weak(
                    "Copy report exports every underlying finding; grouping changes presentation only.",
                );
            });
    });
}

fn show_doctor_finding_card(
    ui: &mut egui::Ui,
    finding: &Finding,
    selected: &mut Option<String>,
    action: &mut Option<DoctorPageAction>,
    ordinals: &DoctorFindingOrdinals,
) {
    // This card's own key, not its kind's - two findings sharing an id must
    // open and close independently.
    let key = doctor_finding_key(finding, ordinals.ordinal(finding));
    let is_selected = selected.as_deref() == Some(key.as_str());
    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            widgets::status_badge(
                ui,
                finding.severity.label(),
                doctor_severity_tone(finding.severity),
            );
            ui.label(egui::RichText::new(&finding.title).strong());
        });
        ui.add(egui::Label::new(&finding.explanation).wrap());
        if let Some(affected) = &finding.affected {
            ui.add(egui::Label::new(format!("Resource: {}", affected.display)).wrap());
            if affected.lossy {
                ui.weak(
                    "This path contains bytes that are not valid text, so it is shown approximately.",
                );
            }
        }
        if widgets::action_button(
            ui,
            if is_selected {
                "Hide details"
            } else {
                "Details"
            },
            widgets::ActionStyle::Quiet,
            true,
        )
        .clicked()
        {
            *selected = if is_selected { None } else { Some(key.clone()) };
        }
        if let Some(repair) = finding.offered_repair() {
            ui.horizontal_wrapped(|ui| {
                widgets::status_badge(ui, "Repair available", widgets::StatusTone::Active);
                ui.label(repair.title);
                widgets::status_badge(
                    ui,
                    match repair.risk {
                        archivefs_core::diagnostics::repair::DoctorRepairRisk::Safe => {
                            "Safe · confirmation required"
                        }
                        archivefs_core::diagnostics::repair::DoctorRepairRisk::NeedsConfirmation => {
                            "Changes real state · confirmation required"
                        }
                    },
                    widgets::StatusTone::Warning,
                );
            });
            if widgets::action_button(ui, "Review repair", widgets::ActionStyle::Secondary, true)
                .clicked()
            {
                *action = Some(DoctorPageAction::ReviewRepair {
                    action: repair.action,
                    finding_id: finding.id.clone(),
                    affected: finding.affected.as_ref().map(|path| path.display.clone()),
                });
            }
        }
        if is_selected {
            show_doctor_finding_details(ui, finding, &key);
        }
    });
}

/// The confirmation screen. The only route to executing a repair, and it
/// states every fact the milestone requires before a person approves.
fn show_doctor_repair_review(
    ui: &mut egui::Ui,
    review: &DoctorRepairReview,
) -> Option<DoctorPageAction> {
    let mut action = None;
    let spec = review.action.spec();
    widgets::card(ui, |ui| {
        ui.label(
            egui::RichText::new("Review this repair")
                .size(17.0)
                .strong(),
        );
        ui.add_space(6.0);
        ui.add(egui::Label::new(format!("Finding: {}", review.finding_title)).wrap());
        match &review.affected {
            Some(affected) => {
                ui.add(egui::Label::new(format!("Affected resource: {affected}")).wrap());
            }
            None => {
                ui.label("Affected resource: this EmuWiz installation");
            }
        }
        ui.add_space(6.0);
        ui.label(egui::RichText::new("Repair").strong());
        ui.add(egui::Label::new(spec.title).wrap());
        ui.weak(format!("Runs the existing {}", spec.invokes));

        ui.add_space(6.0);
        ui.label(egui::RichText::new("Exactly what will change").strong());
        ui.add(egui::Label::new(spec.expected_mutation).wrap());
        if spec.performs_library_scan {
            widgets::banner(
                ui,
                "This rescans your library",
                "As part of its existing implementation, this repair scans every configured source folder. Nothing in your library is modified, but on a large library it can take a while.",
                widgets::StatusTone::Warning,
            );
        }

        ui.add_space(6.0);
        ui.label(egui::RichText::new("What will not be touched").strong());
        ui.add(egui::Label::new(spec.never_touches).wrap());

        if !review.evidence.is_empty() {
            ui.add_space(6.0);
            ui.label(egui::RichText::new("Evidence for this repair").strong());
            for item in &review.evidence {
                ui.add(egui::Label::new(format!("• {item}")).wrap());
            }
        }

        ui.add_space(6.0);
        ui.label(egui::RichText::new("Afterwards").strong());
        ui.add(egui::Label::new(spec.verification).wrap());
        ui.add(egui::Label::new(format!("Undo: {}", spec.undo.label())).wrap());

        ui.add_space(8.0);
        ui.horizontal_wrapped(|ui| {
            if widgets::action_button(ui, "Cancel", widgets::ActionStyle::Quiet, true).clicked() {
                action = Some(DoctorPageAction::CancelRepair);
            }
            if widgets::action_button(ui, "Confirm repair", widgets::ActionStyle::Primary, true)
                .clicked()
            {
                action = Some(DoctorPageAction::ConfirmRepair);
            }
        });
    });
    action
}

/// What one repair attempt did, including when it did not work.
fn show_doctor_repair_result(ui: &mut egui::Ui, outcome: &DoctorRepairOutcome) {
    let record = &outcome.record;
    let (title, tone) = match record.status {
        DoctorRepairStatus::Succeeded => match record.verification {
            DoctorRepairVerification::Verified => ("Repair verified", widgets::StatusTone::Success),
            DoctorRepairVerification::FindingRemains => (
                "Repair completed but finding remains",
                widgets::StatusTone::Warning,
            ),
            DoctorRepairVerification::CouldNotComplete => (
                "Verification could not complete",
                widgets::StatusTone::Warning,
            ),
            DoctorRepairVerification::NotAttempted => {
                ("Repair completed", widgets::StatusTone::Info)
            }
        },
        DoctorRepairStatus::Failed => (
            "Repair failed and state was preserved",
            widgets::StatusTone::Blocked,
        ),
        DoctorRepairStatus::Rejected => {
            // A refusal because the issue disappeared before repair is not a
            // failure on the user's part. The exact reason still travels in
            // the record's summary, which is kept below and in History & Logs.
            if record.rejection == Some(DoctorRepairRejection::StaleFinding) {
                ("Nothing needed changing", widgets::StatusTone::Info)
            } else {
                (
                    "Repair was refused and nothing was changed",
                    widgets::StatusTone::Blocked,
                )
            }
        }
        DoctorRepairStatus::DryRun => ("Validated only", widgets::StatusTone::Info),
    };
    widgets::banner(ui, title, &record.summary, tone);
    widgets::card(ui, |ui| {
        ui.label(format!("Repair: {}", record.action_title));
        if let Some(affected) = &record.affected {
            ui.add(egui::Label::new(format!("Resource: {}", affected.display)).wrap());
        }
        if record.changed_paths.is_empty() {
            ui.label("Nothing was changed on disk.");
        } else {
            ui.label(egui::RichText::new("Changed on disk").strong());
            for path in &record.changed_paths {
                ui.add(egui::Label::new(format!("• {}", path.display)).wrap());
            }
        }
        ui.label(format!("Undo: {}", record.undo.label()));
        if let Some(error) = &record.error {
            ui.add(egui::Label::new(format!("Error: {error}")).wrap());
        }
        ui.weak("This attempt was recorded in History & Logs.");
    });
}

/// Shown in place of the disclosure when a finding measured nothing.
const DOCTOR_NO_MEASURED_VALUES: &str = "No measured values recorded";

/// The selected finding's evidence and provenance. Everything here is
/// observed fact or existing guidance prose - no invented advice, and no
/// control that could change anything.
fn show_doctor_finding_details(ui: &mut egui::Ui, finding: &Finding, key: &str) {
    ui.add_space(6.0);
    ui.separator();
    if let Some(why) = &finding.why_it_matters {
        ui.label(egui::RichText::new("Why it matters").strong());
        ui.add(egui::Label::new(why).wrap());
    }
    if let Some(next) = &finding.next_step {
        ui.label(egui::RichText::new("Recommended next step").strong());
        ui.add(egui::Label::new(next).wrap());
    }
    if !finding.evidence.is_empty() {
        // Evidence (paths, hashes, raw reasons) is already gated behind the
        // finding's own "Details"/"Hide details" selection, so it stays
        // visible exactly when the user asked to see it.
        ui.label(egui::RichText::new("Evidence").strong());
        for item in &finding.evidence {
            ui.add(egui::Label::new(format!("• {item}")).wrap());
        }
    }
    if finding.measurements.is_empty() {
        // Plain text, not a header: a disclosure triangle that opens onto
        // nothing is a control that lies about having something behind it.
        ui.weak(DOCTOR_NO_MEASURED_VALUES);
    } else {
        // The same facts as the evidence above, as values. Shown collapsed so
        // the prose stays the primary account for a person reading this.
        //
        // Salted with this card's unique key, never with `finding.id` alone:
        // a scan repeats an id across hundreds of findings, and salting on it
        // gave every one of their headers the same egui widget id. egui
        // flagged that clash on screen ("First use of widget ID …") and the
        // colliding widgets overwrote each other's open/closed state within
        // the frame, so the triangle never appeared to respond.
        //
        // `CollapsingHeader` is a real button: it carries egui's own keyboard
        // focus, Enter/Space activation and accessibility node. Nothing here
        // paints a triangle by hand.
        egui::CollapsingHeader::new("Measured values")
            .id_salt(format!("doctor-measurements-{key}"))
            .default_open(false)
            .show(ui, |ui| {
                for (name, value) in &finding.measurements {
                    ui.label(format!("{name}: {value}"));
                }
            });
    }
    if let Some(recovery) = &finding.recovery {
        // Informational only. Stage 1A deliberately renders no button here:
        // exposing these safely needs confirmation and post-repair
        // verification, which is Stage 1B's job.
        ui.add_space(4.0);
        ui.add(egui::Label::new(recovery.notice()).wrap());
    }
    ui.add_space(4.0);
    ui.weak(format!(
        "Reported by {} · finding ID {}",
        finding.subsystem.label(),
        finding.id
    ));
}

/// What this scan actually covered, what it could not, and what EmuWiz
/// does not check at all yet. Without this a clean result would read as
/// "everything is fine", which would be untrue.
fn show_doctor_coverage(ui: &mut egui::Ui, scan: &DoctorScan) {
    egui::CollapsingHeader::new("What was checked")
        .id_salt("doctor-coverage")
        .default_open(scan.is_healthy())
        .show(ui, |ui| {
            let checked = scan.checked_subsystems();
            if checked.is_empty() {
                ui.label("Nothing could be checked in this run.");
            } else {
                for entry in checked {
                    ui.label(format!(
                        "Checked: {} ({})",
                        entry.category.label(),
                        entry.subsystem.label()
                    ));
                }
            }
            let unavailable = scan.unavailable_subsystems();
            if !unavailable.is_empty() {
                ui.add_space(6.0);
                ui.label(egui::RichText::new("Not checked in this run").strong());
                for entry in unavailable {
                    let reason = match &entry.status {
                        CoverageStatus::Unavailable { reason } => reason.as_str(),
                        CoverageStatus::Checked => "",
                    };
                    ui.add(
                        egui::Label::new(format!("{}: {reason}", entry.category.label())).wrap(),
                    );
                }
            }
            ui.add_space(6.0);
            ui.label(egui::RichText::new("Not checked by EmuWiz yet").strong());
            ui.weak(
                "These are not covered by the result above, so a healthy result does not mean they are fine.",
            );
            for deferred in scan.deferred {
                ui.add(egui::Label::new(format!("{}: {}", deferred.name, deferred.reason)).wrap());
            }
        });
}

fn doctor_severity_tone(severity: DoctorSeverity) -> widgets::StatusTone {
    match severity {
        DoctorSeverity::Critical | DoctorSeverity::Error => widgets::StatusTone::Blocked,
        DoctorSeverity::Warning => widgets::StatusTone::Warning,
        DoctorSeverity::Info => widgets::StatusTone::Info,
        DoctorSeverity::Healthy => widgets::StatusTone::Success,
    }
}

/// The History detail line for one repair attempt.
///
/// Records everything the milestone requires that `HistoryEntry` itself has
/// no column for - action id, finding id, confirmation, verification, changed
/// paths, undo availability and any error - as one structured line, rather
/// than adding a database migration to store it.
fn doctor_repair_history_detail(outcome: &DoctorRepairOutcome) -> String {
    let record = &outcome.record;
    let mut parts = vec![
        format!("action={}", record.action_id),
        format!("finding={}", record.finding_id),
        format!("confirmed={}", record.confirmed),
        format!("dry_run={}", record.dry_run),
        format!("result={:?}", record.status),
        format!("verification={}", record.verification.label()),
        format!("undo={}", record.undo.label()),
    ];
    if let Some(affected) = &record.affected {
        parts.push(format!("resource={}", affected.display));
    }
    if !record.changed_paths.is_empty() {
        parts.push(format!(
            "changed=[{}]",
            record
                .changed_paths
                .iter()
                .map(|path| path.display.clone())
                .collect::<Vec<_>>()
                .join(", ")
        ));
    }
    if let Some(rejection) = &record.rejection {
        parts.push(format!("refused={rejection:?}"));
    }
    if let Some(error) = &record.error {
        parts.push(format!("error={error}"));
    }
    format!("{} | {}", record.summary, parts.join(" "))
}

/// The exact statement shown on the Doctor page, kept as one constant so the
/// GUI and its tests cannot drift.
const DOCTOR_READ_ONLY_NOTICE: &str = "This scan is read-only: it inspects configuration, existing files and existing records only. It never creates, mounts, unmounts, repairs, rebuilds or removes anything. Free space and write access are read from the filesystem itself - no test file is ever written, and your emulator profiles, cheats and patches are never modified.";

/// Plain-text form of a scan, for "Copy report".
fn doctor_scan_report_text(outcome: &DoctorScanOutcome) -> String {
    let scan = &outcome.scan;
    let mut lines = vec![
        "EmuWiz Doctor - read-only diagnostic scan".to_string(),
        format!(
            "Last run: {}",
            format_unix_timestamp_utc(outcome.finished_at_unix_seconds)
        ),
        scan.counts()
            .iter()
            .map(|(severity, count)| format!("{}: {count}", severity.label()))
            .collect::<Vec<_>>()
            .join("  "),
        String::new(),
    ];
    if scan.is_healthy() {
        lines.push("No problems detected by the available read-only checks.".to_string());
        lines.push(String::new());
    }
    for (category, findings) in scan.by_category() {
        lines.push(format!("{} ({})", category.label(), findings.len()));
        for finding in findings {
            lines.push(format!(
                "  [{}] {} - {}",
                finding.severity.label().to_lowercase(),
                finding.id,
                finding.title
            ));
            lines.push(format!("      {}", finding.explanation));
            if let Some(affected) = &finding.affected {
                lines.push(format!("      Resource: {}", affected.display));
            }
            if let Some(why) = &finding.why_it_matters {
                lines.push(format!("      Why it matters: {why}"));
            }
            if let Some(next) = &finding.next_step {
                lines.push(format!("      Next step: {next}"));
            }
            for item in &finding.evidence {
                lines.push(format!("      Evidence: {item}"));
            }
            for (key, value) in &finding.measurements {
                lines.push(format!("      Measured: {key} = {value}"));
            }
            lines.push(format!("      Reported by: {}", finding.subsystem.label()));
        }
        lines.push(String::new());
    }
    lines.push("Checked:".to_string());
    for entry in scan.checked_subsystems() {
        lines.push(format!(
            "  {} ({})",
            entry.category.label(),
            entry.subsystem.label()
        ));
    }
    for entry in scan.unavailable_subsystems() {
        let reason = match &entry.status {
            CoverageStatus::Unavailable { reason } => reason.as_str(),
            CoverageStatus::Checked => "",
        };
        lines.push(format!(
            "  Not checked: {} - {reason}",
            entry.category.label()
        ));
    }
    lines.push(String::new());
    lines.push("Not checked by EmuWiz yet:".to_string());
    for deferred in scan.deferred {
        lines.push(format!("  {} - {}", deferred.name, deferred.reason));
    }
    lines.join("\n")
}

fn doctor_summary_text(report: &DoctorReport) -> String {
    let passed = report
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Pass)
        .count();
    let warnings = report
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Warn)
        .count();
    let failed = report
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Fail)
        .count();
    format!(
        "{} checks: {passed} passed, {warnings} warnings, {failed} failed · \
         {} archives ({} mounted, {} pending, {} unknown platform)",
        report.checks.len(),
        report.archives_found,
        report.mounted_archives,
        report.pending_archives,
        report.archives_unknown_platform
    )
}

/// The full-report text behind the Doctor page's "Copy Report" - the
/// design's copy-full-details affordance. Plain text, one check per
/// line, so it pastes cleanly into an issue or support request. The
/// design's per-check "Suggested fix" is deliberately absent:
/// `DoctorCheck` carries no suggestion field today, and inventing fixes
/// in the GUI would be untruthful (see the capability matrix's Doctor
/// "Suggested action" row).
fn doctor_report_text(report: &DoctorReport) -> String {
    let mut lines = vec![
        format!("EmuWiz doctor report"),
        format!("Config: {}", report.config_path.display()),
        doctor_summary_text(report),
        String::new(),
    ];
    for check in &report.checks {
        lines.push(format!(
            "[{}] {} — {}",
            check.status, check.name, check.detail
        ));
    }
    if !report.platform_counts.is_empty() {
        lines.push(String::new());
        lines.push("Platform counts:".to_string());
        for (platform, count) in &report.platform_counts {
            lines.push(format!("  {platform}: {count}"));
        }
    }
    lines.join("\n")
}

fn show_doctor_checks_panel(ui: &mut egui::Ui, doctor: Option<&DoctorReport>) {
    let Some(doctor) = doctor else {
        widgets::empty_state(
            ui,
            "Health checks unavailable",
            "Scan the library before running the full EmuWiz health report.",
            None,
        );
        return;
    };
    for status in [DoctorStatus::Fail, DoctorStatus::Warn] {
        for check in doctor.checks.iter().filter(|check| check.status == status) {
            widgets::card(ui, |ui| {
                ui.horizontal_wrapped(|ui| {
                    widgets::status_badge(
                        ui,
                        check.status.to_string(),
                        if status == DoctorStatus::Fail {
                            widgets::StatusTone::Blocked
                        } else {
                            widgets::StatusTone::Warning
                        },
                    );
                    ui.label(egui::RichText::new(&check.name).strong());
                });
                ui.add(egui::Label::new(&check.detail).wrap());
            });
            ui.add_space(6.0);
        }
    }
    let passed = doctor
        .checks
        .iter()
        .filter(|check| check.status == DoctorStatus::Pass)
        .count();
    egui::CollapsingHeader::new(format!("Passed checks ({passed})"))
        .default_open(false)
        .show(ui, |ui| {
            for check in doctor
                .checks
                .iter()
                .filter(|check| check.status == DoctorStatus::Pass)
            {
                ui.horizontal_wrapped(|ui| {
                    widgets::status_badge(ui, "Pass", widgets::StatusTone::Success);
                    ui.strong(&check.name);
                    ui.label(egui::RichText::new(&check.detail).color(theme::muted(ui)));
                });
            }
        });
}

const INSPECTOR_DETAILS_COLUMN_WIDTH: f32 = 300.0;

/// Whether one entry matches the Archive Inspector's current search text
/// (case-insensitive substring against its exact stored name) and
/// classification filter - pure, so it is directly testable without
/// rendering anything, mirroring `health_issue_matches`'s existing
/// convention in this file.
fn inspector_entry_matches(
    entry: &InspectorEntry,
    search_lower: &str,
    classification_filter: Option<InspectorEntryClassification>,
) -> bool {
    if let Some(filter) = classification_filter
        && entry.classification != filter
    {
        return false;
    }
    search_lower.is_empty() || entry.name.to_lowercase().contains(search_lower)
}

/// Filters and sorts the already-inspected entry list without ever
/// mutating it - `entries` is only ever read here, exactly like
/// `visible_health_issue_indices` reads its own `issues` slice.
fn visible_inspector_entry_indices(
    entries: &[InspectorEntry],
    search: &str,
    classification_filter: Option<InspectorEntryClassification>,
    sort_field: InspectorSortField,
    sort_ascending: bool,
) -> Vec<usize> {
    let search_lower = search.trim().to_lowercase();
    let mut indices: Vec<usize> = entries
        .iter()
        .enumerate()
        .filter_map(|(index, entry)| {
            inspector_entry_matches(entry, &search_lower, classification_filter).then_some(index)
        })
        .collect();
    indices.sort_by(|&left, &right| {
        let (left_entry, right_entry) = (&entries[left], &entries[right]);
        let ordering = match sort_field {
            InspectorSortField::Path => left_entry.name.cmp(&right_entry.name),
            InspectorSortField::Size => left_entry
                .uncompressed_size
                .cmp(&right_entry.uncompressed_size),
            InspectorSortField::Classification => {
                left_entry.classification.cmp(&right_entry.classification)
            }
        }
        .then_with(|| left_entry.name.cmp(&right_entry.name));
        if sort_ascending {
            ordering
        } else {
            ordering.reverse()
        }
    });
    indices
}
fn inspector_entry_details_text(entry: &InspectorEntry) -> String {
    match entry.kind {
        InspectorEntryKind::Directory => "Directory".to_string(),
        InspectorEntryKind::File => format!(
            "{} \u{2014} {} \u{2014} compressed {} \u{2014} {}",
            entry.classification.label(),
            format_size(Some(entry.uncompressed_size)),
            format_size(entry.compressed_size),
            entry.compression_method.as_deref().unwrap_or("Unknown"),
        ),
    }
}

/// Renders one Archive Inspector entry row - the same technique
/// `show_data_row` uses for the Library table (a single `Sense::click()`
/// region with `Painter`-painted cell text, never a child widget inside
/// that region), generalised to two columns via the same now-slice-based
/// `cell_index_at`/`hovered_cell_full_text` helpers the Library table
/// itself uses. Selection here is single (`selected: bool`, no
/// multi-select/Ctrl-click) - "Selecting one entry shows its complete
/// details" never needed the Library table's fuller multi-select model.
fn show_inspector_row(
    ui: &mut egui::Ui,
    entry: &InspectorEntry,
    row_height: f32,
    selected: bool,
    widths: &[f32],
) -> egui::Response {
    let spacing = ui.spacing().item_spacing.x;
    let width = widths.iter().sum::<f32>() + spacing * (widths.len().saturating_sub(1) as f32);
    let (_, rect) = ui.allocate_space(egui::vec2(width, row_height));
    let row_id = egui::Id::new("inspector_row").with(&entry.name);
    let mut response = ui.interact(rect, row_id, egui::Sense::click());

    let visuals = ui.visuals();
    if selected {
        ui.painter()
            .rect_filled(rect, 0.0, visuals.selection.bg_fill);
    } else if response.hovered() {
        ui.painter()
            .rect_filled(rect, 0.0, visuals.widgets.hovered.weak_bg_fill);
    }

    let details_text = inspector_entry_details_text(entry);
    let cells: [&str; 2] = [entry.name.as_str(), details_text.as_str()];
    let font_id = egui::TextStyle::Body.resolve(ui.style());
    let color = ui.visuals().text_color();
    let mut x = rect.left();
    for (text, column_width) in cells.iter().zip(widths.iter().copied()) {
        let cell_rect = egui::Rect::from_min_size(
            egui::pos2(x, rect.top()),
            egui::vec2(column_width, row_height),
        );
        ui.painter().with_clip_rect(cell_rect).text(
            egui::pos2(x + 2.0, rect.center().y),
            egui::Align2::LEFT_CENTER,
            *text,
            font_id.clone(),
            color,
        );
        x += column_width + spacing;
    }

    let pointer_x = response.hover_pos().map(|pos| pos.x);
    if let Some(full_text) =
        hovered_cell_full_text(pointer_x, rect.left(), &cells, widths, spacing, |text| {
            ui.fonts_mut(|fonts| {
                fonts
                    .layout_no_wrap(text.to_string(), font_id.clone(), color)
                    .size()
                    .x
            })
        })
    {
        response = response.on_hover_text(full_text.to_string());
    }

    response
}
fn show_archive_inspector_panel(
    ui: &mut egui::Ui,
    state: &mut ArchiveInspectorState,
    clipboard: &mut dyn ClipboardBackend,
) -> bool {
    let close = show_tools_overlay_header(ui, "Archive Inspector");
    ui.horizontal(|ui| {
        ui.label("Archive:");
        let path_text = state.archive_path.display().to_string();
        ui.add(egui::Label::new(&path_text).selectable(true).wrap());
        if ui.small_button("Copy").clicked() {
            let _ = clipboard.set_text(path_text.clone());
        }
    });
    ui.add_space(4.0);

    match &state.status {
        ArchiveInspectorStatus::Loading { .. } => {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Inspecting archive - this runs in the background.");
            });
            return close;
        }
        ArchiveInspectorStatus::Error(message) => {
            ui.colored_label(ui.visuals().error_fg_color, message);
            return close;
        }
        ArchiveInspectorStatus::Ready(_) => {}
    }
    let ArchiveInspectorStatus::Ready(report) = &state.status else {
        unreachable!("every other status already returned above");
    };

    if report.truncated {
        ui.colored_label(
            ui.visuals().warn_fg_color,
            format!(
                "Showing the first {} of {} entries - this view is incomplete. Use a more \
                 specific search to find a particular entry.",
                report.entries.len(),
                report.total_entries_in_archive
            ),
        );
        ui.add_space(2.0);
    }

    ui.horizontal_wrapped(|ui| {
        for classification in InspectorEntryClassification::ALL {
            let count = report
                .entries
                .iter()
                .filter(|entry| entry.classification == classification)
                .count();
            summary_value(ui, classification.label(), count);
        }
    });
    ui.separator();

    ui.horizontal_wrapped(|ui| {
        ui.label("Search path:");
        show_text_edit_with_context_menu(ui, &mut state.search, clipboard, |text_edit| {
            text_edit
                .id_salt("archivefs_inspector_search")
                .desired_width(260.0)
        });
        ui.label("Classification:");
        egui::ComboBox::from_id_salt("inspector_classification_filter")
            .selected_text(
                state
                    .classification_filter
                    .map(InspectorEntryClassification::label)
                    .unwrap_or("All"),
            )
            .show_ui(ui, |ui| {
                ui.selectable_value(&mut state.classification_filter, None, "All");
                for classification in InspectorEntryClassification::ALL {
                    ui.selectable_value(
                        &mut state.classification_filter,
                        Some(classification),
                        classification.label(),
                    );
                }
            });
        ui.label("Sort by:");
        egui::ComboBox::from_id_salt("inspector_sort_field")
            .selected_text(state.sort_field.to_string())
            .show_ui(ui, |ui| {
                for field in [
                    InspectorSortField::Path,
                    InspectorSortField::Size,
                    InspectorSortField::Classification,
                ] {
                    ui.selectable_value(&mut state.sort_field, field, field.to_string());
                }
            });
        ui.checkbox(&mut state.sort_ascending, "Ascending");
    });

    let visible = visible_inspector_entry_indices(
        &report.entries,
        &state.search,
        state.classification_filter,
        state.sort_field,
        state.sort_ascending,
    );
    ui.horizontal_wrapped(|ui| {
        summary_value(ui, "Entries shown", visible.len());
        summary_value(ui, "Total entries", report.entries.len());
    });
    ui.separator();

    if report.entries.is_empty() {
        ui.label("This archive has no entries.");
        return close;
    }
    if visible.is_empty() {
        ui.label("No entries match the current search/filter.");
        return close;
    }

    let row_height = ui
        .text_style_height(&egui::TextStyle::Body)
        .max(ui.spacing().interact_size.y);
    let spacing = ui.spacing().item_spacing.x;

    ui.strong("Entries");
    egui::ScrollArea::horizontal()
        .id_salt("inspector_entries_horizontal")
        .auto_shrink([false, false])
        .show(ui, |ui| {
            let start_of_frame_width = state.path_column_width;
            ui.set_min_width(start_of_frame_width + spacing + INSPECTOR_DETAILS_COLUMN_WIDTH);

            let mut path_header_rect = None;
            ui.horizontal(|ui| {
                let response = ui.add_sized(
                    [start_of_frame_width, row_height],
                    egui::Label::new(egui::RichText::new("Path").strong()),
                );
                path_header_rect = Some(response.rect);
                ui.add_sized(
                    [INSPECTOR_DETAILS_COLUMN_WIDTH, row_height],
                    egui::Label::new(egui::RichText::new("Details").strong()),
                );
            });
            if let Some(path_header_rect) = path_header_rect {
                let handle_rect = egui::Rect::from_min_size(
                    egui::pos2(
                        path_header_rect.right() - COLUMN_RESIZE_HANDLE_WIDTH,
                        path_header_rect.top(),
                    ),
                    egui::vec2(COLUMN_RESIZE_HANDLE_WIDTH, path_header_rect.height()),
                );
                show_column_resize_handle(
                    ui,
                    egui::Id::new("inspector_path_column_resize"),
                    handle_rect,
                    &mut state.path_column_width,
                );
            }
            ui.separator();

            // Re-read after the resize handle, which may have just
            // changed `state.path_column_width` this very frame - the
            // rows below must always paint with *this* frame's width,
            // never a one-frame-stale copy (matches the Library table's
            // identical fix in `show_loaded_data`).
            let widths = [state.path_column_width, INSPECTOR_DETAILS_COLUMN_WIDTH];

            let body_height = ui.available_height().max(row_height);
            egui::ScrollArea::vertical()
                .id_salt("inspector_entries_vertical")
                .max_height(body_height)
                .auto_shrink([false, false])
                .show_rows(ui, row_height, visible.len(), |ui, row_range| {
                    for visible_index in row_range {
                        let entry_index = visible[visible_index];
                        let entry = &report.entries[entry_index];
                        let selected = state.selected_entry.as_deref() == Some(entry.name.as_str());
                        let response = show_inspector_row(ui, entry, row_height, selected, &widths);
                        if response.clicked() {
                            state.selected_entry = Some(entry.name.clone());
                        }
                    }
                });
        });

    let Some(selected_name) = state.selected_entry.clone() else {
        ui.label("Select an entry to view its details.");
        return close;
    };
    let Some(selected_entry) = report
        .entries
        .iter()
        .find(|entry| entry.name == selected_name)
    else {
        return close;
    };

    ui.separator();
    ui.strong("Selected entry");
    egui::Grid::new("inspector_selected_entry_details")
        .num_columns(2)
        .striped(true)
        .show(ui, |ui| {
            detail_row_with_copy(ui, "Path", &selected_entry.name, clipboard);
            detail_row(
                ui,
                "Type",
                match selected_entry.kind {
                    InspectorEntryKind::File => "File",
                    InspectorEntryKind::Directory => "Directory",
                },
            );
            detail_row(ui, "Classification", selected_entry.classification.label());
            detail_row(
                ui,
                "Uncompressed size",
                &format_size(Some(selected_entry.uncompressed_size)),
            );
            detail_row(
                ui,
                "Compressed size",
                &format_size(selected_entry.compressed_size),
            );
            detail_row(
                ui,
                "Compression method",
                selected_entry
                    .compression_method
                    .as_deref()
                    .unwrap_or("Unknown"),
            );
        });

    close
}

/// The shared header every `ToolsOverlay` screen that doesn't already
/// provide its own dismiss action (unlike Diagnostics, whose own
/// `show_setup_diagnostics` already returns `Continue`/`ViewLastSnapshot`)
/// renders - a heading plus one "Back to Library" button. Returns `true`
/// exactly when that button was clicked, so the caller can close the
/// overlay.
///
/// Reviewed for the Library IA migration and deliberately left as-is:
/// despite the label, clicking it does not navigate anywhere - it only
/// clears `self.tools_overlay`, returning to whatever `view` was already
/// active (Mount, Settings, or anything else a Tools overlay can be
/// opened from, not only Library). The label predates the unified
/// Library shell and is a pre-existing minor inaccuracy for the
/// non-Library case, not something this migration introduced or should
/// fix in passing - changing its target to actually navigate to Library
/// would be a real, unrelated behaviour change for users who open a
/// Tools overlay from a non-Library page.
fn show_tools_overlay_header(ui: &mut egui::Ui, title: &str) -> bool {
    let mut close = false;
    ui.horizontal(|ui| {
        ui.heading(title);
        if ui.button("Back to Library").clicked() {
            close = true;
        }
    });
    ui.separator();
    close
}
fn source_action_log_category(action: &SourceAction) -> ActivityAction {
    match action {
        SourceAction::Add(_) => ActivityAction::SourceAdded,
        SourceAction::SetEnabled { enabled: true, .. } => ActivityAction::SourceEnabled,
        SourceAction::SetEnabled { enabled: false, .. } => ActivityAction::SourceDisabled,
        SourceAction::ScanOne(_) | SourceAction::ScanAll | SourceAction::AssignPlatform { .. } => {
            ActivityAction::SourceScan
        }
        SourceAction::Remove { .. } => ActivityAction::SourceRemoved,
    }
}

fn source_action_path(action: &SourceAction) -> Option<PathBuf> {
    match action {
        SourceAction::Add(path)
        | SourceAction::SetEnabled { path, .. }
        | SourceAction::ScanOne(path)
        | SourceAction::AssignPlatform { path, .. }
        | SourceAction::Remove { path, .. } => Some(path.clone()),
        SourceAction::ScanAll => None,
    }
}

fn source_action_started_message(action: &SourceAction) -> String {
    match action {
        SourceAction::Add(path) => format!("Adding source '{}'.", path.display()),
        SourceAction::SetEnabled {
            path,
            enabled: true,
        } => format!("Enabling source '{}'.", path.display()),
        SourceAction::SetEnabled {
            path,
            enabled: false,
        } => format!("Disabling source '{}'.", path.display()),
        SourceAction::ScanOne(path) => format!("Scanning source '{}'.", path.display()),
        SourceAction::ScanAll => "Scanning all enabled sources.".to_string(),
        SourceAction::AssignPlatform { path, platform } => format!(
            "Assigning {platform} to source '{}' and rescanning compatible entries.",
            path.display()
        ),
        SourceAction::Remove {
            path,
            keep_catalogue: true,
        } => format!(
            "Removing source '{}' (keeping catalogue entries).",
            path.display()
        ),
        SourceAction::Remove {
            path,
            keep_catalogue: false,
        } => format!(
            "Removing source '{}' and its catalogue entries.",
            path.display()
        ),
    }
}

fn source_action_success_message(outcome: &SourceActionOutcome) -> String {
    match outcome {
        SourceActionOutcome::Added(source) => format!(
            "Source added: {}. Use Scan to catalogue it.",
            source.path.display()
        ),
        SourceActionOutcome::SetEnabled(outcome) => match &outcome.scan {
            Some(scan) => format!(
                "Source enabled: {}. Scan found {} archive(s), {} missing.",
                outcome.source.path.display(),
                scan.counts.archives_seen,
                scan.counts.archives_missing
            ),
            None => format!(
                "Source disabled: {}. Catalogue entries were preserved.",
                outcome.source.path.display()
            ),
        },
        SourceActionOutcome::Scanned(summary) => {
            let succeeded = summary.counts.source_folders_scanned;
            let failed = summary.folder_errors.len();
            if failed == 0 {
                format!(
                    "Scan complete: {succeeded} source(s) scanned, {} archive(s) found, {} \
                     missing.",
                    summary.counts.archives_seen, summary.counts.archives_missing
                )
            } else {
                format!(
                    "Scan complete: {succeeded} source(s) succeeded, {failed} failed. Existing \
                     catalogue entries were preserved for the failed source(s)."
                )
            }
        }
        SourceActionOutcome::PlatformAssigned { platform, scan } => format!(
            "Source assigned {platform}. Rescan found {} item(s); compatible Unknown entries were reclassified. {} incompatible item(s) remained visible and Unknown.",
            scan.counts.archives_seen,
            scan.platform_assignment_warnings.len()
        ),
        SourceActionOutcome::Removed(outcome) => match outcome.catalogue_rows_removed {
            Some(count) => format!(
                "Source removed: {}. {count} catalogue row(s) removed.",
                outcome.removed_source.path.display()
            ),
            None => format!(
                "Source removed: {}. Catalogue entries were preserved.",
                outcome.removed_source.path.display()
            ),
        },
    }
}

/// Runs one [`SourceAction`] against the default config/database paths -
/// the production entry point `ArchiveFsApp::start_source_action` runs on
/// a background thread. Every arm calls straight into the same, already
/// tested `archivefs_core` function the CLI's matching `source`/`sources`
/// subcommand calls (see `crates/archivefs-cli/src/main.rs`'s `source
/// add`/`enable`/`disable`/`scan`/`sources scan-all`/`source remove`
/// handlers) - never a second implementation of validation, scanning, or
/// persistence.
fn run_source_action(action: &SourceAction) -> archivefs_core::Result<SourceActionOutcome> {
    match action {
        SourceAction::Add(path) => add_source_folder_default(path).map(SourceActionOutcome::Added),
        SourceAction::SetEnabled { path, enabled } => {
            set_source_folder_enabled_default(path, *enabled).map(SourceActionOutcome::SetEnabled)
        }
        SourceAction::ScanOne(path) => {
            scan_source_folder_default(path).map(SourceActionOutcome::Scanned)
        }
        SourceAction::ScanAll => {
            scan_all_enabled_sources_default().map(SourceActionOutcome::Scanned)
        }
        SourceAction::AssignPlatform { path, platform } => {
            assign_source_platform_default(path, platform).map(|scan| {
                SourceActionOutcome::PlatformAssigned {
                    platform: platform.clone(),
                    scan,
                }
            })
        }
        SourceAction::Remove {
            path,
            keep_catalogue,
        } => remove_source_folder_default(path, *keep_catalogue).map(SourceActionOutcome::Removed),
    }
}

fn run_bsfree_operation(
    operation: &BsFreeOperation,
) -> Result<BsFreeOperationResult, archivefs_core::patch_manager::BsFreeError> {
    let paths = BsFreePaths::at(default_bsfree_source_root()?);
    match operation {
        BsFreeOperation::LoadStatus => inspect_bsfree_source(&paths)
            .map(Box::new)
            .map(BsFreeOperationResult::Status),
        BsFreeOperation::Download => download_bsfree_database(
            &paths,
            &BsFreeDownloadOptions::default(),
            &HttpsCheatSourceTransport::new(),
        )
        .map(|result| BsFreeOperationResult::Status(Box::new(result.status))),
        BsFreeOperation::Import(source) => import_local_bsfree_database(&paths, source)
            .map(|result| BsFreeOperationResult::Status(Box::new(result.status))),
        BsFreeOperation::Validate => validate_installed_bsfree_source(&paths)
            .map(Box::new)
            .map(BsFreeOperationResult::Status),
        BsFreeOperation::SetEnabled(enabled) => set_bsfree_enabled(&paths, *enabled)
            .map(Box::new)
            .map(BsFreeOperationResult::Status),
        BsFreeOperation::Remove => {
            remove_local_bsfree_source(&paths, true)?;
            Ok(BsFreeOperationResult::Removed)
        }
        BsFreeOperation::Search(request) => BsFreeCatalogue::open_installed(&paths)?
            .search_games(request)
            .map(BsFreeOperationResult::Search),
        BsFreeOperation::LoadGame {
            upstream_uid,
            offset,
        } => {
            let catalogue = BsFreeCatalogue::open_installed(&paths)?;
            let game = catalogue.game(*upstream_uid)?.ok_or_else(|| {
                archivefs_core::patch_manager::BsFreeError {
                    kind: archivefs_core::patch_manager::BsFreeErrorKind::Query,
                    message: "BSFree game is no longer present".to_string(),
                }
            })?;
            let cheats = catalogue.cheats(*upstream_uid, PageRequest::cheats(*offset))?;
            Ok(BsFreeOperationResult::Game(game, cheats))
        }
    }
}

fn library_view_action_log_category(action: &LibraryViewAction) -> ActivityAction {
    match action {
        LibraryViewAction::Add { .. } => ActivityAction::LibraryViewAdded,
        LibraryViewAction::Edit { .. } => ActivityAction::LibraryViewEdited,
        LibraryViewAction::SetEnabled { enabled: true, .. } => ActivityAction::LibraryViewEnabled,
        LibraryViewAction::SetEnabled { enabled: false, .. } => ActivityAction::LibraryViewDisabled,
        LibraryViewAction::Preview(_) => ActivityAction::LibraryViewPreview,
        LibraryViewAction::Apply(_) => ActivityAction::LibraryViewApply,
        LibraryViewAction::Repair(_) => ActivityAction::LibraryViewRepair,
        LibraryViewAction::Remove { .. } => ActivityAction::LibraryViewRemoved,
    }
}

fn library_view_action_started_message(action: &LibraryViewAction) -> String {
    match action {
        LibraryViewAction::Add { name, .. } => format!("Adding library view '{name}'."),
        LibraryViewAction::Edit { name, .. } => format!("Saving changes to library view '{name}'."),
        LibraryViewAction::SetEnabled {
            identifier,
            enabled: true,
        } => format!("Enabling library view '{identifier}'."),
        LibraryViewAction::SetEnabled {
            identifier,
            enabled: false,
        } => format!("Disabling library view '{identifier}'."),
        LibraryViewAction::Preview(identifier) => {
            format!("Previewing library view '{identifier}'.")
        }
        LibraryViewAction::Apply(identifier) => format!("Applying library view '{identifier}'."),
        LibraryViewAction::Repair(identifier) => format!("Repairing library view '{identifier}'."),
        LibraryViewAction::Remove {
            identifier,
            keep_definition: true,
        } => format!(
            "Removing managed symlinks for library view '{identifier}' (keeping its definition)."
        ),
        LibraryViewAction::Remove {
            identifier,
            keep_definition: false,
        } => format!("Removing library view '{identifier}' and its managed symlinks."),
    }
}

/// Builds the Apply/Repair feedback message, including the current skip
/// count so a partial RomM result (unresolved platform mappings,
/// collisions) is never worded as a plain, unqualified success - see
/// `library_view_current_skip_count`. `skipped` is `None` only when the
/// post-apply re-preview itself could not run; the message still reports
/// the apply's own outcome truthfully in that case, it just cannot add a
/// skip count.
fn library_view_apply_summary_message(
    verb: &str,
    view_name: &str,
    report: &LibraryViewApplyReport,
    skipped: Option<usize>,
) -> String {
    let base = format!(
        "{verb} '{}': {} created, {} repaired, {} removed, {} unchanged, {} failed",
        view_name, report.created, report.repaired, report.removed, report.unchanged, report.failed
    );
    match skipped {
        Some(0) => format!("{base}, 0 skipped."),
        Some(skipped) => format!(
            "{base}, {skipped} skipped - this view is not fully applied. Unresolved platform \
             mappings or collisions remain; see Preview for details."
        ),
        None => format!("{base}."),
    }
}

fn library_view_action_success_message(outcome: &LibraryViewActionOutcome) -> String {
    match outcome {
        LibraryViewActionOutcome::Added(view) => format!(
            "Library view added: {} -> {}.",
            view.name,
            view.destination_root.display()
        ),
        LibraryViewActionOutcome::Edited(view) => format!("Library view updated: {}.", view.name),
        LibraryViewActionOutcome::SetEnabled(view) => {
            if view.enabled {
                format!("Library view enabled: {}.", view.name)
            } else {
                format!("Library view disabled: {}.", view.name)
            }
        }
        LibraryViewActionOutcome::Previewed { view, plan } => format!(
            "Preview for '{}': {} to create, {} correct, {} to repair, {} to remove, {} \
             collision(s), {} skipped.",
            view.name,
            plan.counts.create,
            plan.counts.correct,
            plan.counts.repair,
            plan.counts.remove,
            plan.counts.collision,
            plan.counts.skip
        ),
        LibraryViewActionOutcome::Applied {
            view,
            report,
            skipped,
        } => library_view_apply_summary_message("Applied", &view.name, report, *skipped),
        LibraryViewActionOutcome::Repaired {
            view,
            report,
            skipped,
        } => library_view_apply_summary_message("Repaired", &view.name, report, *skipped),
        LibraryViewActionOutcome::Removed {
            view,
            report,
            kept_definition,
        } => {
            if *kept_definition {
                format!(
                    "Removed {} managed symlink(s) for '{}'. Its definition was kept.",
                    report.removed, view.name
                )
            } else {
                format!(
                    "Removed {} managed symlink(s) for '{}' and its definition.",
                    report.removed, view.name
                )
            }
        }
    }
}

/// Re-previews `view_id` immediately after an Apply/Repair, purely to read
/// off the resulting plan's `counts.skip` for an honest post-apply summary -
/// never used to decide whether the apply itself succeeded (that already
/// happened, via the existing `apply_library_view_default`/
/// `repair_library_view_default` call), and never fed back into another
/// apply. Uses the same `preview_library_view_default` the Preview button
/// already calls - no second planning implementation. `None` on any error
/// (e.g. the view was concurrently removed) rather than fabricating a count.
fn library_view_current_skip_count(view_id: &str) -> Option<usize> {
    preview_library_view_default(view_id)
        .ok()
        .map(|(_, plan)| plan.counts.skip)
}

/// Runs one [`LibraryViewAction`] against the default config/database
/// paths - the production entry point `ArchiveFsApp::start_library_view_action`
/// runs on a background thread. Every arm calls straight into the same,
/// already-tested `archivefs_core` `*_default` function the CLI's matching
/// `view` subcommand calls (see `crates/archivefs-cli/src/main.rs`'s `view
/// list`/`preview`/`apply`/`repair`/`remove` handlers) - never a second
/// implementation of planning, applying, or persistence.
fn run_library_view_action(action: &LibraryViewAction) -> Result<LibraryViewActionOutcome, String> {
    match action {
        LibraryViewAction::Add {
            name,
            destination_root,
            source_folders,
            platforms,
            profile,
        } => add_library_view_default(
            name.clone(),
            destination_root.clone(),
            source_folders.clone(),
            platforms.clone(),
            LibraryViewLayoutTemplate::PlatformFilename,
            profile.clone(),
        )
        .map(LibraryViewActionOutcome::Added)
        .map_err(|error| error.to_string()),
        LibraryViewAction::Edit {
            identifier,
            name,
            destination_root,
            source_folders,
            platforms,
            profile,
        } => edit_library_view_default(
            identifier,
            name.clone(),
            destination_root.clone(),
            source_folders.clone(),
            platforms.clone(),
            profile.clone(),
        )
        .map(LibraryViewActionOutcome::Edited)
        .map_err(|error| error.to_string()),
        LibraryViewAction::SetEnabled {
            identifier,
            enabled,
        } => set_library_view_enabled_default(identifier, *enabled)
            .map(LibraryViewActionOutcome::SetEnabled)
            .map_err(|error| error.to_string()),
        LibraryViewAction::Preview(identifier) => preview_library_view_default(identifier)
            .map(|(view, plan)| LibraryViewActionOutcome::Previewed { view, plan })
            .map_err(|error| error.to_string()),
        LibraryViewAction::Apply(identifier) => apply_library_view_default(identifier)
            .map(|(view, report)| {
                let skipped = library_view_current_skip_count(&view.id);
                LibraryViewActionOutcome::Applied {
                    view,
                    report,
                    skipped,
                }
            })
            .map_err(|error| error.to_string()),
        LibraryViewAction::Repair(identifier) => repair_library_view_default(identifier)
            .map(|(view, report)| {
                let skipped = library_view_current_skip_count(&view.id);
                LibraryViewActionOutcome::Repaired {
                    view,
                    report,
                    skipped,
                }
            })
            .map_err(|error| error.to_string()),
        LibraryViewAction::Remove {
            identifier,
            keep_definition,
        } => remove_library_view_default(identifier, *keep_definition)
            .map(|(view, report)| LibraryViewActionOutcome::Removed {
                view,
                report,
                kept_definition: *keep_definition,
            })
            .map_err(|error| error.to_string()),
    }
}

/// Mirrors the CLI's `format_source_availability` wording exactly (see
/// `crates/archivefs-cli/src/main.rs`) so the two never disagree - kept
/// as its own small presentation-layer function rather than shared code,
/// exactly like `RowOrigin::label()` already is for library rows.
fn source_availability_label(availability: SourceAvailability) -> &'static str {
    match availability {
        SourceAvailability::Available => "Available",
        SourceAvailability::Unavailable => "Unavailable",
        SourceAvailability::PermissionDenied => "Permission denied",
        SourceAvailability::Disabled => "Disabled",
        SourceAvailability::ScanFailed => "Scan failed",
    }
}

enum CatalogueManagerState {
    NotLoaded,
    Loading(Receiver<Result<CheatSourceList, CheatSourceError>>),
    Ready(CheatSourceList),
    Failed(CheatSourceError),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum CatalogueRetrievalKind {
    Download,
    Update,
}

struct CatalogueReview {
    source_id: String,
    kind: CatalogueRetrievalKind,
}

struct RunningCatalogueRetrieval {
    generation: u64,
    source_id: String,
    cancellation: CheatSourceCancellation,
    receiver: Receiver<Result<CheatSourceFetchResult, CheatSourceError>>,
    progress_receiver: Receiver<CheatSourceProgress>,
    progress: Option<CheatSourceProgress>,
    cancellation_requested: bool,
}

enum CatalogueManagerAction {
    Refresh,
    Review {
        source_id: String,
        kind: CatalogueRetrievalKind,
    },
    Confirm,
    CancelReview,
    CancelRunning,
}

enum SourcesPageAction {
    AddFolder(PathBuf),
    ScanOne(PathBuf),
    ScanAll,
    RefreshStatus,
    AssignPlatform {
        path: PathBuf,
        platform: String,
    },
    SetEnabled {
        path: PathBuf,
        enabled: bool,
    },
    ConfirmRemove {
        path: PathBuf,
        keep_catalogue: bool,
    },
    /// From the Sources row context menu's "Show archives from this
    /// source" - navigates to the Library page filtered to exactly this
    /// source, reusing the same `library_source_filter` the Library
    /// page's own Source dropdown already drives (never a second,
    /// independently-drifting filter mechanism).
    ViewInLibrary(PathBuf),
}

fn catalogue_status_label(status: CheatCatalogueStatus) -> &'static str {
    match status {
        CheatCatalogueStatus::Missing => "Missing",
        CheatCatalogueStatus::Ready => "Ready",
        CheatCatalogueStatus::ReadyWithWarnings => "Verified with warnings",
        CheatCatalogueStatus::Stale => "Stale",
        CheatCatalogueStatus::InvalidManifest => "Invalid manifest",
        CheatCatalogueStatus::Incomplete => "Incomplete",
        CheatCatalogueStatus::UnsupportedSchema => "Unsupported schema",
        CheatCatalogueStatus::VerificationFailed => "Verification failed",
        CheatCatalogueStatus::RetrievalFailed => "Retrieval failed",
        CheatCatalogueStatus::Cancelled => "Cancelled",
        CheatCatalogueStatus::ResourceLimitReached => "Resource limit reached",
    }
}

fn show_retroarch_catalogue_manager(
    ui: &mut egui::Ui,
    state: &CatalogueManagerState,
    review: Option<&CatalogueReview>,
    running: Option<&RunningCatalogueRetrieval>,
    last_result: Option<&Result<CheatSourceFetchResult, CheatSourceError>>,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<CatalogueManagerAction> {
    let mut action = None;
    widgets::section_header(
        ui,
        "RetroArch cheat catalogue",
        Some(
            "Explicitly acquire and verify third-party content from the official Libretro database.",
        ),
    );
    match state {
        CatalogueManagerState::NotLoaded | CatalogueManagerState::Loading(_) => {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Verifying local catalogue status…");
            });
        }
        CatalogueManagerState::Failed(error) => {
            widgets::banner(
                ui,
                "Catalogue status unavailable",
                &error.to_string(),
                widgets::StatusTone::Blocked,
            );
            if widgets::action_button(ui, "Retry", widgets::ActionStyle::Secondary, true).clicked()
            {
                action = Some(CatalogueManagerAction::Refresh);
            }
        }
        CatalogueManagerState::Ready(list) => {
            for entry in &list.entries {
                widgets::card(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.strong(&entry.source.display_name);
                    });
                    let status_tone = match entry.status {
                        CheatCatalogueStatus::Ready => widgets::StatusTone::Success,
                        CheatCatalogueStatus::ReadyWithWarnings => widgets::StatusTone::Warning,
                        CheatCatalogueStatus::Missing => widgets::StatusTone::Pending,
                        CheatCatalogueStatus::Stale | CheatCatalogueStatus::Cancelled => {
                            widgets::StatusTone::Warning
                        }
                        _ => widgets::StatusTone::Blocked,
                    };
                    widgets::status_strip(
                        ui,
                        &[
                            (catalogue_status_label(entry.status), status_tone),
                            (
                                "Official repository · third-party content",
                                widgets::StatusTone::Info,
                            ),
                        ],
                    );
                    ui.label("Catalogue download does not install cheats. Apply remains a separate confirmed transaction.");
                    ui.label("Updating this snapshot does not modify RetroArch or emulator files, and a game may legitimately have no matching cheat.");
                    if let Some(revision) = &entry.current_cached_version {
                        ui.label(format!("Active revision: {revision}"));
                    }
                    ui.horizontal_wrapped(|ui| {
                        if let Some(count) = entry.catalogue_file_count {
                            ui.label(format!("Active files: {count}"));
                        }
                        if let Some(count) = entry.indexed_file_count {
                            ui.label(format!("Indexed: {count}"));
                        }
                        if let Some(count) = entry.excluded_file_count {
                            ui.label(format!("Excluded: {count}"));
                        }
                        if let Some(bytes) = entry.total_bytes {
                            ui.label(format!("Verified size: {}", format_size(Some(bytes))));
                        }
                        if let Some(timestamp) = entry.fetched_at_unix_seconds {
                            ui.label(format!(
                                "Last successful update: {}",
                                format_unix_timestamp_utc(timestamp as i64)
                            ));
                        }
                    });
                    show_cheat_warnings_summary(
                        ui,
                        &entry.warnings,
                        ("catalogue_entry_warnings", &entry.source.source_id),
                        clipboard,
                    );
                    if let Some(error) = &entry.last_error {
                        widgets::banner(
                            ui,
                            if entry.setup_usable {
                                "Update failed · existing catalogue remains active and usable"
                            } else {
                                "Update failed · no usable active catalogue"
                            },
                            &error.to_string(),
                            widgets::StatusTone::Warning,
                        );
                        if let Some(timestamp) = entry.last_error_at_unix_seconds {
                            ui.label(format!(
                                "Last failed update: {}",
                                format_unix_timestamp_utc(timestamp as i64)
                            ));
                        }
                    }
                    ui.horizontal_wrapped(|ui| {
                        let idle = running.is_none() && review.is_none();
                        if entry.status == CheatCatalogueStatus::Missing
                            && widgets::action_button(
                                ui,
                                "Download",
                                widgets::ActionStyle::Primary,
                                idle,
                            )
                            .clicked()
                        {
                            action = Some(CatalogueManagerAction::Review {
                                source_id: entry.source.source_id.clone(),
                                kind: CatalogueRetrievalKind::Download,
                            });
                        }
                        if entry.status != CheatCatalogueStatus::Missing
                            && widgets::action_button(
                                ui,
                                "Update",
                                widgets::ActionStyle::Primary,
                                idle,
                            )
                            .clicked()
                        {
                            action = Some(CatalogueManagerAction::Review {
                                source_id: entry.source.source_id.clone(),
                                kind: CatalogueRetrievalKind::Update,
                            });
                        }
                        if widgets::action_button(
                            ui,
                            "Verify",
                            widgets::ActionStyle::Secondary,
                            running.is_none(),
                        )
                        .clicked()
                        {
                            action = Some(CatalogueManagerAction::Refresh);
                        }
                    });
                    widgets::technical_details(
                        ui,
                        ("provider_technical_details", &entry.source.source_id),
                        |ui| {
                            widgets::copyable_value(ui, "Provider ID", &entry.source.source_id);
                            widgets::copyable_value(
                                ui,
                                "Canonical repository",
                                &entry.source.canonical_repository_url,
                            );
                            widgets::copyable_value(
                                ui,
                                "Revision resolver",
                                &entry.source.revision_url,
                            );
                            widgets::copyable_value(
                                ui,
                                "Immutable archive template",
                                &entry.source.download_url,
                            );
                            if let Some(digest) = &entry.archive_sha256 {
                                widgets::copyable_value(ui, "Snapshot SHA-256", digest);
                            }
                            if !entry.exclusion_examples.is_empty() {
                                ui.separator();
                                ui.strong("Bounded exclusion examples");
                                for example in &entry.exclusion_examples {
                                    ui.label(format!(
                                        "{:?}: {}",
                                        example.kind,
                                        example.relative_path.as_deref().unwrap_or(
                                            "path bytes are not representable safely as UTF-8"
                                        )
                                    ));
                                }
                            }
                            ui.label(format!("Trust classification: {}", entry.trust_status));
                            if ui.button("Copy provider details").clicked() {
                                let _ = clipboard.set_text(format!(
                                    "{}\n{}",
                                    entry.source.canonical_repository_url,
                                    entry.source.revision_url
                                ));
                            }
                        },
                    );
                });
            }
        }
    }
    if let Some(running) = running {
        widgets::card(ui, |ui| {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label(if running.cancellation_requested {
                    "Cancellation requested; the active snapshot will remain unchanged."
                } else {
                    "Catalogue retrieval is running; the active snapshot remains usable until activation."
                });
            });
            if let Some(progress) = &running.progress {
                ui.horizontal_wrapped(|ui| {
                    widgets::status_badge(
                        ui,
                        catalogue_progress_label(progress.phase),
                        if progress.phase == CheatSourceProgressPhase::Retrying {
                            widgets::StatusTone::Warning
                        } else {
                            widgets::StatusTone::Info
                        },
                    );
                    if progress.attempt != 0 {
                        ui.label(format!(
                            "Attempt {} of {}",
                            progress.attempt, progress.maximum_attempts
                        ));
                    }
                });
                if progress.phase == CheatSourceProgressPhase::Downloading {
                    let received = format_transfer_bytes(progress.bytes_received);
                    if let Some(total) = progress.total_bytes {
                        let percentage = if total == 0 {
                            0.0
                        } else {
                            progress.bytes_received as f64 * 100.0 / total as f64
                        };
                        ui.label(format!(
                            "Received {received} of {} ({percentage:.1}%)",
                            format_transfer_bytes(total)
                        ));
                        ui.add(
                            egui::ProgressBar::new(
                                (progress.bytes_received as f32 / total.max(1) as f32)
                                    .clamp(0.0, 1.0),
                            )
                            .show_percentage(),
                        );
                    } else {
                        ui.label(format!("Received {received}; server size is unknown."));
                    }
                }
                if progress.phase == CheatSourceProgressPhase::Retrying {
                    ui.label(format!(
                        "Retrying after {} seconds.",
                        progress.retry_delay_seconds.unwrap_or_default()
                    ));
                }
            }
            if widgets::action_button(
                ui,
                "Cancel",
                widgets::ActionStyle::Secondary,
                !running.cancellation_requested,
            )
            .clicked()
            {
                action = Some(CatalogueManagerAction::CancelRunning);
            }
        });
    }
    if let Some(result) = last_result {
        match result {
            Ok(fetch) => widgets::banner(
                ui,
                "Cheat database updated",
                &format!(
                    "Revision {} is active; {} files were verified. No cheats were installed.",
                    fetch.manifest.resolved_revision,
                    fetch.manifest.files.len()
                ),
                widgets::StatusTone::Success,
            ),
            Err(error) => widgets::failure_summary(
                ui,
                "catalogue_result_error",
                if error.code == "cancelled" {
                    "Cheat database download cancelled"
                } else {
                    "Cheat database update failed"
                },
                Some("Your existing cheat database, if any, remains active and usable."),
                &error.to_string(),
            ),
        }
    }
    if let Some(review) = review {
        let mut open = true;
        egui::Window::new(match review.kind {
            CatalogueRetrievalKind::Download => "Review catalogue download",
            CatalogueRetrievalKind::Update => "Review catalogue update",
        })
        .collapsible(false)
        .resizable(false)
        .open(&mut open)
        .show(ui.ctx(), |ui| {
            ui.label("Network access begins only after you confirm this exact request.");
            ui.label(format!("Provider: {}", review.source_id));
            if let Ok(root) = default_cheat_source_cache_root() {
                ui.label(format!("Managed destination: {}", root.display()));
            }
            ui.label("The master reference will be resolved to an exact commit, then an immutable HTTPS archive will be downloaded and verified.");
            ui.horizontal(|ui| {
                if ui.button("Confirm retrieval").clicked() {
                    action = Some(CatalogueManagerAction::Confirm);
                }
                if ui.button("Cancel").clicked() {
                    action = Some(CatalogueManagerAction::CancelReview);
                }
            });
        });
        if !open {
            action = Some(CatalogueManagerAction::CancelReview);
        }
    }
    action
}

fn catalogue_progress_label(phase: CheatSourceProgressPhase) -> &'static str {
    match phase {
        CheatSourceProgressPhase::ResolvingRevision => "Resolving exact revision",
        CheatSourceProgressPhase::Connecting => "Connecting",
        CheatSourceProgressPhase::Downloading => "Downloading",
        CheatSourceProgressPhase::Retrying => "Retrying",
        CheatSourceProgressPhase::VerifyingArchive => "Verifying archive digest",
        CheatSourceProgressPhase::Extracting => "Extracting safely",
        CheatSourceProgressPhase::VerifyingFiles => "Verifying catalogue files",
        CheatSourceProgressPhase::Activating => "Activating verified snapshot",
        CheatSourceProgressPhase::Cancelled => "Cancelled",
    }
}

fn format_transfer_bytes(bytes: u64) -> String {
    const MIB: f64 = (1024 * 1024) as f64;
    if bytes >= 1024 * 1024 {
        format!("{:.1} MiB", bytes as f64 / MIB)
    } else if bytes >= 1024 {
        format!("{:.1} KiB", bytes as f64 / 1024.0)
    } else {
        format!("{bytes} bytes")
    }
}

// ---------------------------------------------------------------------
// Dolphin cheat catalogue management card (Cheats & Mods)
// ---------------------------------------------------------------------

/// A snapshot cheap enough to hold in `App` state: the parsed catalogue (if
/// any) plus the last update-check timestamp, loaded together by one
/// background read so the card never shows one without the other.
struct DolphinCatalogueStatusSnapshot {
    catalogue: Option<DolphinCatalogue>,
    last_check_unix_seconds: Option<u64>,
}

enum DolphinCatalogueManagerState {
    NotLoaded,
    Loading(Receiver<Result<DolphinCatalogueStatusSnapshot, DolphinCatalogueError>>),
    Ready(Box<DolphinCatalogueStatusSnapshot>),
    Failed(DolphinCatalogueError),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum DolphinCatalogueRetrievalKind {
    Download,
    Update,
    /// Re-parses the archive already pinned to the active commit, without
    /// checking upstream for a newer one.
    Rebuild,
}

struct RunningDolphinCatalogueRetrieval {
    generation: u64,
    kind: DolphinCatalogueRetrievalKind,
    cancellation: CheatSourceCancellation,
    receiver: Receiver<Result<DolphinCatalogueFetchResult, DolphinCatalogueError>>,
    progress_receiver: Receiver<CheatSourceProgress>,
    progress: Option<CheatSourceProgress>,
    cancellation_requested: bool,
}

enum DolphinCatalogueManagerAction {
    Refresh,
    Review(DolphinCatalogueRetrievalKind),
    Confirm,
    CancelReview,
    CancelRunning,
    CheckForUpdates,
    RequestRemove,
    ConfirmRemove,
    CancelRemove,
}

fn dolphin_catalogue_retrieval_kind_verb(kind: DolphinCatalogueRetrievalKind) -> &'static str {
    match kind {
        DolphinCatalogueRetrievalKind::Download => "download",
        DolphinCatalogueRetrievalKind::Update => "update",
        DolphinCatalogueRetrievalKind::Rebuild => "rebuild",
    }
}

/// Renders the beginner-facing Dolphin cheat catalogue card described in
/// the Dolphin cheat catalogue design: no-catalogue prompt, downloading
/// progress, ready summary, update-available affordance, and an honest
/// failure banner that never exposes raw transport errors at this level
/// (those live under `widgets::technical_details`).
/// Groups `show_dolphin_catalogue_manager`'s small "current moment" values
/// (as opposed to the state/running/result data it also needs) so the
/// function stays under the usual argument-count limit.
struct DolphinCatalogueCardContext {
    review: Option<DolphinCatalogueRetrievalKind>,
    update_available: Option<bool>,
    remove_confirm: bool,
    now_unix_seconds: u64,
}

fn show_dolphin_catalogue_manager(
    ui: &mut egui::Ui,
    state: &DolphinCatalogueManagerState,
    running: Option<&RunningDolphinCatalogueRetrieval>,
    last_result: Option<&Result<DolphinCatalogueFetchResult, DolphinCatalogueError>>,
    context: DolphinCatalogueCardContext,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<DolphinCatalogueManagerAction> {
    let DolphinCatalogueCardContext {
        review,
        update_available,
        remove_confirm,
        now_unix_seconds,
    } = context;
    let mut action = None;
    widgets::section_header(
        ui,
        "Dolphin cheat catalogue",
        Some(
            "A locally cached index of Gecko cheat definitions from the official Dolphin upstream project - downloaded once, searched instantly offline afterwards.",
        ),
    );
    let idle = running.is_none() && review.is_none() && !remove_confirm;
    match state {
        DolphinCatalogueManagerState::NotLoaded | DolphinCatalogueManagerState::Loading(_) => {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Checking Dolphin cheat catalogue status…");
            });
        }
        DolphinCatalogueManagerState::Failed(error) => {
            widgets::banner(
                ui,
                "Catalogue status unavailable",
                &error.to_string(),
                widgets::StatusTone::Blocked,
            );
            if widgets::action_button(ui, "Retry", widgets::ActionStyle::Secondary, true).clicked()
            {
                action = Some(DolphinCatalogueManagerAction::Refresh);
            }
        }
        DolphinCatalogueManagerState::Ready(snapshot) => {
            widgets::card(ui, |ui| match &snapshot.catalogue {
                None => {
                    widgets::status_strip(
                        ui,
                        &[(
                            "Dolphin cheat catalogue not downloaded",
                            widgets::StatusTone::Pending,
                        )],
                    );
                    if widgets::action_button(
                        ui,
                        "Download catalogue",
                        widgets::ActionStyle::Primary,
                        idle,
                    )
                    .clicked()
                    {
                        action = Some(DolphinCatalogueManagerAction::Review(
                            DolphinCatalogueRetrievalKind::Download,
                        ));
                    }
                }
                Some(catalogue) => {
                    let stale = catalogue.metadata.is_stale(now_unix_seconds);
                    let show_update = stale || update_available == Some(true);
                    let tone = if show_update {
                        widgets::StatusTone::Warning
                    } else {
                        widgets::StatusTone::Success
                    };
                    widgets::status_strip(
                        ui,
                        &[(
                            if show_update {
                                "Update available"
                            } else {
                                "Dolphin catalogue ready"
                            },
                            tone,
                        )],
                    );
                    ui.label(format!(
                        "{} games · {} cheats",
                        catalogue.games.len(),
                        catalogue.metadata.total_usable_gecko_entries
                    ));
                    ui.label(format!(
                        "Updated {}",
                        format_unix_timestamp_utc(
                            catalogue.metadata.fetched_at_unix_seconds as i64
                        )
                    ));
                    if catalogue.metadata.malformed_or_skipped_files > 0 {
                        ui.label(format!(
                            "{} upstream file(s) had no usable Gecko codes.",
                            catalogue.metadata.malformed_or_skipped_files
                        ));
                    }
                    ui.horizontal_wrapped(|ui| {
                        if widgets::action_button(
                            ui,
                            "Update catalogue",
                            widgets::ActionStyle::Primary,
                            idle,
                        )
                        .clicked()
                        {
                            action = Some(DolphinCatalogueManagerAction::Review(
                                DolphinCatalogueRetrievalKind::Update,
                            ));
                        }
                        if widgets::action_button(
                            ui,
                            "Check for updates",
                            widgets::ActionStyle::Secondary,
                            idle,
                        )
                        .clicked()
                        {
                            action = Some(DolphinCatalogueManagerAction::CheckForUpdates);
                        }
                        if widgets::action_button(
                            ui,
                            "Rebuild local index",
                            widgets::ActionStyle::Secondary,
                            idle,
                        )
                        .clicked()
                        {
                            action = Some(DolphinCatalogueManagerAction::Review(
                                DolphinCatalogueRetrievalKind::Rebuild,
                            ));
                        }
                        if widgets::action_button(
                            ui,
                            "Remove downloaded catalogue",
                            widgets::ActionStyle::Secondary,
                            idle,
                        )
                        .clicked()
                        {
                            action = Some(DolphinCatalogueManagerAction::RequestRemove);
                        }
                    });
                    if !catalogue.metadata.warnings.is_empty() {
                        show_cheat_warnings_summary(
                            ui,
                            &catalogue.metadata.warnings,
                            (
                                "dolphin_catalogue_warnings",
                                &catalogue.metadata.resolved_commit,
                            ),
                            clipboard,
                        );
                    }
                    widgets::technical_details(
                        ui,
                        (
                            "dolphin_catalogue_technical_details",
                            &catalogue.metadata.resolved_commit,
                        ),
                        |ui| {
                            widgets::copyable_value(
                                ui,
                                "Repository",
                                &catalogue.metadata.canonical_repository_url,
                            );
                            widgets::copyable_value(
                                ui,
                                "Resolved commit",
                                &catalogue.metadata.resolved_commit,
                            );
                            widgets::copyable_value(
                                ui,
                                "Source archive",
                                &catalogue.metadata.source_archive_url,
                            );
                            widgets::copyable_value(
                                ui,
                                "Archive SHA-256",
                                &catalogue.metadata.archive_sha256,
                            );
                            ui.label(format!(
                                "Downloaded: {}",
                                format_transfer_bytes(catalogue.metadata.downloaded_bytes)
                            ));
                            ui.label(format!(
                                "GameSettings files inspected: {}",
                                catalogue.metadata.game_settings_files_inspected
                            ));
                            ui.label(format!(
                                    "Non-matching files skipped (wildcard names, non-GameSettings paths): {}",
                                    catalogue.metadata.non_matching_files_skipped
                                ));
                            ui.label(format!("Licence: {}", catalogue.metadata.license));
                            ui.label(catalogue.metadata.attribution.clone());
                            if let Some(timestamp) = snapshot.last_check_unix_seconds {
                                ui.label(format!(
                                    "Last update check: {}",
                                    format_unix_timestamp_utc(timestamp as i64)
                                ));
                            }
                        },
                    );
                }
            });
        }
    }
    if let Some(running) = running {
        widgets::card(ui, |ui| {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label(if running.cancellation_requested {
                    "Cancellation requested; the active catalogue will remain unchanged."
                } else {
                    match running.kind {
                        DolphinCatalogueRetrievalKind::Download => {
                            "Downloading Dolphin cheat catalogue…"
                        }
                        DolphinCatalogueRetrievalKind::Update => {
                            "Updating Dolphin cheat catalogue…"
                        }
                        DolphinCatalogueRetrievalKind::Rebuild => {
                            "Rebuilding the local Dolphin cheat index…"
                        }
                    }
                });
            });
            if let Some(progress) = &running.progress {
                ui.horizontal_wrapped(|ui| {
                    widgets::status_badge(
                        ui,
                        catalogue_progress_label(progress.phase),
                        if progress.phase == CheatSourceProgressPhase::Retrying {
                            widgets::StatusTone::Warning
                        } else {
                            widgets::StatusTone::Info
                        },
                    );
                });
                if progress.phase == CheatSourceProgressPhase::Downloading {
                    let received = format_transfer_bytes(progress.bytes_received);
                    ui.label(format!("Received {received}."));
                }
            }
            if widgets::action_button(
                ui,
                "Cancel",
                widgets::ActionStyle::Secondary,
                !running.cancellation_requested,
            )
            .clicked()
            {
                action = Some(DolphinCatalogueManagerAction::CancelRunning);
            }
        });
    }
    if let Some(result) = last_result {
        match result {
            Ok(fetch) => widgets::banner(
                ui,
                "Dolphin catalogue ready",
                &format!(
                    "{} games · {} cheats. Updated {}.",
                    fetch.catalogue.games.len(),
                    fetch.catalogue.metadata.total_usable_gecko_entries,
                    format_unix_timestamp_utc(
                        fetch.catalogue.metadata.fetched_at_unix_seconds as i64
                    )
                ),
                widgets::StatusTone::Success,
            ),
            Err(error) => widgets::failure_summary(
                ui,
                "dolphin_catalogue_result_error",
                if error.kind == DolphinCatalogueErrorKind::Cancelled {
                    "Catalogue download cancelled"
                } else {
                    "Could not update the catalogue"
                },
                Some("Your existing catalogue is still available."),
                &error.to_string(),
            ),
        }
    }
    if let Some(kind) = review {
        let mut open = true;
        egui::Window::new(format!(
            "{}{} the Dolphin cheat catalogue?",
            dolphin_catalogue_retrieval_kind_verb(kind)[..1].to_uppercase(),
            &dolphin_catalogue_retrieval_kind_verb(kind)[1..]
        ))
        .collapsible(false)
        .resizable(false)
        .open(&mut open)
        .show(ui.ctx(), |ui| {
            ui.label("Network access begins only after you confirm this exact request.");
            if let Ok(root) = default_dolphin_catalogue_cache_root() {
                ui.label(format!("Managed destination: {}", root.display()));
            }
            ui.label("This only affects EmuWiz's own catalogue cache. Your Dolphin profile and installed codes are never touched by this action.");
            ui.horizontal(|ui| {
                if ui.button("Confirm").clicked() {
                    action = Some(DolphinCatalogueManagerAction::Confirm);
                }
                if ui.button("Cancel").clicked() {
                    action = Some(DolphinCatalogueManagerAction::CancelReview);
                }
            });
        });
        if !open {
            action = Some(DolphinCatalogueManagerAction::CancelReview);
        }
    }
    if remove_confirm {
        let mut open = true;
        egui::Window::new("Remove downloaded catalogue?")
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ui.ctx(), |ui| {
                ui.label("This removes only EmuWiz's own catalogue cache.");
                ui.label("It never removes installed Dolphin codes and never alters your Dolphin User/GameSettings files.");
                ui.horizontal(|ui| {
                    if ui.button("Remove").clicked() {
                        action = Some(DolphinCatalogueManagerAction::ConfirmRemove);
                    }
                    if ui.button("Cancel").clicked() {
                        action = Some(DolphinCatalogueManagerAction::CancelRemove);
                    }
                });
            });
        if !open {
            action = Some(DolphinCatalogueManagerAction::CancelRemove);
        }
    }
    action
}

/// One-shot gate mirroring `catalogue_status_load_needed`: load the status
/// snapshot the first time the Cheats & Mods Dolphin workflow needs it.
fn dolphin_catalogue_status_load_needed(
    view: MainView,
    state: &DolphinCatalogueManagerState,
) -> bool {
    view == MainView::CheatsMods && matches!(state, DolphinCatalogueManagerState::NotLoaded)
}

/// The cheat-database readiness summary the Sources Overview shows -
/// derived entirely from state `show_retroarch_catalogue_manager` (the
/// card rendered lower on the page) already owns, never a second,
/// independently-drifting classification. `running` takes priority over
/// `state`'s own per-entry status, since a retrieval in progress is the
/// most current, most actionable fact.
fn sources_catalogue_overview_status(
    state: &CatalogueManagerState,
    running: Option<&RunningCatalogueRetrieval>,
) -> (String, widgets::StatusTone) {
    if let Some(running) = running {
        return if running.cancellation_requested {
            (
                "Cheat database update: cancelling".to_string(),
                widgets::StatusTone::Warning,
            )
        } else {
            (
                "Cheat database update in progress".to_string(),
                widgets::StatusTone::Active,
            )
        };
    }
    match state {
        CatalogueManagerState::NotLoaded | CatalogueManagerState::Loading(_) => (
            "Checking cheat database status…".to_string(),
            widgets::StatusTone::Pending,
        ),
        CatalogueManagerState::Failed(_) => (
            "Cheat database status unavailable".to_string(),
            widgets::StatusTone::Blocked,
        ),
        CatalogueManagerState::Ready(list) => {
            let worst = list
                .entries
                .iter()
                .map(|entry| entry.status)
                .max_by_key(|status| match status {
                    CheatCatalogueStatus::Ready => 0,
                    CheatCatalogueStatus::ReadyWithWarnings => 1,
                    CheatCatalogueStatus::Stale | CheatCatalogueStatus::Cancelled => 2,
                    CheatCatalogueStatus::Missing => 3,
                    _ => 4,
                });
            match worst {
                None => (
                    "No cheat database provider configured".to_string(),
                    widgets::StatusTone::Pending,
                ),
                Some(status) => {
                    let tone = match status {
                        CheatCatalogueStatus::Ready => widgets::StatusTone::Success,
                        CheatCatalogueStatus::ReadyWithWarnings
                        | CheatCatalogueStatus::Stale
                        | CheatCatalogueStatus::Cancelled => widgets::StatusTone::Warning,
                        CheatCatalogueStatus::Missing => widgets::StatusTone::Pending,
                        _ => widgets::StatusTone::Blocked,
                    };
                    (
                        format!("Cheat database: {}", catalogue_status_label(status)),
                        tone,
                    )
                }
            }
        }
    }
}

/// The Sources page's Overview: how many source folders are configured
/// and their availability at a glance, plus the cheat database's current
/// readiness - both summarised from data the sections below already show
/// in full detail (the configured-source list and the RetroArch cheat
/// catalogue card), never a third, independently-computed source of
/// truth.
fn show_sources_overview(
    ui: &mut egui::Ui,
    sources: &[SourceFolderView],
    catalogue_manager: &CatalogueManagerState,
    catalogue_retrieval: Option<&RunningCatalogueRetrieval>,
) {
    widgets::section_header(
        ui,
        "Overview",
        Some("Configured source folders and cheat database readiness at a glance."),
    );
    widgets::card(ui, |ui| {
        let available = sources
            .iter()
            .filter(|source| source.availability == SourceAvailability::Available)
            .count();
        let disabled = sources.iter().filter(|source| !source.enabled).count();
        let blocked = sources
            .iter()
            .filter(|source| {
                source.enabled
                    && matches!(
                        source.availability,
                        SourceAvailability::Unavailable
                            | SourceAvailability::PermissionDenied
                            | SourceAvailability::ScanFailed
                    )
            })
            .count();
        ui.label(format!(
            "{} configured source folder{}",
            sources.len(),
            if sources.len() == 1 { "" } else { "s" }
        ));
        let mut items: Vec<(String, widgets::StatusTone)> = vec![(
            format!("{available} available"),
            widgets::StatusTone::Success,
        )];
        if disabled > 0 {
            items.push((format!("{disabled} disabled"), widgets::StatusTone::Pending));
        }
        if blocked > 0 {
            items.push((format!("{blocked} blocked"), widgets::StatusTone::Blocked));
        }
        let (catalogue_label, catalogue_tone) =
            sources_catalogue_overview_status(catalogue_manager, catalogue_retrieval);
        items.push((catalogue_label, catalogue_tone));
        let item_refs: Vec<(&str, widgets::StatusTone)> = items
            .iter()
            .map(|(label, tone)| (label.as_str(), *tone))
            .collect();
        widgets::status_strip(ui, &item_refs);
    });
}

fn show_sources_page(
    ui: &mut egui::Ui,
    sources: &[SourceFolderView],
    mount_root: Option<&Path>,
    busy: bool,
    add_dialog: &mut Option<SourcesAddDialogState>,
    remove_dialog: &mut Option<SourcesRemoveDialogState>,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<SourcesPageAction> {
    let mut action = None;

    // No `widgets::page_header` here any more: the Sources page's one
    // "Sources" heading now lives at the app-level call site, above the
    // Overview section this function's content follows - see the
    // `MainView::Sources` dispatch in `update`. Nothing here changed
    // otherwise; this function keeps its exact signature and every
    // existing test that calls it directly still gets the same content,
    // just without the now-redundant page-level heading repeating.
    widgets::section_header(
        ui,
        "Configured sources",
        Some("Manage the configured folders EmuWiz scans for archives."),
    );

    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            if widgets::action_button(ui, "Add folder", widgets::ActionStyle::Primary, !busy)
                .clicked()
            {
                *add_dialog = Some(SourcesAddDialogState::default());
            }
            if widgets::action_button(
                ui,
                "Scan all enabled",
                widgets::ActionStyle::Secondary,
                !busy,
            )
            .clicked()
            {
                action = Some(SourcesPageAction::ScanAll);
            }
            if widgets::action_button(ui, "Refresh status", widgets::ActionStyle::Quiet, !busy)
                .clicked()
            {
                action = Some(SourcesPageAction::RefreshStatus);
            }
        })
        .inner
    });
    ui.add_space(12.0);

    if sources.is_empty() {
        if widgets::empty_state(
            ui,
            "No source folders",
            "Add an existing readable directory, then scan it to build the catalogue.",
            Some("Add folder"),
        ) {
            *add_dialog = Some(SourcesAddDialogState::default());
        }
    } else {
        egui::ScrollArea::vertical()
            .id_salt("sources_list")
            .max_height(320.0)
            .auto_shrink([false, false])
            .show(ui, |ui| {
                for view in sources {
                    let group_response = ui.group(|ui| {
                        ui.horizontal(|ui| {
                            ui.vertical(|ui| {
                                if widgets::path_value(ui, "Source", &view.path) {
                                    let _ = clipboard.set_text(view.path.display().to_string());
                                }
                                let availability_tone = match view.availability {
                                    SourceAvailability::Available => widgets::StatusTone::Success,
                                    SourceAvailability::Disabled => widgets::StatusTone::Pending,
                                    SourceAvailability::Unavailable
                                    | SourceAvailability::PermissionDenied
                                    | SourceAvailability::ScanFailed => {
                                        widgets::StatusTone::Blocked
                                    }
                                };
                                widgets::status_strip(
                                    ui,
                                    &[
                                        (
                                            if view.enabled { "Enabled" } else { "Disabled" },
                                            if view.enabled {
                                                widgets::StatusTone::Active
                                            } else {
                                                widgets::StatusTone::Pending
                                            },
                                        ),
                                        (
                                            source_availability_label(view.availability),
                                            availability_tone,
                                        ),
                                    ],
                                );
                                ui.horizontal_wrapped(|ui| {
                                    ui.label(format!(
                                        "{} archives",
                                        view.last_archive_count
                                            .map(|count| count.to_string())
                                            .unwrap_or_else(|| "never scanned".to_string())
                                    ));
                                    ui.label(format!(
                                        "Last scan: {}",
                                        view.last_scan_at.as_deref().unwrap_or("never")
                                    ));
                                });
                                // Reviewed for the Sources cleanup and
                                // deliberately left as a plain inline
                                // label, not routed through
                                // `widgets::failure_summary` or
                                // `widgets::banner`: this is the full,
                                // already-short error text for exactly
                                // this one source folder's last scan, and
                                // a source list can show many of these
                                // rows at once. Collapsing it behind
                                // `technical_details` (as `failure_summary`
                                // would) is exactly the "would make
                                // recovery harder" case this milestone was
                                // told to avoid - the user needs to see
                                // *which* folder failed and *why* without
                                // an extra click, right where the folder
                                // itself is listed. `banner`'s heavier
                                // card-like treatment was also judged too
                                // much visual weight to repeat once per
                                // failing source in a scrollable list.
                                if let Some(error) = &view.last_scan_error {
                                    ui.colored_label(ui.visuals().error_fg_color, error);
                                }
                            });
                            ui.with_layout(
                                egui::Layout::right_to_left(egui::Align::Center),
                                |ui| {
                                    if widgets::action_button(
                                        ui,
                                        "Remove",
                                        widgets::ActionStyle::Destructive,
                                        !busy,
                                    )
                                    .clicked()
                                    {
                                        *remove_dialog = Some(SourcesRemoveDialogState {
                                            path: view.path.clone(),
                                            last_archive_count: view.last_archive_count,
                                            keep_catalogue: true,
                                        });
                                    }
                                    let enable_label =
                                        if view.enabled { "Disable" } else { "Enable" };
                                    if widgets::action_button(
                                        ui,
                                        enable_label,
                                        widgets::ActionStyle::Quiet,
                                        !busy,
                                    )
                                    .clicked()
                                    {
                                        action = Some(SourcesPageAction::SetEnabled {
                                            path: view.path.clone(),
                                            enabled: !view.enabled,
                                        });
                                    }
                                    if widgets::action_button(
                                        ui,
                                        "Scan / detect",
                                        widgets::ActionStyle::Secondary,
                                        !busy,
                                    )
                                    .clicked()
                                    {
                                        action =
                                            Some(SourcesPageAction::ScanOne(view.path.clone()));
                                    }
                                    ui.menu_button("Assign platform", |ui| {
                                        ui.label(format!(
                                            "Preview: up to {} Unknown entries can be updated on rescan.",
                                            view.unknown_archive_count
                                        ));
                                        if let Some(current) = &view.assigned_platform {
                                            ui.label(format!("Current: {current}"));
                                        }
                                        egui::ScrollArea::vertical()
                                            .id_salt(("sources_assign_platform_menu", &view.path))
                                            .max_height(240.0)
                                            .auto_shrink([false, false])
                                            .show(ui, |ui| {
                                                for platform in canonical_platform_names() {
                                                    if ui
                                                        .add_enabled(
                                                            !busy,
                                                            egui::Button::new(platform),
                                                        )
                                                        .clicked()
                                                    {
                                                        action =
                                                            Some(SourcesPageAction::AssignPlatform {
                                                                path: view.path.clone(),
                                                                platform: platform.to_string(),
                                                            });
                                                        ui.close();
                                                    }
                                                }
                                            });
                                        ui.small("Incompatible direct images remain Unknown.");
                                    });
                                },
                            );
                        });
                    });
                    group_response.response.context_menu(|ui| {
                        if ui
                            .add_enabled(!busy, egui::Button::new("Re-run platform detection"))
                            .clicked()
                        {
                            action = Some(SourcesPageAction::ScanOne(view.path.clone()));
                            ui.close();
                        }
                        let enable_label = if view.enabled {
                            "Disable source"
                        } else {
                            "Enable source"
                        };
                        if ui
                            .add_enabled(!busy, egui::Button::new(enable_label))
                            .clicked()
                        {
                            action = Some(SourcesPageAction::SetEnabled {
                                path: view.path.clone(),
                                enabled: !view.enabled,
                            });
                            ui.close();
                        }
                        if ui.button("Show archives from this source").clicked() {
                            action = Some(SourcesPageAction::ViewInLibrary(view.path.clone()));
                            ui.close();
                        }
                        if ui.button("Copy source path").clicked() {
                            let _ = clipboard.set_text(view.path.display().to_string());
                            ui.close();
                        }
                        ui.separator();
                        if ui
                            .add_enabled(!busy, egui::Button::new("Remove source"))
                            .clicked()
                        {
                            *remove_dialog = Some(SourcesRemoveDialogState {
                                path: view.path.clone(),
                                last_archive_count: view.last_archive_count,
                                keep_catalogue: true,
                            });
                            ui.close();
                        }
                    });
                }
            });
    }

    ui.add_space(theme::SECTION_GAP);
    widgets::section_header(
        ui,
        "Mount destination",
        Some("The configured mount root is read-only here."),
    );
    widgets::card(ui, |ui| {
        if let Some(root) = mount_root {
            if widgets::path_value(ui, "Mount root", root) {
                let _ = clipboard.set_text(root.display().to_string());
            }
        } else {
            ui.label("Mount root: unknown");
        }
        ui.label(
            egui::RichText::new("Configuration editing is intentionally unavailable on this page.")
                .color(theme::muted(ui)),
        );
    });

    if let Some(dialog) = add_dialog.as_mut() {
        let mut open = true;
        let mut submit = false;
        let mut cancel = false;
        egui::Window::new("Add Folder")
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ui.ctx(), |ui| {
                ui.label("Add an existing, readable directory as an EmuWiz source folder.");
                ui.horizontal(|ui| {
                    ui.label("Path:");
                    show_text_edit_with_context_menu(
                        ui,
                        &mut dialog.path_text,
                        clipboard,
                        |text_edit| {
                            text_edit
                                .id_salt("sources_add_dialog_path")
                                .desired_width(320.0)
                        },
                    );
                    // rfd's `pick_folder` is synchronous and returns
                    // `None` on cancellation or picker failure - never
                    // panics, and a cancelled pick leaves whatever the
                    // user had already typed untouched.
                    if ui.button("Browse...").clicked()
                        && let Some(path) = rfd::FileDialog::new()
                            .set_title("Select Archive Source Folder")
                            .pick_folder()
                    {
                        dialog.path_text = path.display().to_string();
                        dialog.validation_message = None;
                    }
                });
                if let Some(message) = &dialog.validation_message {
                    ui.colored_label(ui.visuals().error_fg_color, message);
                }
                ui.horizontal(|ui| {
                    if ui
                        .add_enabled(
                            !busy && !dialog.path_text.trim().is_empty(),
                            egui::Button::new("Add"),
                        )
                        .clicked()
                    {
                        submit = true;
                    }
                    if ui.button("Cancel").clicked() {
                        cancel = true;
                    }
                });
            });

        if submit {
            let candidate = PathBuf::from(dialog.path_text.trim());
            let existing: Vec<PathBuf> = sources.iter().map(|source| source.path.clone()).collect();
            match validate_new_source_folder(&candidate, &existing) {
                Ok(validated) => action = Some(SourcesPageAction::AddFolder(validated)),
                Err(error) => dialog.validation_message = Some(error.to_string()),
            }
        }
        if cancel || !open {
            *add_dialog = None;
        }
    }

    if let Some(dialog) = remove_dialog.clone() {
        let mut open = true;
        let mut confirmed = false;
        let mut cancel = false;
        let mut keep_catalogue = dialog.keep_catalogue;
        egui::Window::new("Remove this source from EmuWiz?")
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ui.ctx(), |ui| {
                ui.label("EmuWiz will not delete the folder or any files inside it.");
                ui.add_space(4.0);
                ui.strong(dialog.path.display().to_string());
                ui.add_space(4.0);
                ui.radio_value(
                    &mut keep_catalogue,
                    true,
                    "Keep catalogue entries (recommended)",
                );
                let remove_label = match dialog.last_archive_count {
                    Some(count) => {
                        format!("Remove catalogue entries belonging to this source ({count} rows)")
                    }
                    None => "Remove catalogue entries belonging to this source".to_string(),
                };
                ui.radio_value(&mut keep_catalogue, false, remove_label);
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    if ui
                        .add_enabled(!busy, egui::Button::new("Remove Source"))
                        .clicked()
                    {
                        confirmed = true;
                    }
                    if ui.button("Cancel").clicked() {
                        cancel = true;
                    }
                });
            });

        if confirmed {
            action = Some(SourcesPageAction::ConfirmRemove {
                path: dialog.path.clone(),
                keep_catalogue,
            });
            *remove_dialog = None;
        } else if cancel || !open {
            *remove_dialog = None;
        } else if let Some(current) = remove_dialog.as_mut() {
            current.keep_catalogue = keep_catalogue;
        }
    }

    action
}

fn bsfree_state_label(state: CheatProviderSourceState) -> &'static str {
    match state {
        CheatProviderSourceState::NotInstalled => "Not installed",
        CheatProviderSourceState::Downloading => "Downloading",
        CheatProviderSourceState::Validating => "Validating",
        CheatProviderSourceState::Ready => "Ready",
        CheatProviderSourceState::UpdateAvailable => "Update available",
        CheatProviderSourceState::Invalid => "Invalid",
        CheatProviderSourceState::UnsupportedSchema => "Unsupported schema",
        CheatProviderSourceState::DownloadFailed => "Download failed",
        CheatProviderSourceState::ValidationFailed => "Validation failed",
        CheatProviderSourceState::Disabled => "Disabled",
    }
}

fn bsfree_state_tone(state: CheatProviderSourceState) -> widgets::StatusTone {
    match state {
        CheatProviderSourceState::Ready => widgets::StatusTone::Success,
        CheatProviderSourceState::Downloading | CheatProviderSourceState::Validating => {
            widgets::StatusTone::Active
        }
        CheatProviderSourceState::NotInstalled | CheatProviderSourceState::Disabled => {
            widgets::StatusTone::Pending
        }
        CheatProviderSourceState::UpdateAvailable
        | CheatProviderSourceState::DownloadFailed
        | CheatProviderSourceState::ValidationFailed => widgets::StatusTone::Warning,
        CheatProviderSourceState::Invalid | CheatProviderSourceState::UnsupportedSchema => {
            widgets::StatusTone::Blocked
        }
    }
}

fn show_bsfree_source_card(
    ui: &mut egui::Ui,
    manager: &BsFreeManagerState,
    busy: bool,
    state: &mut BsFreeGuiState,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<BsFreeOperation> {
    let mut action = None;
    widgets::section_header(
        ui,
        "BSFree Archive",
        Some("Optional third-party, read-only historical cheat catalogue."),
    );
    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            ui.strong("BSFree Archive");
            match manager {
                BsFreeManagerState::NotLoaded => {
                    widgets::status_badge(ui, "Checking local state", widgets::StatusTone::Pending)
                }
                BsFreeManagerState::Ready(status) => widgets::status_badge(
                    ui,
                    bsfree_state_label(status.state),
                    bsfree_state_tone(status.state),
                ),
                BsFreeManagerState::Failed(_) => {
                    widgets::status_badge(ui, "Status unavailable", widgets::StatusTone::Warning)
                }
            }
            widgets::status_badge(
                ui,
                "GameCube cheats installable via Dolphin",
                widgets::StatusTone::Info,
            );
        });
        ui.label(
            "This catalogue covers all supported BSFree systems. GameCube cheats can be installed \
             with Dolphin; other formats remain browse only.",
        );
        widgets::technical_details(ui, "bsfree-source-provenance", |ui| {
            ui.label("Source: BSFree Archive");
            ui.label("Maintainer: Andrew Mackrodt");
            ui.label("Origin: Historical bsfree.org database");
            ui.label("Distribution status: Optional third-party download");
            ui.label("Verification: Historical community data, not verified by EmuWiz");
        });
        widgets::banner(
            ui,
            "Database-content licence not established",
            "The upstream application code is MIT, but EmuWiz does not claim that licence covers the historical cheat dataset.",
            widgets::StatusTone::Warning,
        );

        match manager {
            BsFreeManagerState::Ready(status) => {
                if widgets::path_value(ui, "Local destination", &status.database_path) {
                    let _ = clipboard.set_text(status.database_path.display().to_string());
                }
                if let Some(validation) = &status.validation {
                    widgets::status_strip(
                        ui,
                        &[
                            ("Immutable read-only SQLite", widgets::StatusTone::Success),
                            ("Query-only", widgets::StatusTone::Success),
                        ],
                    );
                    widgets::copyable_value(
                        ui,
                        "Database SHA-256",
                        &validation.result.source_fingerprint.sha256,
                    );
                    ui.label(format!(
                        "{} systems · {} games · {} codes · {} bytes",
                        validation.counts.systems,
                        validation.counts.games,
                        validation.counts.codes,
                        validation.result.source_fingerprint.size_bytes
                    ));
                    ui.label(format!(
                        "Validated: {}",
                        format_unix_timestamp_utc(
                            validation.result.validated_at_unix_seconds as i64
                        )
                    ));
                }
                if let Some(error) = &status.last_error {
                    widgets::banner(
                        ui,
                        "Last operation failed",
                        &error.message,
                        widgets::StatusTone::Warning,
                    );
                }
            }
            BsFreeManagerState::Failed(message) => widgets::banner(
                ui,
                "Could not inspect BSFree source",
                message,
                widgets::StatusTone::Warning,
            ),
            BsFreeManagerState::NotLoaded => {
                ui.horizontal(|ui| {
                    ui.spinner();
                    ui.label("Reading local source metadata...");
                });
            }
        }

        ui.separator();
        ui.horizontal_wrapped(|ui| {
            if widgets::action_button(
                ui,
                "Download database",
                widgets::ActionStyle::Primary,
                !busy,
            )
            .clicked()
            {
                state.download_confirm = true;
            }
            if widgets::action_button(
                ui,
                "Validate",
                widgets::ActionStyle::Secondary,
                !busy
                    && matches!(manager, BsFreeManagerState::Ready(status) if status.fingerprint.is_some()),
            )
            .clicked()
            {
                action = Some(BsFreeOperation::Validate);
            }
            if let BsFreeManagerState::Ready(status) = manager {
                if widgets::action_button(
                    ui,
                    if status.enabled { "Disable" } else { "Enable" },
                    widgets::ActionStyle::Quiet,
                    !busy,
                )
                .clicked()
                {
                    action = Some(BsFreeOperation::SetEnabled(!status.enabled));
                }
                if widgets::action_button(
                    ui,
                    "Remove local copy",
                    widgets::ActionStyle::Destructive,
                    !busy && status.fingerprint.is_some(),
                )
                .clicked()
                {
                    state.remove_confirm = true;
                }
            }
        });
        ui.horizontal_wrapped(|ui| {
            ui.label("Import local BSFree SQLite database");
            ui.add(
                egui::TextEdit::singleline(&mut state.import_path)
                    .desired_width(360.0)
                    .hint_text("/path/to/bsfree.4cfee26.db"),
            );
            if widgets::action_button(
                ui,
                "Import local database",
                widgets::ActionStyle::Secondary,
                !busy && !state.import_path.trim().is_empty(),
            )
            .clicked()
            {
                action = Some(BsFreeOperation::Import(PathBuf::from(
                    state.import_path.trim(),
                )));
            }
        });
        if busy {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("BSFree operation in progress...");
            });
        }
        if state.download_confirm {
            widgets::banner(
                ui,
                "Download optional third-party database?",
                "Approximately 283 MiB. Network access is required. The database-content licence is not established, it will be stored in EmuWiz's data directory, and no cheats will be installed.",
                widgets::StatusTone::Warning,
            );
            ui.horizontal(|ui| {
                if widgets::action_button(
                    ui,
                    "Confirm download",
                    widgets::ActionStyle::Primary,
                    !busy,
                )
                .clicked()
                {
                    state.download_confirm = false;
                    action = Some(BsFreeOperation::Download);
                }
                if ui.button("Cancel").clicked() {
                    state.download_confirm = false;
                }
            });
        }
        if state.remove_confirm {
            widgets::banner(
                ui,
                "Remove EmuWiz's local BSFree copy?",
                "Only the BSFree database and EmuWiz-owned BSFree metadata are removed. Emulator profiles and other cheat providers are untouched.",
                widgets::StatusTone::Warning,
            );
            ui.horizontal(|ui| {
                if widgets::action_button(
                    ui,
                    "Confirm removal",
                    widgets::ActionStyle::Destructive,
                    !busy,
                )
                .clicked()
                {
                    state.remove_confirm = false;
                    action = Some(BsFreeOperation::Remove);
                }
                if ui.button("Cancel").clicked() {
                    state.remove_confirm = false;
                }
            });
        }
    });
    action
}

fn bsfree_match_label(confidence: ProviderGameMatchConfidence) -> &'static str {
    match confidence {
        ProviderGameMatchConfidence::ExactTitlePlatform => "Exact title + platform",
        ProviderGameMatchConfidence::ProbableTitlePlatform => "Probable title + platform",
        ProviderGameMatchConfidence::Ambiguous => "Ambiguous candidates",
        ProviderGameMatchConfidence::NoMatch => "No match",
    }
}

fn bsfree_compatibility_label(compatibility: DeviceFormatCompatibility) -> &'static str {
    match compatibility {
        DeviceFormatCompatibility::DirectlyInstallable => "Directly installable",
        DeviceFormatCompatibility::PotentiallyConvertible => "Potentially convertible",
        DeviceFormatCompatibility::ReferenceOnly => "Reference only",
        DeviceFormatCompatibility::Unsupported => "Unsupported",
        DeviceFormatCompatibility::Unknown => "Unknown format",
    }
}

/// Honest, per-code capability statement for a BSFree cheat row. GameCube
/// hex-pair codes classify as installable through the existing Dolphin
/// adapter (Gecko-equivalent or native Action Replay); every other platform
/// and every unsupported format stays reference-only. This never claims
/// EmuWiz has verified the BSFree database - it states only which formats
/// an existing adapter can represent.
fn bsfree_code_capability(
    cheat: &BsFreeCheat,
    platform_id: Option<&str>,
) -> (&'static str, widgets::StatusTone) {
    if platform_id == Some("GameCube") {
        match classify_bsfree_gamecube_cheat(cheat).code_format {
            BsFreeGameCubeCodeFormat::GeckoEquivalent => {
                ("Supported by Dolphin (Gecko)", widgets::StatusTone::Success)
            }
            BsFreeGameCubeCodeFormat::ActionReplayNative => (
                "Supported by Dolphin (Action Replay)",
                widgets::StatusTone::Success,
            ),
            BsFreeGameCubeCodeFormat::Unsupported | BsFreeGameCubeCodeFormat::Malformed => (
                "Unsupported for this emulator",
                widgets::StatusTone::Pending,
            ),
        }
    } else {
        ("Reference only", widgets::StatusTone::Pending)
    }
}

fn show_bsfree_game_browser(
    ui: &mut egui::Ui,
    manager: &BsFreeManagerState,
    busy: bool,
    state: &mut BsFreeGuiState,
    context: Option<&(PathBuf, String, String)>,
) -> Option<BsFreeOperation> {
    let mut action = None;
    if let Some((archive_path, title, platform)) = context
        && state.search_context.as_ref() != Some(archive_path)
    {
        state.search_context = Some(archive_path.clone());
        state.search_title.clone_from(title);
        state.search_platform.clone_from(platform);
        state.search_result = None;
        state.selected_game = None;
        state.cheats = None;
    }

    // Whether this browser was opened for a GameCube game. Only then is the
    // "installable via Dolphin" claim relevant to what is being browsed; for
    // any other platform (or no platform) the catalogue is browse-only, and
    // saying otherwise would imply this platform's cheats can be installed.
    let is_gamecube_browse = context.is_some_and(|(_, _, platform)| {
        archivefs_core::canonical_platform_for_alias(platform) == Some("GameCube")
    });

    widgets::section_header(
        ui,
        "BSFree Archive",
        Some("Search an optional historical catalogue by title and platform."),
    );
    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            if is_gamecube_browse {
                widgets::status_badge(
                    ui,
                    "GameCube: installable via Dolphin",
                    widgets::StatusTone::Info,
                );
                ui.label(
                    "GameCube cheats can be installed with Dolphin. Other BSFree formats remain \
                     browse only.",
                );
            } else {
                widgets::status_badge(ui, "Browse only", widgets::StatusTone::Pending);
                ui.label(
                    "Cheats here are for reference: they can be viewed and copied, but EmuWiz \
                     does not install them for this platform.",
                );
            }
        });
        ui.label("Match based on platform and title. Exact game revision is not verified.");

        let usable = matches!(manager, BsFreeManagerState::Ready(status) if status.usable);
        match manager {
            BsFreeManagerState::Ready(status) if !status.usable => widgets::banner(
                ui,
                "BSFree source is not ready",
                "Download or import and validate the optional database from Cheats → Sources.",
                widgets::StatusTone::Pending,
            ),
            BsFreeManagerState::Failed(message) => widgets::banner(
                ui,
                "BSFree status unavailable",
                message,
                widgets::StatusTone::Warning,
            ),
            BsFreeManagerState::NotLoaded => {
                ui.horizontal(|ui| {
                    ui.spinner();
                    ui.label("Checking BSFree source...");
                });
            }
            BsFreeManagerState::Ready(_) => {}
        }

        ui.horizontal_wrapped(|ui| {
            ui.label("Platform");
            ui.add(
                egui::TextEdit::singleline(&mut state.search_platform)
                    .desired_width(130.0)
                    .hint_text("Canonical platform"),
            );
            ui.label("Title");
            ui.add(egui::TextEdit::singleline(&mut state.search_title).desired_width(300.0));
            if widgets::action_button(
                ui,
                "Search BSFree Archive",
                widgets::ActionStyle::Secondary,
                usable && !busy && !state.search_title.trim().is_empty(),
            )
            .clicked()
            {
                action = Some(BsFreeOperation::Search(BsFreeGameSearchRequest {
                    platform_id: (!state.search_platform.trim().is_empty())
                        .then(|| state.search_platform.trim().to_string()),
                    title: state.search_title.trim().to_string(),
                    version: None,
                    device_id: None,
                    upstream_game_id: None,
                    page: PageRequest::games(0),
                }));
            }
        });
        if busy {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Reading the local BSFree database...");
            });
        }

        if let Some(result) = &state.search_result {
            ui.separator();
            match result {
                Err(message) => widgets::banner(
                    ui,
                    "BSFree search failed",
                    message,
                    widgets::StatusTone::Warning,
                ),
                Ok(result) => {
                    ui.horizontal_wrapped(|ui| {
                        widgets::status_badge(
                            ui,
                            bsfree_match_label(result.confidence),
                            if result.confidence == ProviderGameMatchConfidence::NoMatch {
                                widgets::StatusTone::Pending
                            } else {
                                widgets::StatusTone::Info
                            },
                        );
                        ui.label(format!(
                            "{} candidate(s); revision not verified",
                            result.page.total
                        ));
                    });
                    ui.label(&result.explanation);
                    for game in &result.page.rows {
                        ui.group(|ui| {
                            ui.horizontal_wrapped(|ui| {
                                ui.strong(&game.name);
                                widgets::status_badge(
                                    ui,
                                    game.system
                                        .archivefs_platform_display_name
                                        .as_deref()
                                        .unwrap_or(&game.system.name),
                                    widgets::StatusTone::Info,
                                );
                                widgets::status_badge(
                                    ui,
                                    &game.device.name,
                                    widgets::StatusTone::Pending,
                                );
                            });
                            ui.label(format!(
                                "Version: {} · {} cheats · BSFree game UID {} / historical game ID {}",
                                game.version.as_deref().unwrap_or("not supplied"),
                                game.cheat_count,
                                game.upstream_uid,
                                game.upstream_game_id
                            ));
                            if ui
                                .add_enabled(!busy, egui::Button::new("Browse cheats"))
                                .clicked()
                            {
                                action = Some(BsFreeOperation::LoadGame {
                                    upstream_uid: game.upstream_uid,
                                    offset: 0,
                                });
                            }
                        });
                    }
                }
            }
        }

        if let (Some(game), Some(cheats)) = (&state.selected_game, &state.cheats) {
            ui.separator();
            ui.heading(&game.name);
            ui.label(format!(
                "{} · {} · {}",
                game.system
                    .archivefs_platform_display_name
                    .as_deref()
                    .unwrap_or(&game.system.name),
                game.device.name,
                game.version.as_deref().unwrap_or("version not supplied")
            ));
            match cheats {
                Err(message) => widgets::banner(
                    ui,
                    "Could not load BSFree cheats",
                    message,
                    widgets::StatusTone::Warning,
                ),
                Ok(page) => {
                    ui.label(format!(
                        "Showing {}–{} of {} cheats",
                        page.offset.saturating_add(1),
                        page.offset.saturating_add(page.rows.len() as u32),
                        page.total
                    ));
                    ui.horizontal(|ui| {
                        if ui
                            .add_enabled(
                                !busy && page.offset > 0,
                                egui::Button::new("Previous 100"),
                            )
                            .clicked()
                        {
                            action = Some(BsFreeOperation::LoadGame {
                                upstream_uid: game.upstream_uid,
                                offset: page
                                    .offset
                                    .saturating_sub(PageRequest::DEFAULT_CHEAT_LIMIT as u32),
                            });
                        }
                        if ui
                            .add_enabled(!busy && page.has_more, egui::Button::new("Next 100"))
                            .clicked()
                        {
                            action = Some(BsFreeOperation::LoadGame {
                                upstream_uid: game.upstream_uid,
                                offset: page.offset.saturating_add(page.limit as u32),
                            });
                        }
                    });
                    for cheat in &page.rows {
                        ui.group(|ui| {
                            ui.horizontal_wrapped(|ui| {
                                ui.strong(&cheat.name);
                                widgets::status_badge(
                                    ui,
                                    bsfree_compatibility_label(cheat.compatibility),
                                    widgets::StatusTone::Pending,
                                );
                                let (capability_label, capability_tone) = bsfree_code_capability(
                                    cheat,
                                    game.system.archivefs_platform_id.as_deref(),
                                );
                                widgets::status_badge(ui, capability_label, capability_tone);
                            });
                            if let Some(section) = &cheat.section {
                                ui.label(format!("Section: {}", section.name));
                            }
                            if let Some(author) = &cheat.author {
                                ui.label(format!("Author: {}", author.name));
                            }
                            if let Some(note) = &cheat.note {
                                ui.label(note);
                            }
                            ui.collapsing("Raw code and provenance", |ui| {
                                ui.monospace(&cheat.code);
                                ui.label(format!(
                                    "Provider: BSFree Archive · device: {} · row ID: {}",
                                    cheat.device.name, cheat.upstream_id
                                ));
                            });
                        });
                    }
                }
            }
        }
    });
    action
}

/// The Sources page's compact "Recent activity" - reuses
/// `widgets::activity_row_header` (the same shared row-header component
/// Phase 2's activity consolidation introduced for the bottom activity
/// bar, the History & Logs page, and the Cheats & Mods mini card), scoped
/// to the `ActivityAction` variants a Sources-page user would recognise as
/// theirs: adding/enabling/disabling/removing/scanning a source folder,
/// and cheat-database retrieval (shared with Cheats & Mods, since a
/// database update started from either page is the same event). No new
/// activity-rendering logic - only a new filter over the same
/// `OperationHistory` every other activity surface already reads.
///
/// There is no "view full history" link here, matching
/// `show_recent_cheat_activity`'s precedent on Cheats & Mods (which
/// doesn't have one either) - not invented for this page specifically.
/// Full History & Logs remains reachable from the sidebar as always.
fn show_sources_recent_activity(ui: &mut egui::Ui, history: &OperationHistory) {
    let entries: Vec<&HistoryEntry> = history
        .entries()
        .filter(|entry| {
            matches!(
                entry.action,
                ActivityAction::SourceAdded
                    | ActivityAction::SourceEnabled
                    | ActivityAction::SourceDisabled
                    | ActivityAction::SourceScan
                    | ActivityAction::SourceRemoved
                    | ActivityAction::CheatSourceRetrieval
            )
        })
        .take(5)
        .collect();
    widgets::section_header(
        ui,
        "Recent activity",
        Some("A compact view of this session's source and cheat-database changes."),
    );
    if entries.is_empty() {
        ui.weak("No source or cheat-database activity has been recorded in this session.");
        return;
    }
    for entry in entries {
        widgets::card(ui, |ui| {
            widgets::activity_row_header(
                ui,
                entry.outcome.to_string(),
                activity_outcome_tone(entry.outcome),
                entry.action.to_string(),
                Some(&format_history_timestamp(entry.timestamp)),
                |_ui| {},
            );
            ui.add(egui::Label::new(&entry.message).truncate())
                .on_hover_text(&entry.message);
        });
        ui.add_space(4.0);
    }
}

/// Renders the currently-previewed plan's counts and (filtered) entry
/// details - shared by every view's Preview output, since only one view's
/// plan is ever cached at a time (`ArchiveFsApp::library_view_last_plan`).
/// Performs no filesystem access itself; purely a display of the already-
/// computed `plan`.
fn show_library_view_plan_summary(
    ui: &mut egui::Ui,
    plan: &LibraryViewPlan,
    filter: &mut LibraryViewPlanFilter,
) {
    if let Some(error) = &plan.unsafe_root_error {
        ui.colored_label(
            ui.visuals().error_fg_color,
            format!("Unsafe destination - Apply/Repair are refused: {error}"),
        );
        return;
    }
    if let Some(error) = &plan.profile_error {
        ui.colored_label(
            ui.visuals().error_fg_color,
            format!("Unsupported frontend profile - Apply/Repair are refused: {error}"),
        );
        return;
    }
    if let Some(conflict) = &plan.fingerprint_conflict {
        ui.colored_label(
            ui.visuals().warn_fg_color,
            format!(
                "Profile changed since this view was last applied - review before re-applying: \
                 {conflict}"
            ),
        );
        return;
    }

    ui.horizontal_wrapped(|ui| {
        ui.label(format!("Create: {}", plan.counts.create));
        ui.label(format!("Correct: {}", plan.counts.correct));
        ui.label(format!("Repair: {}", plan.counts.repair));
        ui.label(format!("Remove: {}", plan.counts.remove));
        ui.label(format!("Collision: {}", plan.counts.collision));
        ui.label(format!("Skip: {}", plan.counts.skip));
    });

    ui.horizontal_wrapped(|ui| {
        for candidate in [
            LibraryViewPlanFilter::All,
            LibraryViewPlanFilter::Create,
            LibraryViewPlanFilter::Correct,
            LibraryViewPlanFilter::Repair,
            LibraryViewPlanFilter::Remove,
            LibraryViewPlanFilter::Collision,
            LibraryViewPlanFilter::Skip,
        ] {
            if ui
                .selectable_label(*filter == candidate, candidate.label())
                .clicked()
            {
                *filter = candidate;
            }
        }
    });

    let visible: Vec<&LibraryViewPlanEntry> = plan
        .entries
        .iter()
        .filter(|entry| filter.matches(entry.action))
        .collect();
    if visible.is_empty() {
        ui.label("No entries match this filter.");
        return;
    }
    egui::ScrollArea::vertical()
        .id_salt("library_view_plan_details")
        .max_height(240.0)
        .auto_shrink([false, false])
        .show(ui, |ui| {
            for entry in visible {
                let path_text = entry
                    .destination_path
                    .as_ref()
                    .or(entry.archive_path.as_ref())
                    .map(|path| path.display().to_string())
                    .unwrap_or_else(|| "?".to_string());
                ui.horizontal_wrapped(|ui| {
                    ui.label(format!("[{:?}]", entry.action));
                    ui.label(egui::RichText::new(path_text).monospace());
                    if let Some(reason) = &entry.reason {
                        ui.weak(reason);
                    }
                });
            }
        });
}

fn show_library_view_source_selection(
    ui: &mut egui::Ui,
    sources: &[SourceFolderView],
    selected: &mut HashSet<PathBuf>,
) {
    widgets::card(ui, |ui| {
        widgets::section_header(
            ui,
            "Sources",
            Some("Leave every source unchecked to include all configured sources."),
        );
        egui::ScrollArea::vertical()
            .id_salt("library_view_form_sources")
            .max_height(210.0)
            .auto_shrink([false, false])
            .show(ui, |ui| {
                if sources.is_empty() {
                    ui.weak("No source folders are configured.");
                }
                for source in sources {
                    let mut checked = selected.contains(&source.path);
                    if ui
                        .checkbox(&mut checked, source.path.display().to_string())
                        .on_hover_text(source.path.display().to_string())
                        .changed()
                    {
                        if checked {
                            selected.insert(source.path.clone());
                        } else {
                            selected.remove(&source.path);
                        }
                    }
                }
            });
    });
}

fn show_library_view_platform_selection(ui: &mut egui::Ui, selected: &mut HashSet<String>) {
    widgets::card(ui, |ui| {
        widgets::section_header(
            ui,
            "Platforms",
            Some("Leave every platform unchecked to include all known platforms."),
        );
        egui::ScrollArea::vertical()
            .id_salt("library_view_form_platforms")
            .max_height(210.0)
            .auto_shrink([false, false])
            .show(ui, |ui| {
                for platform in canonical_platform_names() {
                    let mut checked = selected.contains(platform);
                    if ui.checkbox(&mut checked, platform).changed() {
                        if checked {
                            selected.insert(platform.to_string());
                        } else {
                            selected.remove(platform);
                        }
                    }
                }
            });
    });
}

/// The Frontend Profile section of the Add/Edit View dialog: which frontend
/// (`FrontendProfileKind`) the view is nominally shaped for, and - only for
/// `Romm` - its explicit `catalogue platform -> RomM slug` overrides.
/// `Generic` is the default and, being the pre-existing behaviour, needs no
/// extra controls at all. `EsDe` is shown (so the vocabulary is visible -
/// milestone note: "should remain visible only if that fits the current UI
/// vocabulary") but its own radio option is disabled, with a short reason,
/// since `FrontendProfileKind::EsDe` still fails closed in the backend -
/// selecting it here would only ever produce a refused plan.
///
/// Writes overrides into `overrides` as an edited `(platform, slug)` list;
/// the caller (the dialog's submit handler) is the only place that turns
/// this into a real `FrontendPlatformMapping` - this function never talks to
/// `archivefs_core` at all, matching every other selection widget in this
/// dialog (`show_library_view_source_selection`/`show_library_view_platform_selection`).
#[allow(clippy::too_many_arguments)]
fn show_library_view_profile_selection(
    ui: &mut egui::Ui,
    profile_kind: &mut FrontendProfileKind,
    overrides: &mut Vec<(String, String)>,
    platform_input: &mut String,
    slug_input: &mut String,
    clipboard: &mut dyn ClipboardBackend,
) {
    widgets::card(ui, |ui| {
        widgets::section_header(
            ui,
            "Frontend Profile",
            Some(
                "Which frontend this view is shaped for. Generic is the existing \
                 {platform}/{filename} layout and is unaffected by anything below.",
            ),
        );
        ui.horizontal_wrapped(|ui| {
            ui.selectable_value(profile_kind, FrontendProfileKind::Generic, "Generic");
            ui.selectable_value(profile_kind, FrontendProfileKind::Romm, "RomM");
            ui.add_enabled_ui(false, |ui| {
                ui.selectable_value(profile_kind, FrontendProfileKind::EsDe, "ES-DE");
            })
            .response
            .on_disabled_hover_text(
                "ES-DE planning is not implemented yet - selecting it would only produce a \
                 refused plan.",
            );
        });

        if *profile_kind == FrontendProfileKind::Romm {
            ui.add_space(6.0);
            widgets::banner(
                ui,
                "RomM layout",
                "Plans roms/<slug>/<filename> under the destination above. A platform with no \
                 resolved RomM slug is skipped individually, never guessed - add an explicit \
                 override below, or resolve it via a previously imported RomM identity cache.",
                widgets::StatusTone::Info,
            );
            ui.add_space(6.0);
            ui.label(egui::RichText::new("Platform overrides").strong());
            if overrides.is_empty() {
                ui.weak("No explicit overrides yet.");
            } else {
                let mut remove_index = None;
                for (index, (platform, slug)) in overrides.iter().enumerate() {
                    ui.horizontal(|ui| {
                        ui.label(egui::RichText::new(format!("{platform} -> {slug}")).monospace());
                        if ui.small_button("Remove").clicked() {
                            remove_index = Some(index);
                        }
                    });
                }
                if let Some(index) = remove_index {
                    overrides.remove(index);
                }
            }
            ui.add_space(4.0);
            ui.horizontal(|ui| {
                ui.label("Canonical platform:");
                show_text_edit_with_context_menu(ui, platform_input, clipboard, |text_edit| {
                    text_edit
                        .id_salt("library_view_form_romm_override_platform")
                        .desired_width(140.0)
                });
                ui.label("RomM slug:");
                show_text_edit_with_context_menu(ui, slug_input, clipboard, |text_edit| {
                    text_edit
                        .id_salt("library_view_form_romm_override_slug")
                        .desired_width(120.0)
                });
                let platform_trimmed = platform_input.trim();
                let slug_trimmed = slug_input.trim();
                let can_add = !platform_trimmed.is_empty() && !slug_trimmed.is_empty();
                if ui
                    .add_enabled(can_add, egui::Button::new("Add override"))
                    .clicked()
                {
                    overrides.retain(|(existing, _)| existing != platform_trimmed);
                    overrides.push((platform_trimmed.to_string(), slug_trimmed.to_string()));
                    platform_input.clear();
                    slug_input.clear();
                }
            });
        }
    });
}

#[allow(clippy::too_many_arguments)]
fn show_library_views_page(
    ui: &mut egui::Ui,
    views: &[LibraryViewConfig],
    all_source_folders: &[SourceFolderView],
    busy: bool,
    last_plan: Option<&(LibraryViewConfig, LibraryViewPlan)>,
    focus_archive: Option<&Path>,
    plan_filter: &mut LibraryViewPlanFilter,
    form_dialog: &mut Option<LibraryViewFormDialogState>,
    remove_dialog: &mut Option<LibraryViewRemoveDialogState>,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<LibraryViewAction> {
    let mut action = None;

    widgets::section_header(
        ui,
        "Views",
        Some(
            "Organised, symlink-based folder trees that point at your existing archives. \
             EmuWiz never moves, copies, renames, or deletes an original archive file.",
        ),
    );
    ui.add_space(2.0);
    if let Some(archive_path) = focus_archive {
        ui.add_space(4.0);
        match library_view_planned_entry_for(last_plan, archive_path) {
            Some(entry) => {
                let destination = entry
                    .destination_path
                    .as_ref()
                    .map(|path| path.display().to_string())
                    .unwrap_or_else(|| "(no destination planned)".to_string());
                ui.label(format!(
                    "Preview status for {}: [{:?}] {destination}",
                    archive_path.display(),
                    entry.action
                ));
                if let Some(reason) = &entry.reason {
                    ui.weak(reason);
                }
            }
            None => {
                ui.weak(format!(
                    "No current preview covers {} - run Preview on the relevant view to see its \
                     status.",
                    archive_path.display()
                ));
            }
        }
        ui.add_space(4.0);
    }

    if ui
        .add_enabled(!busy, egui::Button::new("Add View"))
        .clicked()
    {
        *form_dialog = Some(LibraryViewFormDialogState::default());
    }
    ui.separator();

    if views.is_empty() {
        ui.label("No library views are configured yet. Click \"Add View\" to create one.");
    } else {
        egui::ScrollArea::vertical()
            .id_salt("library_views_list")
            .max_height(320.0)
            .auto_shrink([false, false])
            .show(ui, |ui| {
                for view in views {
                    // Compares the *whole* cached `LibraryViewConfig`, not
                    // just `id` - a stale plan computed for an earlier
                    // version of this same view (different source_folders,
                    // platforms, profile, ...) must never be shown or
                    // offered for Apply as if it still described `view`.
                    // `library_view_last_plan` is proactively cleared on
                    // every Add/Edit/Apply/Repair/Remove outcome already
                    // (see `poll_library_view_action`), but that is a
                    // single, easily-bypassed invalidation point (e.g. the
                    // config file changing on disk between two frames for
                    // any other reason); comparing full equality here is a
                    // second, always-correct guard that never depends on
                    // every mutation path remembering to invalidate the
                    // cache by hand.
                    let has_current_plan = last_plan
                        .as_ref()
                        .is_some_and(|(previewed, _)| previewed == view);
                    let can_apply = last_plan.as_ref().is_some_and(|(previewed, plan)| {
                        previewed == view && plan.is_safe_to_apply()
                    });
                    let group_response = ui.group(|ui| {
                        ui.horizontal(|ui| {
                            ui.strong(&view.name);
                            if !view.enabled {
                                ui.weak("(disabled)");
                            }
                        });
                        ui.label(format!("Destination: {}", view.destination_root.display()));
                        ui.label(format!(
                            "Sources: {}",
                            if view.source_folders.is_empty() {
                                "all configured sources".to_string()
                            } else {
                                view.source_folders
                                    .iter()
                                    .map(|path| path.display().to_string())
                                    .collect::<Vec<_>>()
                                    .join(", ")
                            }
                        ));
                        ui.label(format!(
                            "Platforms: {}",
                            if view.platforms.is_empty() {
                                "all known platforms".to_string()
                            } else {
                                view.platforms.join(", ")
                            }
                        ));
                        ui.label(format!("Layout: {}", view.layout_template.label()));

                        ui.horizontal_wrapped(|ui| {
                            if ui
                                .add_enabled(!busy, egui::Button::new("Preview"))
                                .clicked()
                            {
                                action = Some(LibraryViewAction::Preview(view.id.clone()));
                            }
                            if ui
                                .add_enabled(!busy && can_apply, egui::Button::new("Apply"))
                                .clicked()
                            {
                                action = Some(LibraryViewAction::Apply(view.id.clone()));
                            }
                            if ui
                                .add_enabled(!busy && can_apply, egui::Button::new("Repair"))
                                .clicked()
                            {
                                action = Some(LibraryViewAction::Repair(view.id.clone()));
                            }
                            if ui.add_enabled(!busy, egui::Button::new("Edit")).clicked() {
                                *form_dialog = Some(LibraryViewFormDialogState {
                                    editing_id: Some(view.id.clone()),
                                    name: view.name.clone(),
                                    destination_text: view.destination_root.display().to_string(),
                                    selected_source_folders: view
                                        .source_folders
                                        .iter()
                                        .cloned()
                                        .collect(),
                                    selected_platforms: view.platforms.iter().cloned().collect(),
                                    validation_message: None,
                                    profile_kind: view.profile.kind,
                                    romm_overrides: view
                                        .profile
                                        .policy
                                        .platform_mapping_overrides
                                        .iter()
                                        .map(|(platform, slug)| {
                                            (platform.to_string(), slug.to_string())
                                        })
                                        .collect(),
                                    romm_override_platform_input: String::new(),
                                    romm_override_slug_input: String::new(),
                                });
                            }
                            let enable_label = if view.enabled { "Disable" } else { "Enable" };
                            if ui
                                .add_enabled(!busy, egui::Button::new(enable_label))
                                .clicked()
                            {
                                action = Some(LibraryViewAction::SetEnabled {
                                    identifier: view.id.clone(),
                                    enabled: !view.enabled,
                                });
                            }
                            if ui.button("Copy destination path").clicked() {
                                let _ =
                                    clipboard.set_text(view.destination_root.display().to_string());
                            }
                            if ui.add_enabled(!busy, egui::Button::new("Remove")).clicked() {
                                *remove_dialog = Some(LibraryViewRemoveDialogState {
                                    view_id: view.id.clone(),
                                    view_name: view.name.clone(),
                                    keep_definition: true,
                                });
                            }
                        });

                        if has_current_plan {
                            ui.separator();
                            let (_, plan) = last_plan.expect("has_current_plan implies Some");
                            show_library_view_plan_summary(ui, plan, plan_filter);
                        }
                    });
                    group_response.response.context_menu(|ui| {
                        if ui
                            .add_enabled(!busy, egui::Button::new("Preview"))
                            .clicked()
                        {
                            action = Some(LibraryViewAction::Preview(view.id.clone()));
                            ui.close();
                        }
                        if ui
                            .add_enabled(!busy && can_apply, egui::Button::new("Apply"))
                            .clicked()
                        {
                            action = Some(LibraryViewAction::Apply(view.id.clone()));
                            ui.close();
                        }
                        if ui
                            .add_enabled(!busy && can_apply, egui::Button::new("Repair"))
                            .clicked()
                        {
                            action = Some(LibraryViewAction::Repair(view.id.clone()));
                            ui.close();
                        }
                        if ui.button("Copy destination path").clicked() {
                            let _ = clipboard.set_text(view.destination_root.display().to_string());
                            ui.close();
                        }
                        let enable_label = if view.enabled { "Disable" } else { "Enable" };
                        if ui
                            .add_enabled(!busy, egui::Button::new(enable_label))
                            .clicked()
                        {
                            action = Some(LibraryViewAction::SetEnabled {
                                identifier: view.id.clone(),
                                enabled: !view.enabled,
                            });
                            ui.close();
                        }
                        ui.separator();
                        if ui
                            .add_enabled(!busy, egui::Button::new("Remove View"))
                            .clicked()
                        {
                            *remove_dialog = Some(LibraryViewRemoveDialogState {
                                view_id: view.id.clone(),
                                view_name: view.name.clone(),
                                keep_definition: true,
                            });
                            ui.close();
                        }
                    });
                    ui.add_space(4.0);
                }
            });
    }

    if let Some(dialog) = form_dialog.as_mut() {
        let mut open = true;
        let mut submit = false;
        let mut cancel = false;
        let title = if dialog.editing_id.is_some() {
            "Edit Library View"
        } else {
            "Add Library View"
        };
        let dialog_size =
            library_view_dialog_size(ui.ctx().input(|input| input.screen_rect().size()));
        egui::Window::new(title)
            .collapsible(false)
            .resizable(true)
            .default_size(dialog_size)
            .min_size(egui::vec2(
                dialog_size.x.min(460.0),
                dialog_size.y.min(440.0),
            ))
            .open(&mut open)
            .show(ui.ctx(), |ui| {
                let form_width = ui.available_width();
                let form_scroll_height = (ui.available_height() - 94.0).max(220.0);
                egui::ScrollArea::vertical()
                    .id_salt("library_view_form_content")
                    .max_height(form_scroll_height)
                    .auto_shrink([false, false])
                    .show(ui, |ui| {
                        widgets::card(ui, |ui| {
                            widgets::section_header(
                                ui,
                                "View details",
                                Some("Name the view and choose a destination outside every archive source."),
                            );
                            ui.label(egui::RichText::new("Name").strong());
                            let name_width = ui.available_width().max(180.0);
                            show_text_edit_with_context_menu(
                                ui,
                                &mut dialog.name,
                                clipboard,
                                |text_edit| {
                                    text_edit
                                        .id_salt("library_view_form_name")
                                        .desired_width(name_width)
                                },
                            );
                            ui.add_space(4.0);
                            ui.label(egui::RichText::new("Destination").strong());
                            ui.horizontal(|ui| {
                                let destination_width = (ui.available_width() - 100.0).max(180.0);
                                show_text_edit_with_context_menu(
                                    ui,
                                    &mut dialog.destination_text,
                                    clipboard,
                                    |text_edit| {
                                        text_edit
                                            .id_salt("library_view_form_destination")
                                            .desired_width(destination_width)
                                    },
                                );
                                if ui.button("Browse...").clicked()
                                    && let Some(path) = rfd::FileDialog::new()
                                        .set_title("Select Library View Destination Folder")
                                        .pick_folder()
                                {
                                    dialog.destination_text = path.display().to_string();
                                    dialog.validation_message = None;
                                }
                            });
                        });
                        ui.add_space(8.0);

                        if library_view_selections_side_by_side(form_width) {
                            ui.columns(2, |columns| {
                                let (left, right) = columns.split_at_mut(1);
                                show_library_view_source_selection(
                                    &mut left[0],
                                    all_source_folders,
                                    &mut dialog.selected_source_folders,
                                );
                                show_library_view_platform_selection(
                                    &mut right[0],
                                    &mut dialog.selected_platforms,
                                );
                            });
                        } else {
                            show_library_view_source_selection(
                                ui,
                                all_source_folders,
                                &mut dialog.selected_source_folders,
                            );
                            ui.add_space(8.0);
                            show_library_view_platform_selection(
                                ui,
                                &mut dialog.selected_platforms,
                            );
                        }
                        ui.add_space(8.0);
                        widgets::banner(
                            ui,
                            "Layout",
                            "Creates {platform}/{filename}. No other layout is selected or implied.",
                            widgets::StatusTone::Info,
                        );
                        ui.add_space(8.0);
                        show_library_view_profile_selection(
                            ui,
                            &mut dialog.profile_kind,
                            &mut dialog.romm_overrides,
                            &mut dialog.romm_override_platform_input,
                            &mut dialog.romm_override_slug_input,
                            clipboard,
                        );
                    });

                ui.separator();
                if let Some(message) = &dialog.validation_message {
                    ui.colored_label(ui.visuals().error_fg_color, message);
                }
                let submit_blocker =
                    library_view_submit_blocker(&dialog.name, &dialog.destination_text, busy);
                if let Some(reason) = submit_blocker {
                    ui.weak(reason);
                }
                ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                    let submit_label = if dialog.editing_id.is_some() {
                        "Save"
                    } else {
                        "Add"
                    };
                    if ui
                        .add_enabled(submit_blocker.is_none(), egui::Button::new(submit_label))
                        .on_disabled_hover_text(submit_blocker.unwrap_or_default())
                        .clicked()
                    {
                        submit = true;
                    }
                    if widgets::action_button(
                        ui,
                        "Cancel",
                        widgets::ActionStyle::Quiet,
                        true,
                    )
                    .clicked()
                    {
                        cancel = true;
                    }
                    if submit_blocker.is_none() {
                        ui.label(
                            egui::RichText::new("Ready to validate and save")
                                .color(theme::muted(ui)),
                        );
                    }
                });
            });

        if submit {
            let name = dialog.name.trim().to_string();
            let destination_candidate = PathBuf::from(dialog.destination_text.trim());
            let all_source_paths: Vec<PathBuf> = all_source_folders
                .iter()
                .map(|source| source.path.clone())
                .collect();
            match validate_library_view_destination(&destination_candidate, &all_source_paths) {
                Ok(validated_destination) => {
                    let source_folders: Vec<PathBuf> =
                        dialog.selected_source_folders.iter().cloned().collect();
                    let platforms: Vec<String> =
                        dialog.selected_platforms.iter().cloned().collect();
                    let profile = library_view_form_profile(dialog);
                    action = Some(match &dialog.editing_id {
                        Some(identifier) => LibraryViewAction::Edit {
                            identifier: identifier.clone(),
                            name,
                            destination_root: validated_destination,
                            source_folders,
                            platforms,
                            profile,
                        },
                        None => LibraryViewAction::Add {
                            name,
                            destination_root: validated_destination,
                            source_folders,
                            platforms,
                            profile,
                        },
                    });
                }
                Err(error) => dialog.validation_message = Some(error.to_string()),
            }
        }
        if cancel || !open {
            *form_dialog = None;
        }
    }

    if let Some(dialog) = remove_dialog.clone() {
        let mut open = true;
        let mut confirmed = false;
        let mut cancel = false;
        let mut keep_definition = dialog.keep_definition;
        egui::Window::new("Remove this library view?")
            .collapsible(false)
            .resizable(false)
            .open(&mut open)
            .show(ui.ctx(), |ui| {
                ui.label(
                    "EmuWiz will remove only the managed symlinks recorded for this view. \
                     Original archive files are never touched.",
                );
                ui.add_space(4.0);
                ui.strong(&dialog.view_name);
                ui.add_space(4.0);
                ui.radio_value(
                    &mut keep_definition,
                    true,
                    "Keep the view's definition (recommended) - re-apply later to recreate its \
                     symlinks",
                );
                ui.radio_value(
                    &mut keep_definition,
                    false,
                    "Also remove the view's definition from configuration",
                );
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    if ui
                        .add_enabled(!busy, egui::Button::new("Remove View"))
                        .clicked()
                    {
                        confirmed = true;
                    }
                    if ui.button("Cancel").clicked() {
                        cancel = true;
                    }
                });
            });

        if confirmed {
            action = Some(LibraryViewAction::Remove {
                identifier: dialog.view_id.clone(),
                keep_definition,
            });
            *remove_dialog = None;
        } else if cancel || !open {
            *remove_dialog = None;
        } else if let Some(current) = remove_dialog.as_mut() {
            current.keep_definition = keep_definition;
        }
    }

    action
}
fn show_about_window(
    ctx: &egui::Context,
    open: &mut bool,
    database_state: &DatabaseState,
    diagnostics: &DiagnosticsState,
    mount_root: Option<&Path>,
    clipboard: &mut dyn ClipboardBackend,
) {
    egui::Window::new("About EmuWiz")
        .open(open)
        .resizable(false)
        .collapsible(false)
        .show(ctx, |ui| {
            show_about_contents(ui, database_state, diagnostics, mount_root, clipboard);
        });
}
fn system_information_text(
    database_path: Option<&str>,
    config_path: Option<&str>,
    mount_root: Option<&str>,
) -> String {
    format!(
        "EmuWiz {}\nOS: {} ({})\nDesktop: {}\nSession: {}\nDatabase schema: v{}\nDatabase path: {}\nConfiguration path: {}\nMount root: {}",
        env!("CARGO_PKG_VERSION"),
        std::env::consts::OS,
        std::env::consts::ARCH,
        std::env::var("XDG_CURRENT_DESKTOP").unwrap_or_else(|_| "unset".to_string()),
        clipboard_environment_summary(),
        latest_schema_version(),
        database_path.unwrap_or("unknown"),
        config_path.unwrap_or("unknown"),
        mount_root.unwrap_or("not loaded"),
    )
}

fn show_about_contents(
    ui: &mut egui::Ui,
    database_state: &DatabaseState,
    diagnostics: &DiagnosticsState,
    mount_root: Option<&Path>,
    clipboard: &mut dyn ClipboardBackend,
) {
    widgets::page_header_with_icon(
        ui,
        crate::ui::icons::ABOUT,
        "EmuWiz",
        "A Linux archive library and safe mount manager.",
    );

    let database_path = database_state_path(database_state).map(|path| path.display().to_string());
    let config_path = match diagnostics {
        DiagnosticsState::Ready { report, .. } => report
            .config_path
            .as_ref()
            .map(|path| path.display().to_string()),
        _ => None,
    };
    let mount_root = mount_root.map(|path| path.display().to_string());

    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            widgets::status_badge(
                ui,
                format!("Version {}", env!("CARGO_PKG_VERSION")),
                widgets::StatusTone::Info,
            );
            ui.label(format!(
                "{} · {}",
                std::env::consts::OS,
                std::env::consts::ARCH
            ));
            ui.label(format!("Database schema v{}", latest_schema_version()));
        });
        ui.label(format!(
            "Desktop: {}",
            std::env::var("XDG_CURRENT_DESKTOP").unwrap_or_else(|_| "unset".to_string())
        ));
    });
    ui.add_space(theme::SECTION_GAP);
    widgets::section_header(
        ui,
        "Runtime locations",
        Some("Paths are shown for troubleshooting and are not edited here."),
    );
    widgets::card(ui, |ui| {
        if let Some(path) = &database_path {
            if widgets::copyable_value(ui, "Database", path) {
                let _ = clipboard.set_text(path.clone());
            }
        } else {
            ui.label("Database: unknown");
        }
        if let Some(path) = &config_path {
            if widgets::copyable_value(ui, "Configuration", path) {
                let _ = clipboard.set_text(path.clone());
            }
        } else {
            ui.label("Configuration: unknown");
        }
        if let Some(path) = &mount_root {
            if widgets::copyable_value(ui, "Mount root", path) {
                let _ = clipboard.set_text(path.clone());
            }
        } else {
            ui.label("Mount root: not loaded");
        }
    });

    ui.add_space(12.0);
    if widgets::action_button(
        ui,
        "Copy system information",
        widgets::ActionStyle::Secondary,
        true,
    )
    .clicked()
    {
        let _ = clipboard.set_text(system_information_text(
            database_path.as_deref(),
            config_path.as_deref(),
            mount_root.as_deref(),
        ));
    }
}

/// The design's per-archive validation label on the Mount page - a pure
/// mapping from the live `MountState`, so the preview can never disagree
/// with what the batch engine will actually do (`Pending` is the only
/// state `queued_pending_paths` lets through to a mount attempt).
fn mount_validation_label(state: MountState) -> &'static str {
    match state {
        MountState::Pending => "Ready to mount",
        MountState::Mounted => "Already mounted — will be skipped",
        MountState::MountPathExists => "Destination already exists — will be skipped",
        MountState::NotMountable => "Loose ROM · no EmuWiz mount required",
    }
}

/// Drops queued paths whose archive no longer exists in the live
/// snapshot (source removed, rescan, etc.). Deliberately keeps queued
/// archives that are merely no longer `Pending` (mounted meanwhile, or a
/// destination collision) - those stay visible on the Mount page with
/// their skip reason instead of vanishing silently.
fn prune_mount_queue(queue: &mut Vec<PathBuf>, records: &[ArchiveRecord]) {
    queue.retain(|path| {
        records
            .iter()
            .any(|record| record.mount_plan.archive.path == *path)
    });
}

/// The queued paths that a "Mount queue" run will actually attempt - in
/// queue order, `Pending` archives only, mirroring
/// `show_bulk_row_context_menu`'s contract that
/// `mount_all_items_for_paths` is only ever fed genuinely eligible
/// archives.
fn queued_pending_paths(queue: &[PathBuf], records: &[ArchiveRecord]) -> Vec<PathBuf> {
    queue
        .iter()
        .filter(|path| {
            records.iter().any(|record| {
                record.mount_plan.archive.path == **path
                    && record.mount_state == MountState::Pending
                    && record.is_mount_input()
            })
        })
        .cloned()
        .collect()
}

/// Case-insensitive substring match over the fields the Mount page
/// displays (name, platform, archive path, planned destination) - the
/// Mount page's counterpart of the Library's `search_text` matching.
fn mount_row_matches(record: &ArchiveRecord, filter: &str) -> bool {
    let needle = filter.trim().to_lowercase();
    if needle.is_empty() {
        return true;
    }
    format!(
        "{} {} {} {}",
        record.identity.display_name,
        record.identity.platform.as_deref().unwrap_or(""),
        record.mount_plan.archive.path.display(),
        record.mount_plan.mount_path.display()
    )
    .to_lowercase()
    .contains(&needle)
}

/// What the Mount page asks `update` to do - executing a mount goes
/// through the app's own `start_mount_all` (the proven batch engine),
/// never directly from render code.
enum MountPageAction {
    MountQueue,
    Refresh,
    /// Navigate to the Mount page (the Selected page's empty-queue
    /// affordance).
    GoToMount,
    /// Open the first-class Cheats & Mods workspace for this exact
    /// archive (the Selected page's entry point).
    OpenCheatsMods(PathBuf),
    /// Start the shared background RetroArch profile scan from the
    /// Selected page's entry section.
    ScanRetroArchProfiles,
}

/// What the user chose in the shared mount-queue confirmation strip.
enum QueueConfirmChoice {
    Mount,
    Cancel,
}

/// The inline "mount the queue" confirmation strip shared by the Mount
/// and Selected pages, so their wording and gating can never drift.
fn show_mount_queue_confirmation(
    ui: &mut egui::Ui,
    attempted: usize,
    busy: bool,
) -> Option<QueueConfirmChoice> {
    let mut choice = None;
    widgets::card(ui, |ui| {
        widgets::status_badge(ui, "Confirmation", widgets::StatusTone::Warning);
        if attempted == 1 {
            ui.strong("Mount 1 queued archive?");
        } else {
            ui.strong(format!("Mount {attempted} queued archives?"));
        }
        ui.label(
            "Only archives that are ready to mount are attempted; already-mounted \
             archives and existing destinations are skipped by the batch engine.",
        );
        ui.horizontal(|ui| {
            if widgets::action_button(
                ui,
                "Mount now",
                widgets::ActionStyle::Primary,
                !busy && attempted > 0,
            )
            .clicked()
            {
                choice = Some(QueueConfirmChoice::Mount);
            }
            if widgets::action_button(ui, "Cancel", widgets::ActionStyle::Quiet, true).clicked() {
                choice = Some(QueueConfirmChoice::Cancel);
            }
        });
    });
    choice
}

/// The design's "Planned Action" label for a queued archive - what the
/// batch engine will do with it, derived purely from `MountState` (the
/// action-verb counterpart of `mount_validation_label`).
fn planned_action_label(state: MountState) -> &'static str {
    match state {
        MountState::Pending => "Mount",
        MountState::Mounted => "Skip — already mounted",
        MountState::MountPathExists => "Skip — destination already exists",
        MountState::NotMountable => "Skip — loose ROM needs no mount",
    }
}
struct SelectedPageViewState<'a> {
    selected_archive: Option<&'a Path>,
    selected_count: usize,
    retroarch_profiles: &'a RetroArchProfilesState,
    queue: &'a mut Vec<PathBuf>,
    confirm: &'a mut bool,
    busy: bool,
    block_reason: Option<&'a str>,
}

fn show_selected_page(
    ui: &mut egui::Ui,
    live: Option<&LoadedData>,
    mount_all_result: Option<&MountAllResult>,
    view_state: SelectedPageViewState<'_>,
) -> Option<MountPageAction> {
    let SelectedPageViewState {
        selected_archive,
        selected_count,
        retroarch_profiles,
        queue,
        confirm,
        busy,
        block_reason,
    } = view_state;
    let mut action = None;
    widgets::page_header_with_icon(
        ui,
        crate::ui::icons::SELECTED,
        "Selected",
        "Review queued archives and their validated destinations before mounting.",
    );
    if let Some(result) = mount_all_result {
        show_mount_all_result(ui, result);
        ui.separator();
    }

    widgets::section_header(
        ui,
        "Cheats & Mods",
        Some("Open the dedicated workspace for the archive selected in Library."),
    );
    match selected_archive {
        Some(path) => {
            if widgets::path_value(ui, "Selected archive", path) {
                ui.ctx().copy_text(path.display().to_string());
            }
        }
        None => {
            ui.label("No archive is selected in the Library.");
        }
    }
    let entry_blocker = cheat_entry_blocker(
        selected_archive,
        selected_count,
        live.map(|data| data.records.as_slice()),
        retroarch_profiles,
    );
    ui.horizontal(|ui| {
        if widgets::action_button(
            ui,
            "Open Cheats & Mods",
            widgets::ActionStyle::Secondary,
            entry_blocker.is_none() && !busy,
        )
        .clicked()
            && let Some(path) = selected_archive
        {
            action = Some(MountPageAction::OpenCheatsMods(path.to_path_buf()));
        }
        if matches!(
            retroarch_profiles,
            RetroArchProfilesState::NotScanned | RetroArchProfilesState::Error(_)
        ) && widgets::action_button(
            ui,
            "Scan for RetroArch profiles",
            widgets::ActionStyle::Quiet,
            !busy,
        )
        .clicked()
        {
            action = Some(MountPageAction::ScanRetroArchProfiles);
        }
    });
    if let Some(reason) = entry_blocker {
        widgets::banner(ui, "Unavailable", reason, widgets::StatusTone::Pending);
    }
    ui.separator();

    let Some(data) = live else {
        ui.label("Live mount state is not loaded yet.");
        return action;
    };
    prune_mount_queue(queue, &data.records);
    if queue.is_empty() {
        if widgets::empty_state(
            ui,
            "No archives queued",
            "Choose archives on the Mount page, then return here to review them.",
            Some("Choose archives"),
        ) {
            action = Some(MountPageAction::GoToMount);
        }
        return action;
    }
    let attempted = queued_pending_paths(queue, &data.records);

    widgets::section_header(
        ui,
        "Mount queue",
        Some(
            "Ready entries will be mounted; blocked entries remain visible and are skipped safely.",
        ),
    );
    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            if queue.len() == 1 {
                ui.label("1 archive queued.");
            } else {
                ui.label(format!("{} archives queued.", queue.len()));
            }
            if attempted.len() < queue.len() {
                ui.label(format!(
                    "{} will be skipped (already mounted or destination exists).",
                    queue.len() - attempted.len()
                ));
            }
            if widgets::action_button(
                ui,
                "Clear queue",
                widgets::ActionStyle::Quiet,
                !queue.is_empty(),
            )
            .clicked()
            {
                queue.clear();
                *confirm = false;
            }
            let mount_enabled = !busy && !attempted.is_empty() && !*confirm;
            if widgets::action_button(
                ui,
                format!("Mount queue ({})", attempted.len()),
                widgets::ActionStyle::Primary,
                mount_enabled,
            )
            .clicked()
            {
                *confirm = true;
            }
        })
        .inner
    });
    if busy && let Some(reason) = block_reason {
        ui.label(reason);
    }
    if *confirm {
        match show_mount_queue_confirmation(ui, attempted.len(), busy) {
            Some(QueueConfirmChoice::Mount) => {
                action = Some(MountPageAction::MountQueue);
                *confirm = false;
            }
            Some(QueueConfirmChoice::Cancel) => *confirm = false,
            None => {}
        }
    }
    ui.separator();

    egui::ScrollArea::vertical()
        .auto_shrink([false, false])
        .show(ui, |ui| {
            let mut remove: Option<PathBuf> = None;
            for ready in [true, false] {
                let count = queue
                    .iter()
                    .filter(|path| {
                        data.records.iter().any(|record| {
                            record.mount_plan.archive.path == ***path
                                && (record.mount_state == MountState::Pending) == ready
                        })
                    })
                    .count();
                if count == 0 {
                    continue;
                }
                ui.label(
                    egui::RichText::new(if ready { "READY" } else { "BLOCKED / SKIPPED" })
                        .small()
                        .strong()
                        .color(theme::muted(ui)),
                );
                for path in queue.iter() {
                    let Some(record) = data
                        .records
                        .iter()
                        .find(|record| record.mount_plan.archive.path == *path)
                    else {
                        continue;
                    };
                    if (record.mount_state == MountState::Pending) != ready {
                        continue;
                    }
                    widgets::card(ui, |ui| {
                        ui.horizontal_wrapped(|ui| {
                            ui.label(
                                egui::RichText::new(&record.identity.display_name)
                                    .size(17.0)
                                    .strong(),
                            );
                            widgets::status_badge(
                                ui,
                                record.identity.platform.as_deref().unwrap_or("Unknown"),
                                widgets::StatusTone::Info,
                            );
                            widgets::status_badge(
                                ui,
                                planned_action_label(record.mount_state),
                                if ready {
                                    widgets::StatusTone::Success
                                } else {
                                    widgets::StatusTone::Blocked
                                },
                            );
                            ui.with_layout(
                                egui::Layout::right_to_left(egui::Align::Center),
                                |ui| {
                                    if widgets::action_button(
                                        ui,
                                        "Remove",
                                        widgets::ActionStyle::Quiet,
                                        true,
                                    )
                                    .clicked()
                                    {
                                        remove = Some(path.clone());
                                    }
                                },
                            );
                        });
                        if widgets::path_value(ui, "Destination", &record.mount_plan.mount_path) {
                            ui.ctx()
                                .copy_text(record.mount_plan.mount_path.display().to_string());
                        }
                    });
                    ui.add_space(6.0);
                }
            }
            if let Some(path) = remove {
                queue.retain(|queued_path| *queued_path != path);
            }
        });
    action
}

/// The Mount page's mutable UI state, borrowed field-by-field from
/// `ArchiveFsApp` (same pattern as `HealthDashboardViewState`).
struct MountPageViewState<'a> {
    queue: &'a mut Vec<PathBuf>,
    search: &'a mut String,
    platform: &'a mut Option<String>,
    confirm: &'a mut bool,
    busy: bool,
    block_reason: Option<&'a str>,
}
fn show_mount_page(
    ui: &mut egui::Ui,
    live: Option<&LoadedData>,
    mount_all_result: Option<&MountAllResult>,
    view_state: MountPageViewState<'_>,
) -> Option<MountPageAction> {
    let MountPageViewState {
        queue,
        search,
        platform,
        confirm,
        busy,
        block_reason,
    } = view_state;
    let mut action = None;
    widgets::page_header_with_icon(
        ui,
        crate::ui::icons::MOUNT,
        "Mount",
        "Choose archives, review validated destinations, and mount the ready queue.",
    );
    if let Some(result) = mount_all_result {
        show_mount_all_result(ui, result);
        ui.separator();
    }
    let Some(data) = live else {
        ui.label("Live mount state is not loaded yet.");
        return None;
    };
    prune_mount_queue(queue, &data.records);
    let attempted = queued_pending_paths(queue, &data.records);

    let platform_counts = detected_platform_counts(
        data.records
            .iter()
            .map(|record| record.identity.platform.as_deref()),
    );
    ui.horizontal_wrapped(|ui| {
        if ui.selectable_label(platform.is_none(), "All").clicked() {
            *platform = None;
        }
        for (candidate, count) in &platform_counts.named {
            if ui
                .selectable_label(
                    platform.as_deref() == Some(candidate.as_str()),
                    format!("{candidate} ({count})"),
                )
                .clicked()
            {
                *platform = Some(candidate.clone());
            }
        }
        if platform_counts.unknown > 0
            && ui
                .selectable_label(
                    platform.as_deref() == Some("Unknown"),
                    format!("Unknown ({})", platform_counts.unknown),
                )
                .clicked()
        {
            *platform = Some("Unknown".to_string());
        }
    });

    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            ui.label("Search");
            ui.add(egui::TextEdit::singleline(search).desired_width(240.0));
            if widgets::action_button(ui, "Clear", widgets::ActionStyle::Quiet, !search.is_empty())
                .clicked()
            {
                search.clear();
            }
            if widgets::action_button(ui, "Refresh", widgets::ActionStyle::Secondary, !busy)
                .clicked()
            {
                action = Some(MountPageAction::Refresh);
            }
        })
        .inner
    });
    ui.add_space(4.0);

    let visible: Vec<&ArchiveRecord> = data
        .records
        .iter()
        .filter(|record| {
            platform.as_deref().is_none_or(|wanted| {
                record.identity.platform.as_deref().unwrap_or("Unknown") == wanted
            }) && mount_row_matches(record, search)
        })
        .collect();

    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            if queue.len() == 1 {
                ui.label("1 archive queued.");
            } else {
                ui.label(format!("{} archives queued.", queue.len()));
            }
            let any_visible_unqueued_pending = visible.iter().any(|record| {
                record.mount_state == MountState::Pending
                    && !queue.contains(&record.mount_plan.archive.path)
            });
            if widgets::action_button(
                ui,
                "Queue all visible",
                widgets::ActionStyle::Secondary,
                any_visible_unqueued_pending,
            )
            .clicked()
            {
                for record in &visible {
                    if record.mount_state == MountState::Pending
                        && !queue.contains(&record.mount_plan.archive.path)
                    {
                        queue.push(record.mount_plan.archive.path.clone());
                    }
                }
            }
            if widgets::action_button(
                ui,
                "Clear queue",
                widgets::ActionStyle::Quiet,
                !queue.is_empty(),
            )
            .clicked()
            {
                queue.clear();
                *confirm = false;
            }
            let mount_enabled = !busy && !attempted.is_empty() && !*confirm;
            if widgets::action_button(
                ui,
                format!("Mount queue ({})", attempted.len()),
                widgets::ActionStyle::Primary,
                mount_enabled,
            )
            .clicked()
            {
                *confirm = true;
            }
        })
        .inner
    });
    if busy && let Some(reason) = block_reason {
        ui.label(reason);
    }

    if *confirm {
        match show_mount_queue_confirmation(ui, attempted.len(), busy) {
            Some(QueueConfirmChoice::Mount) => {
                action = Some(MountPageAction::MountQueue);
                *confirm = false;
            }
            Some(QueueConfirmChoice::Cancel) => *confirm = false,
            None => {}
        }
    }
    ui.separator();

    if data.records.is_empty() {
        widgets::empty_state(
            ui,
            "No archives found",
            "Add and scan a source folder before creating a mount queue.",
            None,
        );
        return action;
    }
    if visible.is_empty() {
        widgets::empty_state(
            ui,
            "No matching archives",
            "Change or clear the search to see available archives.",
            None,
        );
        return action;
    }

    egui::ScrollArea::vertical()
        .auto_shrink([false, false])
        .show(ui, |ui| {
            let mut toggle: Option<(PathBuf, bool)> = None;
            for record in &visible {
                let path = &record.mount_plan.archive.path;
                let queued = queue.contains(path);
                widgets::card(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(
                            egui::RichText::new(&record.identity.display_name)
                                .size(17.0)
                                .strong(),
                        );
                        widgets::status_badge(
                            ui,
                            record.identity.platform.as_deref().unwrap_or("Unknown"),
                            widgets::StatusTone::Info,
                        );
                        let tone = match record.mount_state {
                            MountState::Pending => widgets::StatusTone::Success,
                            MountState::Mounted => widgets::StatusTone::Active,
                            MountState::MountPathExists => widgets::StatusTone::Blocked,
                            MountState::NotMountable => widgets::StatusTone::Info,
                        };
                        widgets::status_badge(ui, mount_validation_label(record.mount_state), tone);
                        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                            let label = if queued { "Remove" } else { "Add to queue" };
                            if widgets::action_button(
                                ui,
                                label,
                                if queued {
                                    widgets::ActionStyle::Quiet
                                } else {
                                    widgets::ActionStyle::Secondary
                                },
                                queued || record.mount_state == MountState::Pending,
                            )
                            .clicked()
                            {
                                toggle = Some((path.clone(), !queued));
                            }
                        });
                    });
                    if widgets::path_value(ui, "Destination", &record.mount_plan.mount_path) {
                        ui.ctx()
                            .copy_text(record.mount_plan.mount_path.display().to_string());
                    }
                    widgets::technical_details(ui, ("mount_queue_archive_location", path), |ui| {
                        if widgets::path_value(ui, "Archive", path) {
                            ui.ctx().copy_text(path.display().to_string());
                        }
                    });
                });
                ui.add_space(6.0);
            }
            if let Some((path, add)) = toggle {
                if add {
                    if !queue.contains(&path) {
                        queue.push(path);
                    }
                } else {
                    queue.retain(|queued_path| *queued_path != path);
                }
            }
        });
    action
}

/// What the Active Mounts page asks `update` to do. `Unmount` is only
/// ever returned after the page's own inline confirmation, and is then
/// routed through the exact `AppOperationRequest::Archive` /
/// `start_operation` path the Library's selected-archive panel uses.
enum ActiveMountsPageAction {
    Unmount(PathBuf),
    OpenInLibrary(PathBuf),
    Refresh,
}
fn show_active_mounts_page(
    ui: &mut egui::Ui,
    live_records: Option<&[ArchiveRecord]>,
    confirm_unmount: &mut Option<PathBuf>,
    cleanup_after_unmount: &mut bool,
    feedback: Option<&ActionFeedback>,
    busy: bool,
) -> Option<ActiveMountsPageAction> {
    let mut action = None;
    widgets::page_header_with_icon(
        ui,
        crate::ui::icons::MOUNT,
        "Active Mounts",
        "Review current mounts and unmount them normally after closing applications that use them.",
    );
    if let Some(feedback) = feedback {
        widgets::banner(
            ui,
            if feedback.succeeded {
                "Completed"
            } else {
                "Failed"
            },
            &feedback.message,
            if feedback.succeeded {
                widgets::StatusTone::Success
            } else {
                widgets::StatusTone::Blocked
            },
        );
    }
    let Some(records) = live_records else {
        ui.label("Live mount state is not loaded yet.");
        return None;
    };
    let mounted = pending_unmount_items(records);
    // A confirmation for an archive that is no longer mounted (unmounted
    // meanwhile, snapshot refreshed) must not survive as a stale prompt.
    if let Some(pending) = confirm_unmount.as_ref()
        && !mounted.iter().any(|item| item.archive_path == *pending)
    {
        *confirm_unmount = None;
    }
    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            widgets::status_badge(
                ui,
                format!("{} active", mounted.len()),
                if mounted.is_empty() {
                    widgets::StatusTone::Pending
                } else {
                    widgets::StatusTone::Active
                },
            );
            if mounted.len() == 1 {
                ui.label("1 mounted archive.");
            } else {
                ui.label(format!("{} mounted archives.", mounted.len()));
            }
            if widgets::action_button(ui, "Refresh", widgets::ActionStyle::Secondary, !busy)
                .clicked()
            {
                action = Some(ActiveMountsPageAction::Refresh);
            }
        })
        .inner
    });
    if mounted.is_empty() {
        widgets::empty_state(
            ui,
            "Nothing is mounted",
            "Mounted archives will appear here with their destinations and normal unmount controls.",
            None,
        );
        return action;
    }
    ui.add_enabled_ui(!busy, |ui| {
        ui.checkbox(
            cleanup_after_unmount,
            "Clean empty mount directories after unmount",
        );
    });
    if let Some(pending) = confirm_unmount.clone() {
        let name = mounted
            .iter()
            .find(|item| item.archive_path == pending)
            .map(|item| item.display_name.as_str())
            .unwrap_or("this archive");
        widgets::card(ui, |ui| {
            widgets::status_badge(ui, "Confirmation", widgets::StatusTone::Warning);
            ui.strong(format!("Unmount {name}?"));
            ui.label("Close applications using this mount before unmounting.");
            ui.horizontal(|ui| {
                if widgets::action_button(
                    ui,
                    "Unmount now",
                    widgets::ActionStyle::Destructive,
                    !busy,
                )
                .clicked()
                {
                    action = Some(ActiveMountsPageAction::Unmount(pending.clone()));
                    *confirm_unmount = None;
                }
                if widgets::action_button(ui, "Cancel", widgets::ActionStyle::Quiet, true).clicked()
                {
                    *confirm_unmount = None;
                }
            });
        });
    }
    ui.separator();
    egui::ScrollArea::vertical()
        .auto_shrink([false, false])
        .show(ui, |ui| {
            for item in &mounted {
                widgets::card(ui, |ui| {
                    ui.horizontal_wrapped(|ui| {
                        ui.label(egui::RichText::new(&item.display_name).size(17.0).strong());
                        widgets::status_badge(ui, "Mounted", widgets::StatusTone::Active);
                        ui.with_layout(egui::Layout::right_to_left(egui::Align::Center), |ui| {
                            if widgets::action_button(
                                ui,
                                "Unmount",
                                widgets::ActionStyle::Destructive,
                                !busy,
                            )
                            .clicked()
                            {
                                *confirm_unmount = Some(item.archive_path.clone());
                            }
                            if widgets::action_button(
                                ui,
                                "Open in Library",
                                widgets::ActionStyle::Quiet,
                                true,
                            )
                            .clicked()
                            {
                                action = Some(ActiveMountsPageAction::OpenInLibrary(
                                    item.archive_path.clone(),
                                ));
                            }
                        });
                    });
                    if widgets::path_value(ui, "Destination", &item.mount_path) {
                        ui.ctx().copy_text(item.mount_path.display().to_string());
                    }
                    if widgets::path_value(ui, "Archive", &item.archive_path) {
                        ui.ctx().copy_text(item.archive_path.display().to_string());
                    }
                });
                ui.add_space(6.0);
            }
        });
    action
}

/// Active Mounts' compact "Recent activity" - reuses
/// `widgets::activity_row_header`, the same shared row-header component
/// `show_sources_recent_activity` and `show_recent_cheat_activity` already
/// use, scoped to the `ActivityAction` variants a mount/unmount user would
/// recognise as theirs. No new row-rendering logic, only a new filter over
/// the same `OperationHistory` every other activity surface already reads.
/// No "view full history" link, matching the same precedent; full History
/// & Logs remains reachable from the sidebar as always.
fn show_active_mounts_recent_activity(ui: &mut egui::Ui, history: &OperationHistory) {
    let entries: Vec<&HistoryEntry> = history
        .entries()
        .filter(|entry| {
            matches!(
                entry.action,
                ActivityAction::Mount
                    | ActivityAction::MountAll
                    | ActivityAction::Unmount
                    | ActivityAction::UnmountAll
                    | ActivityAction::LazyUnmount
                    | ActivityAction::Remount
                    | ActivityAction::Cleanup
            )
        })
        .take(5)
        .collect();
    widgets::section_header(
        ui,
        "Recent activity",
        Some("A compact view of this session's mount and unmount changes."),
    );
    if entries.is_empty() {
        ui.weak("No mount or unmount activity has been recorded in this session.");
        return;
    }
    for entry in entries {
        widgets::card(ui, |ui| {
            widgets::activity_row_header(
                ui,
                entry.outcome.to_string(),
                activity_outcome_tone(entry.outcome),
                entry.action.to_string(),
                Some(&format_history_timestamp(entry.timestamp)),
                |_ui| {},
            );
            ui.add(egui::Label::new(&entry.message).truncate())
                .on_hover_text(&entry.message);
        });
        ui.add_space(4.0);
    }
}

/// The shared rollback preview/review/confirm/apply/result card, reused
/// verbatim (extracted, not duplicated - see
/// docs/GUI_NAVIGATION_RESET_DESIGN.md's Undo requirement) by both
/// History & Logs and Gamer View's "Undo last change" so there is exactly
/// one rendering of this state machine, not a second copy that could
/// drift from it.
fn show_shared_rollback_card(
    ui: &mut egui::Ui,
    rollback: &mut SharedRollbackState,
) -> Option<HistoryPageAction> {
    let mut action = None;
    widgets::card(ui, |ui| match rollback {
        SharedRollbackState::Idle => {
            ui.label("Rollback always begins with a fresh read-only preview and a separate confirmation.");
        }
        SharedRollbackState::Previewing { .. } => {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Inspecting rollback state off the UI thread…");
            });
        }
        SharedRollbackState::Review { preview, .. } => {
            widgets::status_badge(
                ui,
                if preview.available {
                    "Rollback available"
                } else {
                    "Rollback blocked"
                },
                if preview.available {
                    widgets::StatusTone::Warning
                } else {
                    widgets::StatusTone::Blocked
                },
            );
            widgets::copyable_value(ui, "Rollback preview ID", &preview.preview_id);
            for entry in &preview.entries {
                ui.label(format!("Current state: {:?}", entry.outcome));
                if let Some(destination) = &entry.destination {
                    ui.label(format!("Destination: {}", destination.display));
                }
                if let Some(backup) = &entry.backup {
                    ui.label(format!("Backup: {}", backup.display));
                }
                if let Some(failure) = &entry.failure {
                    ui.label(format!("Blocker: {:?} · {}", failure.kind, failure.detail));
                }
            }
            ui.horizontal_wrapped(|ui| {
                if widgets::action_button(
                    ui,
                    "Confirm exact rollback",
                    widgets::ActionStyle::Primary,
                    preview.available,
                )
                .clicked()
                {
                    action = Some(HistoryPageAction::ConfirmRollback);
                }
                if widgets::action_button(ui, "Cancel", widgets::ActionStyle::Quiet, true).clicked()
                {
                    action = Some(HistoryPageAction::CancelRollback);
                }
            });
        }
        SharedRollbackState::Applying { .. } => {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Restoring the previous files and checking the result…");
            });
        }
        SharedRollbackState::Result(result) => {
            widgets::status_badge(
                ui,
                format!("Rollback {:?}", result.status),
                if result.status == SharedApplyStatus::Success {
                    widgets::StatusTone::Success
                } else {
                    widgets::StatusTone::Warning
                },
            );
            for entry in &result.preview.entries {
                ui.label(format!("Rollback result: {:?}", entry.outcome));
            }
            if widgets::action_button(ui, "Close result", widgets::ActionStyle::Quiet, true)
                .clicked()
            {
                action = Some(HistoryPageAction::CancelRollback);
            }
        }
        SharedRollbackState::Failed(message) => {
            widgets::banner(ui, "Rollback failed", message, widgets::StatusTone::Blocked);
            if widgets::action_button(ui, "Close", widgets::ActionStyle::Quiet, true).clicked() {
                action = Some(HistoryPageAction::CancelRollback);
            }
        }
    });
    action
}

fn shared_history_adapter_label(adapter: PreviewAdapter) -> &'static str {
    match adapter {
        PreviewAdapter::RetroArch => "RetroArch",
        PreviewAdapter::Pcsx2 => "PCSX2",
        PreviewAdapter::Dolphin => "Dolphin",
        PreviewAdapter::Xenia => "Xenia",
    }
}

fn shared_history_status_label(status: SharedApplyStatus) -> &'static str {
    match status {
        SharedApplyStatus::DryRun => "Preview",
        SharedApplyStatus::Success => "Completed",
        SharedApplyStatus::PartialFailure => "Needs attention",
        SharedApplyStatus::Failed => "Failed",
    }
}

fn shared_history_game_title(
    journal: &archivefs_core::patch_manager::SharedApplyJournal,
) -> String {
    journal
        .context
        .selected_archive
        .to_path_buf()
        .ok()
        .and_then(|path| {
            path.file_stem()
                .map(|name| name.to_string_lossy().into_owned())
        })
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| "selected game".to_string())
}

fn shared_history_title(journal: &archivefs_core::patch_manager::SharedApplyJournal) -> String {
    let game = shared_history_game_title(journal);
    match (journal.status, journal.context.adapter) {
        (SharedApplyStatus::DryRun, _) => format!("Changes previewed for {game}"),
        (_, PreviewAdapter::Xenia) => format!("Patches added to {game}"),
        _ => format!("Cheats added to {game}"),
    }
}

fn short_month(month: time::Month) -> &'static str {
    match month {
        time::Month::January => "Jan",
        time::Month::February => "Feb",
        time::Month::March => "Mar",
        time::Month::April => "Apr",
        time::Month::May => "May",
        time::Month::June => "Jun",
        time::Month::July => "Jul",
        time::Month::August => "Aug",
        time::Month::September => "Sep",
        time::Month::October => "Oct",
        time::Month::November => "Nov",
        time::Month::December => "Dec",
    }
}

/// Friendly local wall-clock display for a saved change. The raw Unix value
/// remains under Technical details for audit work.
fn format_shared_history_time(timestamp: u64, now: SystemTime) -> String {
    let Ok(timestamp) = i64::try_from(timestamp) else {
        return "Time unavailable".to_string();
    };
    let Ok(utc) = time::OffsetDateTime::from_unix_timestamp(timestamp) else {
        return "Time unavailable".to_string();
    };
    let offset = time::UtcOffset::current_local_offset().unwrap_or(time::UtcOffset::UTC);
    let local = utc.to_offset(offset);
    let now_seconds = now
        .duration_since(UNIX_EPOCH)
        .ok()
        .and_then(|duration| i64::try_from(duration.as_secs()).ok())
        .and_then(|seconds| time::OffsetDateTime::from_unix_timestamp(seconds).ok())
        .map(|value| value.to_offset(offset));
    if now_seconds.is_some_and(|value| value.date() == local.date()) {
        format!("Today at {:02}:{:02}", local.hour(), local.minute())
    } else {
        format!(
            "{} {} {} at {:02}:{:02}",
            local.day(),
            short_month(local.month()),
            local.year(),
            local.hour(),
            local.minute()
        )
    }
}

fn show_history_logs_page(
    ui: &mut egui::Ui,
    shared_history: &SharedHistoryState,
    rollback: &mut SharedRollbackState,
    selected_operation: Option<&str>,
    history: &mut OperationHistory,
    filters: &mut HistoryLogFilters,
    clipboard: &mut dyn ClipboardBackend,
) -> Option<HistoryPageAction> {
    let mut action = None;
    widgets::page_header_with_icon(
        ui,
        crate::ui::icons::HISTORY,
        "History & Logs",
        "Filter, inspect, copy, or export operations from this application session.",
    );
    widgets::section_header(
        ui,
        "Recovery",
        Some("Undo the most recent cheat or patch changes if something went wrong."),
    );
    if let Some(rollback_action) = show_shared_rollback_card(ui, rollback) {
        action = Some(rollback_action);
    }
    widgets::section_header(
        ui,
        "Changes you can undo",
        Some("Recent cheat and patch changes, with rollback available when safe."),
    );
    if widgets::action_button(
        ui,
        "Refresh change history",
        widgets::ActionStyle::Secondary,
        !matches!(shared_history, SharedHistoryState::Loading { .. }),
    )
    .clicked()
    {
        action = Some(HistoryPageAction::Refresh);
    }
    match shared_history {
        SharedHistoryState::NotLoaded | SharedHistoryState::Loading { .. } => {
            ui.horizontal(|ui| {
                ui.spinner();
                ui.label("Loading change history…");
            });
        }
        SharedHistoryState::Failed(message) => widgets::banner(
            ui,
            "Change history unavailable",
            message,
            widgets::StatusTone::Warning,
        ),
        SharedHistoryState::Ready(report) => {
            if !report.warnings.is_empty() {
                widgets::banner(
                    ui,
                    "Some history details could not be read",
                    &format!(
                        "{} saved record(s) could not be opened. Other changes remain available.",
                        report.warnings.len()
                    ),
                    widgets::StatusTone::Warning,
                );
            }
            if report.journals.is_empty() {
                ui.label("No undoable changes found.");
            } else {
                let mut journals: Vec<_> = report.journals.iter().collect();
                journals.sort_by(|left, right| {
                    right
                        .1
                        .timestamp_unix_seconds
                        .cmp(&left.1.timestamp_unix_seconds)
                        .then_with(|| right.1.operation_id.cmp(&left.1.operation_id))
                });
                for (path, journal) in journals.into_iter().take(200) {
                    widgets::card(ui, |ui| {
                        ui.horizontal_wrapped(|ui| {
                            widgets::status_badge(
                                ui,
                                shared_history_status_label(journal.status),
                                match journal.status {
                                    SharedApplyStatus::Success => widgets::StatusTone::Success,
                                    SharedApplyStatus::PartialFailure => {
                                        widgets::StatusTone::Warning
                                    }
                                    SharedApplyStatus::Failed => widgets::StatusTone::Blocked,
                                    SharedApplyStatus::DryRun => widgets::StatusTone::Info,
                                },
                            );
                            ui.strong(shared_history_title(journal));
                            if selected_operation == Some(journal.operation_id.as_str()) {
                                widgets::status_badge(
                                    ui,
                                    "Opened from apply result",
                                    widgets::StatusTone::Info,
                                );
                            }
                        });
                        ui.label(format!(
                            "{} · {}",
                            shared_history_adapter_label(journal.context.adapter),
                            format_shared_history_time(
                                journal.timestamp_unix_seconds,
                                SystemTime::now()
                            )
                        ));
                        ui.label(format!(
                            "{} change{}",
                            journal.entries.len(),
                            if journal.entries.len() == 1 { "" } else { "s" }
                        ));
                        ui.label(format!(
                            "Rollback: {}",
                            if journal.rollback_operation_id.is_some() {
                                "already completed"
                            } else if journal.status == SharedApplyStatus::Success {
                                "preview may be available"
                            } else {
                                "unavailable"
                            }
                        ));
                        widgets::technical_details(
                            ui,
                            ("journal_technical_detail", &journal.plan_id),
                            |ui| {
                                widgets::copyable_value(
                                    ui,
                                    "Transaction ID",
                                    &journal.operation_id,
                                );
                                widgets::copyable_value(ui, "Plan ID", &journal.plan_id);
                                ui.label(format!(
                                    "Raw timestamp: {}",
                                    journal.timestamp_unix_seconds
                                ));
                                widgets::copyable_value(
                                    ui,
                                    "Selected archive",
                                    &journal.context.selected_archive.display,
                                );
                                widgets::copyable_value(
                                    ui,
                                    "Source mode",
                                    &journal.context.source_mode,
                                );
                                widgets::copyable_value(
                                    ui,
                                    "Destination root",
                                    &journal.destination_root.display,
                                );
                                if widgets::path_value(
                                    ui,
                                    "Journal path",
                                    &PathBuf::from(&path.display),
                                ) {
                                    let _ = clipboard.set_text(path.display.clone());
                                }
                                for entry in &journal.entries {
                                    ui.label(format!(
                                        "{:?} · {} · verification {} · backup {}",
                                        entry.outcome,
                                        entry.plan_entry.destination_relative_path.display,
                                        if entry.verification_succeeded {
                                            "passed"
                                        } else {
                                            "not complete"
                                        },
                                        if entry.backup_path.is_some() {
                                            "retained"
                                        } else {
                                            "not required"
                                        }
                                    ));
                                }
                            },
                        );
                        let journal_path = path.to_path_buf().ok();
                        let destination_root = journal.destination_root.to_path_buf().ok();
                        let can_preview = journal.status == SharedApplyStatus::Success
                            && journal.rollback_operation_id.is_none()
                            && journal_path.is_some()
                            && destination_root.is_some()
                            && matches!(rollback, SharedRollbackState::Idle);
                        if widgets::action_button(
                            ui,
                            "Preview rollback",
                            widgets::ActionStyle::Secondary,
                            can_preview,
                        )
                        .clicked()
                        {
                            action = Some(HistoryPageAction::PreviewRollback {
                                journal_path: journal_path.expect("enabled path"),
                                destination_root: destination_root.expect("enabled root"),
                            });
                        }
                    });
                }
            }
        }
    }
    ui.add_space(theme::SECTION_GAP);
    widgets::section_header(
        ui,
        "Session activity",
        Some("This session's recorded operations - filter, copy, or export what's shown below."),
    );
    if history.entries().next().is_none() {
        widgets::empty_state(
            ui,
            "No session activity yet",
            "Mounts, scans, diagnostics, and trusted-source retrievals will be recorded here for this session.",
            None,
        );
        return action;
    }

    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            egui::ComboBox::from_label("Operation")
                .selected_text(
                    filters
                        .action
                        .map_or_else(|| "All Operations".to_string(), |action| action.to_string()),
                )
                .show_ui(ui, |ui| {
                    ui.selectable_value(&mut filters.action, None, "All Operations");
                    for action in ALL_ACTIVITY_ACTIONS {
                        ui.selectable_value(&mut filters.action, Some(action), action.to_string());
                    }
                });
            egui::ComboBox::from_label("Result")
                .selected_text(
                    filters
                        .outcome
                        .map_or_else(|| "All Results".to_string(), |outcome| outcome.to_string()),
                )
                .show_ui(ui, |ui| {
                    ui.selectable_value(&mut filters.outcome, None, "All Results");
                    for outcome in ALL_ACTIVITY_OUTCOMES {
                        ui.selectable_value(
                            &mut filters.outcome,
                            Some(outcome),
                            outcome.to_string(),
                        );
                    }
                });
            let sort_label = if filters.oldest_first {
                "Sort: Oldest First"
            } else {
                "Sort: Newest First"
            };
            if widgets::action_button(ui, sort_label, widgets::ActionStyle::Secondary, true)
                .clicked()
            {
                filters.oldest_first = !filters.oldest_first;
            }
            if widgets::action_button(
                ui,
                "Clear filters",
                widgets::ActionStyle::Quiet,
                filters.action.is_some() || filters.outcome.is_some(),
            )
            .clicked()
            {
                filters.action = None;
                filters.outcome = None;
            }
        })
        .inner
    });

    // Owned copies end the immutable borrow of `history` before the
    // buttons below may mutate it (clear / record an export entry).
    let visible_entries: Vec<HistoryEntry> = visible_history_entries(history, filters)
        .into_iter()
        .cloned()
        .collect();
    let visible_texts: Vec<String> = visible_entries.iter().map(history_entry_text).collect();
    let total = history.entries().count();

    let mut export_requested = false;
    widgets::card(ui, |ui| {
        ui.horizontal_wrapped(|ui| {
            if visible_texts.len() == total {
                if total == 1 {
                    ui.label("1 entry.".to_string());
                } else {
                    ui.label(format!("{total} entries."));
                }
            } else {
                ui.label(format!("{} of {total} entries shown.", visible_texts.len()));
            }
            if widgets::action_button(
                ui,
                "Copy visible log",
                widgets::ActionStyle::Secondary,
                !visible_texts.is_empty(),
            )
            .clicked()
            {
                let _ = clipboard.set_text(visible_texts.join("\n"));
            }
            if widgets::action_button(
                ui,
                "Export log",
                widgets::ActionStyle::Secondary,
                !visible_texts.is_empty(),
            )
            .clicked()
            {
                export_requested = true;
            }
            if widgets::action_button(
                ui,
                "Clear history",
                widgets::ActionStyle::Destructive,
                !visible_texts.is_empty(),
            )
            .clicked()
            {
                history.clear();
            }
        })
        .inner
    });
    if export_requested
        && let Some(path) = rfd::FileDialog::new()
            .set_file_name("archivefs-operations-log.txt")
            .save_file()
    {
        match std::fs::write(&path, visible_texts.join("\n")) {
            Ok(()) => history.record(HistoryEntry::new(
                ActivityAction::LogExport,
                None,
                ActivityOutcome::Completed,
                format!(
                    "Exported {} log entries to {}",
                    visible_texts.len(),
                    path.display()
                ),
            )),
            Err(error) => history.record(HistoryEntry::new(
                ActivityAction::LogExport,
                None,
                ActivityOutcome::Failed,
                format!("Could not export log to {}: {error}", path.display()),
            )),
        }
    }
    ui.separator();

    if visible_texts.is_empty() {
        widgets::empty_state(
            ui,
            "No matching activity",
            "Change or clear the filters to see session events.",
            None,
        );
        return action;
    }
    for (entry, text) in visible_entries.iter().zip(&visible_texts) {
        widgets::card(ui, |ui| {
            widgets::activity_row_header(
                ui,
                entry.outcome.to_string(),
                activity_outcome_tone(entry.outcome),
                entry.action.to_string(),
                Some(&format_history_timestamp(entry.timestamp)),
                |ui| {
                    if widgets::action_button(ui, "Copy", widgets::ActionStyle::Quiet, true)
                        .clicked()
                    {
                        let _ = clipboard.set_text(text.clone());
                    }
                },
            );
            ui.add(egui::Label::new(&entry.message).selectable(true).wrap());
            if let Some(path) = &entry.archive_path {
                widgets::technical_details(ui, ("history_related_archive", path), |ui| {
                    if widgets::path_value(ui, "Archive", path) {
                        let _ = clipboard.set_text(path.display().to_string());
                    }
                });
            }
        });
        ui.add_space(6.0);
    }
    action
}
/// What `try_resolve_dolphin_provider_from_local_sources` found, kept
/// distinct from `dolphin_provider` itself because `NotLoaded` alone can no
/// longer distinguish "hasn't looked yet" from "looked locally and found
/// nothing" now that a fruitless local lookup does not fall through to an
/// automatic network request.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
enum DolphinLocalLookupState {
    #[default]
    NotAttempted,
    NoCatalogueInstalled,
    NotInCatalogue,
    RegionMismatch,
    NoUsableCodes {
        warnings: Vec<String>,
    },
}

struct CheatWorkflowState {
    /// Exact-byte identity - the same `ArchiveRecord.mount_plan.archive
    /// .path` identity the rest of the app uses, never a filename.
    archive_path: PathBuf,
    display_name: String,
    normalized_name: String,
    platform: Option<String>,
    region: Option<String>,
    source_root: PathBuf,
    size_bytes: Option<u64>,
    /// The emulator adapter is explicit and independent from archive
    /// selection. PCSX2 is offered only for a canonical PS2 archive.
    adapter: CheatEmulatorAdapter,
    identity_request: Option<GameIdentityRequest>,
    identity: CheatStepResource<(GameIdentityRequest, GameIdentityReport)>,
    preview_request: Option<CheatPreviewRequestKey>,
    preview: CheatStepResource<CheatPreviewResponse>,
    transaction: CheatTransactionState,
    transaction_notice: Option<String>,
    /// The explicitly selected profile. Preselected only when exactly
    /// one eligible profile exists (the CLI's own auto-selection rule);
    /// with several eligible profiles the user must choose - never
    /// silently picked.
    selected_profile_id: Option<String>,
    selected_pcsx2_profile_id: Option<String>,
    /// The PCSX2 profile identity bound to this archive's inventory.
    pcsx2_inventory_profile_id: Option<String>,
    pcsx2_inventory: CheatStepResource<Pcsx2PnachInventory>,
    pcsx2_gamehacking: CheatStepResource<Pcsx2GameHackingState>,
    /// Dolphin-family GameHacking.org coverage. Wii is adapted into this
    /// existing state only after its own identity and safety policy runs.
    gamecube_gamehacking: CheatStepResource<GameCubeGameHackingState>,
    gamecube_gamehacking_request: Option<DolphinGameHackingRequestKey>,
    gamecube_gamehacking_cancellation: Option<Arc<AtomicBool>>,
    gamecube_gamehacking_generation: u64,
    /// True exactly when the current `gamecube_gamehacking` `Failed` state
    /// was classified as `GameHackingErrorKind::CloudflareBlocked` (see
    /// `GAMEHACKING_PROVIDER_CHALLENGE_MESSAGE`) rather than an ordinary
    /// failure - drives the dedicated neutral/blocked banner and hides
    /// Retry, since retrying immediately cannot help and core-side cooldown
    /// gating already prevents hammering a blocked origin.
    gamecube_gamehacking_blocked: bool,
    /// BSFree Archive GameCube coverage in Cheats & Mods: an optional local
    /// SQLite source, matched by platform + title to the selected archive's
    /// verified Dolphin Game ID. Installable only for the proven hex-pair
    /// formats; every other BSFree record stays browseable.
    bsfree_gamecube: CheatStepResource<BsFreeGameCubeGuiState>,
    bsfree_gamecube_cancellation: Option<Arc<AtomicBool>>,
    bsfree_gamecube_generation: u64,
    /// BSFree Wii coverage: the same optional local SQLite source, matched by
    /// platform + title to the archive's verified Dolphin Wii Game ID. Only
    /// the verified hex-pair subset is installable.
    bsfree_wii: CheatStepResource<BsFreeWiiGuiState>,
    bsfree_wii_cancellation: Option<Arc<AtomicBool>>,
    bsfree_wii_generation: u64,
    selected_dolphin_profile_id: Option<String>,
    /// An optional additional Dolphin configuration directory to scan,
    /// typed by the user - covers portable/AppImage installs, which have
    /// no fixed native or Flatpak path EmuWiz can discover on its own.
    /// Never auto-populated; rescanning without it drops nothing already
    /// found under the standard native/Flatpak locations.
    dolphin_explicit_root: String,
    /// The Dolphin profile identity bound to this archive's inventory.
    dolphin_inventory_profile_id: Option<String>,
    dolphin_inventory: CheatStepResource<DolphinGameIniInventory>,
    /// External discovery is bound only to exact archive/game/revision identity.
    /// Dolphin paths enter only when the adapter builds the selection below.
    dolphin_provider_request: Option<DolphinProviderRequestKey>,
    dolphin_provider: CheatStepResource<GeckoProviderFetchResult>,
    dolphin_provider_selection: Option<DolphinProviderSelectionState>,
    dolphin_destination_error: Option<String>,
    /// What the network-free local lookup (catalogue, then cached
    /// single-game result) found when it found nothing usable to show in
    /// `dolphin_provider` - lets the beginner view distinguish "still
    /// looking" (`NotAttempted`, `dolphin_provider` stays `NotLoaded`
    /// briefly) from "looked locally and there is genuinely nothing here"
    /// (any other variant, `dolphin_provider` stays `NotLoaded`
    /// indefinitely since no automatic network request follows).
    dolphin_local_lookup: DolphinLocalLookupState,
    /// The most recent automatic-selection outcome for the Dolphin
    /// profile - drives the beginner view's "using X automatically"
    /// confirmation, the "choose one of N profiles" chooser, or the
    /// setup-needed state. Recomputed whenever `dolphin_profiles`
    /// changes; never recomputed merely because the page re-renders.
    dolphin_profile_selection: Option<EmulatorProfileSelection>,
    /// The profile currently highlighted in the profile chooser dialog,
    /// pending the user's explicit "Use selected profile" confirmation.
    dolphin_profile_choice: Option<String>,
    /// Whether the beginner page's "Details" disclosure is expanded.
    /// Owned here (not egui's own collapsing-header memory) so it is
    /// trivially set from a test fixture and so it can be reset
    /// deliberately whenever the workflow state it discloses changes.
    /// Collapsed (`false`) by default.
    dolphin_details_open: bool,
    /// Whether the beginner install confirmation's "Show exact changes"
    /// disclosure is expanded. Resets to `false` whenever a fresh
    /// confirmation begins (see `start_beginner_install_dolphin`).
    dolphin_show_exact_changes: bool,
    selected_xenia_profile_id: Option<String>,
    /// An explicit Xenia Canary directory typed by the user - the only
    /// way EmuWiz ever learns of a Xenia install, since it has no
    /// single standard location.
    xenia_explicit_root: String,
    xenia_provider_request: Option<XeniaProviderRequestKey>,
    xenia_provider: CheatStepResource<XeniaProviderFetchResult>,
    /// Which of the provider's returned candidate documents the user
    /// picked - Xenia's own dataset legitimately has multiple files per
    /// Title ID (different Title Update/module-hash variants).
    xenia_selected_candidate_index: Option<usize>,
    xenia_selection: Option<XeniaSelectionState>,
    xenia_destination_error: Option<String>,
    /// The most recent automatic-selection outcome for the Xenia Canary
    /// profile - same role as `dolphin_profile_selection`.
    xenia_profile_selection: Option<EmulatorProfileSelection>,
    /// The profile currently highlighted in the profile chooser dialog,
    /// pending the user's explicit "Use selected profile" confirmation.
    xenia_profile_choice: Option<String>,
    /// Xenia's counterpart to `dolphin_details_open`.
    xenia_details_open: bool,
    /// Xenia's counterpart to `dolphin_show_exact_changes`.
    xenia_show_exact_changes: bool,
    /// Independent source mode. Changing it never changes the archive,
    /// profile, destination, or any fetched result retained by another mode.
    source_mode: CheatSourceMode,
    /// The profile identity bound to the current read-only installed-library
    /// inspection. A profile change invalidates only this observation.
    existing_library_profile_id: Option<String>,
    existing_library: CheatStepResource<RetroArchCheatLibraryInspection>,
    /// Step 2: the trusted-source cache listing, loaded in the
    /// background when the workflow opens.
    source_list: CheatStepResource<CheatSourceList>,
    /// Step 2: the most recent catalogue retrieval (network fetch or
    /// offline cached-snapshot reuse). A result whose source no longer
    /// matches `selected_source_id` at receive time is discarded.
    source_fetch: CheatStepResource<CheatSourceFetchResult>,
    /// The explicitly selected trusted source - preselected only when
    /// exactly one enabled trusted source exists (same single-candidate
    /// rule as profiles).
    selected_source_id: Option<String>,
    /// Whether "Fetch / Update catalogue" bypasses the fresh-cache
    /// short-circuit (the CLI's `--force-refresh`). Never applies to
    /// offline reuse.
    fetch_force_refresh: bool,
    /// Stage 4: the ranked candidate cheat files for this exact archive,
    /// bound to the key that produced them.
    candidates: CheatStepResource<CheatCandidateStage>,
    candidates_request: Option<CheatPreviewRequestKey>,
    /// Stage 4 search box, used only when the list is capped.
    candidate_query: String,
    /// Stages 5 and 6: the chosen candidate, its parsed cheats, and the
    /// user's per-cheat choices. Cleared whenever the candidate list is.
    candidate_selection: Option<CheatCandidateSelection>,
    /// A candidate the user chose that could not be opened - kept so the
    /// failure stays on screen instead of silently reverting the choice.
    candidate_load_error: Option<String>,
}

