    /// A deterministic, in-memory stand-in for `NativeClipboard` - the
    /// injectable clipboard every context-menu test uses instead of the
    /// real OS clipboard, so assertions never depend on (or pollute) the
    /// machine actually running the tests. Can independently simulate
    /// every case `ClipboardTextStatus` distinguishes: usable text,
    /// confirmed-empty, and a broken backend (`unavailable`) - plus a
    /// failing write (`set_error`), to exercise "backend failure produces
    /// a diagnostic and no mutation".
    #[derive(Default)]
    struct InMemoryClipboard {
        text: Option<String>,
        unavailable: Option<String>,
        set_error: Option<String>,
        set_calls: Vec<String>,
    }

    impl InMemoryClipboard {
        fn with_text(text: impl Into<String>) -> Self {
            Self {
                text: Some(text.into()),
                ..Self::default()
            }
        }

        fn unavailable(reason: impl Into<String>) -> Self {
            Self {
                unavailable: Some(reason.into()),
                ..Self::default()
            }
        }

        fn failing_to_write(reason: impl Into<String>) -> Self {
            Self {
                set_error: Some(reason.into()),
                ..Self::default()
            }
        }

        /// Test-only: the text from the most recent *successful*
        /// `set_text` call - i.e. what Copy/Cut actually wrote. Distinct
        /// from `get_text_status`, which is what a following Paste would
        /// read back (the same value, once written - real clipboards
        /// read back what was last written too).
        fn copied_text(&self) -> Option<String> {
            self.set_calls.last().cloned()
        }
    }

    impl ClipboardBackend for InMemoryClipboard {
        fn get_text_status(&mut self) -> ClipboardTextStatus {
            if let Some(reason) = &self.unavailable {
                return ClipboardTextStatus::Unavailable(reason.clone());
            }
            match &self.text {
                Some(text) if !text.is_empty() => ClipboardTextStatus::Ready(text.clone()),
                _ => ClipboardTextStatus::Empty,
            }
        }

        fn set_text(&mut self, text: String) -> Result<(), String> {
            if let Some(reason) = &self.set_error {
                return Err(reason.clone());
            }
            self.set_calls.push(text.clone());
            self.text = Some(text);
            Ok(())
        }
    }

    fn row(search_text: &str) -> ArchiveRow {
        ArchiveRow {
            path: PathBuf::new(),
            archive_path: String::new(),
            mount_path: String::new(),
            platform: String::new(),
            state: String::new(),
            search_text: search_text.to_lowercase(),
            origin: RowOrigin::Live,
            unknown_platform: false,
            source_path: None,
        }
    }

    fn record(archive_path: &str, mount_state: MountState) -> ArchiveRecord {
        let archive = Archive::from_path(archive_path).unwrap();
        ArchiveRecord::new(
            MountPlan::new(archive, PathBuf::from("/mnt/archivefs/Test")),
            mount_state,
            ArchiveMetadata {
                title: None,
                platform: None,
                region: None,
                languages: None,
                version: None,
                disc: None,
                publisher: None,
                developer: None,
                release_year: None,
                genre: None,
                notes: None,
                source: None,
            },
            ArchiveHealth::Pending,
        )
    }

    fn loose_mega_drive_record(path: &str) -> ArchiveRecord {
        let archive = Archive::from_path_in_root(path, "/roms").unwrap();
        ArchiveRecord::new(
            MountPlan::new(archive, PathBuf::from("/mnt/archivefs/Alien_3")),
            MountState::NotMountable,
            ArchiveMetadata {
                title: None,
                platform: Some("MegaDrive".to_string()),
                region: None,
                languages: None,
                version: None,
                disc: None,
                publisher: None,
                developer: None,
                release_year: None,
                genre: None,
                notes: None,
                source: None,
            },
            ArchiveHealth::Unsupported,
        )
    }

    #[test]
    fn queued_pending_paths_keeps_queue_order_and_only_pending_archives() {
        let records = vec![
            record("/roms/a.zip", MountState::Mounted),
            record("/roms/b.zip", MountState::Pending),
            record("/roms/c.zip", MountState::MountPathExists),
            record("/roms/d.zip", MountState::Pending),
        ];
        let queue = vec![
            PathBuf::from("/roms/d.zip"),
            PathBuf::from("/roms/a.zip"),
            PathBuf::from("/roms/b.zip"),
            PathBuf::from("/roms/missing.zip"),
        ];
        assert_eq!(
            queued_pending_paths(&queue, &records),
            vec![PathBuf::from("/roms/d.zip"), PathBuf::from("/roms/b.zip")],
            "only Pending queued archives are attempted, in queue order"
        );
    }

    #[test]
    fn stale_loose_rom_queue_entry_is_visible_but_never_attempted() {
        let loose = loose_mega_drive_record("/roms/genesis/Alien 3.md");
        let archive = record("/roms/game.zip", MountState::Pending);
        let records = vec![loose, archive];
        let queue = vec![
            PathBuf::from("/roms/genesis/Alien 3.md"),
            PathBuf::from("/roms/game.zip"),
        ];
        assert_eq!(
            queued_pending_paths(&queue, &records),
            vec![PathBuf::from("/roms/game.zip")]
        );
        assert_eq!(
            queue.len(),
            2,
            "stale loose entry remains removable by the user"
        );
        assert_eq!(pending_mount_items(&records).len(), 1);
        assert!(
            mount_all_items_for_paths(&records, &queue)
                .iter()
                .all(|item| item.archive_path != Path::new("/roms/genesis/Alien 3.md"))
        );
    }

    #[test]
    fn prune_mount_queue_drops_only_archives_missing_from_the_snapshot() {
        let records = vec![
            record("/roms/a.zip", MountState::Mounted),
            record("/roms/b.zip", MountState::MountPathExists),
        ];
        let mut queue = vec![
            PathBuf::from("/roms/a.zip"),
            PathBuf::from("/roms/gone.zip"),
            PathBuf::from("/roms/b.zip"),
        ];
        prune_mount_queue(&mut queue, &records);
        assert_eq!(
            queue,
            vec![PathBuf::from("/roms/a.zip"), PathBuf::from("/roms/b.zip")],
            "non-Pending archives stay queued (with a skip label); only vanished paths are pruned"
        );
    }

    #[test]
    fn mount_validation_labels_distinguish_ready_mounted_and_collision() {
        assert_eq!(
            mount_validation_label(MountState::Pending),
            "Ready to mount"
        );
        assert_eq!(
            mount_validation_label(MountState::Mounted),
            "Already mounted — will be skipped"
        );
        assert_eq!(
            mount_validation_label(MountState::MountPathExists),
            "Destination already exists — will be skipped"
        );
    }

    fn cheat_profile(profile_id: &str, eligible: bool) -> RetroArchCheatSetupProfile {
        RetroArchCheatSetupProfile {
            profile_id: profile_id.to_string(),
            installation_type: ProfileKind::Native,
            scope: ProfileScope::User,
            state: if eligible {
                RetroArchCheatSetupProfileState::Eligible
            } else {
                RetroArchCheatSetupProfileState::Ineligible
            },
            eligible,
            executable_evidence: Vec::new(),
            configuration_path: EncodedPath::from_path(Path::new("/isolated/retroarch.cfg")),
            cheat_destination_root: eligible
                .then(|| EncodedPath::from_path(Path::new("/isolated/cheats"))),
            blockers: if eligible {
                Vec::new()
            } else {
                vec![RetroArchCheatSetupProfileBlocker {
                    code: "cheats_destination_unresolved".to_string(),
                    detail: "no resolved cheats destination".to_string(),
                }]
            },
            diagnostics: Vec::new(),
        }
    }

