    /// Mirrors `show_primary_navigation`'s exact layout (same widgets, same
    /// order, same enabled predicate, same selected predicate) purely to
    /// discover each button's rendered `Rect` for click simulation. The
    /// production function itself only returns `Option<MainView>`, not
    /// per-button geometry; egui's vertical layout is fully deterministic
    /// from widget order and size alone, so this mirror's rects match the
    /// real function's. Iterates the same `PRIMARY_NAVIGATION_DESTINATIONS`
    /// const production uses, so the mirror cannot drift from the real
    /// destination list - now just one section since sidebar consolidation
    /// removed the secondary "LIBRARY TOOLS" section entirely.
    /// The actual click below is driven through the real production
    /// function, not this mirror.
    fn primary_nav_rects(
        ctx: &egui::Context,
        current: MainView,
        has_database: bool,
    ) -> Vec<(MainView, egui::Rect)> {
        let mut rects = Vec::new();
        let _ = ctx.run(egui::RawInput::default(), |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| {
                ui.vertical(|ui| {
                    ui.label(egui::RichText::new("EmuWiz").size(23.0).strong());
                    ui.label(
                        egui::RichText::new("Archive library manager").color(theme::muted(ui)),
                    );
                    ui.add_space(18.0);
                    ui.label(
                        egui::RichText::new("WORKFLOWS")
                            .small()
                            .strong()
                            .color(theme::muted(ui)),
                    );
                    for (view, label) in PRIMARY_NAVIGATION_DESTINATIONS {
                        let enabled = navigation_destination_enabled(view, has_database);
                        let selected = navigation_destination_selected(current, view);
                        let button = egui::Button::selectable(selected, label)
                            .min_size(egui::vec2(ui.available_width(), 34.0));
                        let resp = ui.add_enabled(enabled, button);
                        rects.push((view, resp.rect));
                    }
                });
            });
        });
        rects
    }

    #[test]
    fn all_navigation_destinations_are_reachable_via_a_real_click() {
        let ctx = egui::Context::default();

        let all_destinations = PRIMARY_NAVIGATION_DESTINATIONS
            .iter()
            .map(|(view, _)| *view);
        for target in all_destinations {
            let rects = primary_nav_rects(&ctx, MainView::Library, true);
            let target_rect = rects
                .iter()
                .find(|(view, _)| *view == target)
                .map(|(_, rect)| *rect)
                .unwrap_or_else(|| panic!("{target:?} must be one of the rendered nav labels"));

            let clicked_view: std::rc::Rc<std::cell::RefCell<Option<MainView>>> =
                std::rc::Rc::new(std::cell::RefCell::new(None));
            let captured = std::rc::Rc::clone(&clicked_view);
            let render = move |ui: &mut egui::Ui| -> egui::Response {
                let inner = ui.scope(|ui| show_primary_navigation(ui, MainView::Library, true));
                if let Some(view) = inner.inner {
                    *captured.borrow_mut() = Some(view);
                }
                inner.response
            };
            simulate_row_click(
                &ctx,
                target_rect.center(),
                egui::Modifiers::default(),
                render,
            );

            assert_eq!(
                *clicked_view.borrow(),
                Some(target),
                "clicking the {target:?} label must select it as the primary destination"
            );
        }
    }
    fn rendered_text_contains(output: &egui::FullOutput, needle: &str) -> bool {
        fn shape_contains(shape: &egui::Shape, needle: &str) -> bool {
            match shape {
                egui::Shape::Text(text_shape) => text_shape.galley.text().contains(needle),
                egui::Shape::Vec(nested) => nested.iter().any(|s| shape_contains(s, needle)),
                _ => false,
            }
        }
        output
            .shapes
            .iter()
            .any(|clipped| shape_contains(&clipped.shape, needle))
    }

    /// Finds the screen-space center of the first `Shape::Text` whose
    /// laid-out string *exactly matches* `needle` (unlike
    /// `rendered_text_contains`'s substring search, an exact match is
    /// required here so e.g. "Cancel" never matches a longer label that
    /// happens to contain it) - used to click a real button inside an
    /// already-rendered `egui::Window`, where the button's position
    /// cannot be predicted by rendering an identical standalone widget
    /// (unlike a fresh panel's first widget, a window's content depends
    /// on everything painted before it and the window's own computed
    /// size/anchor).
    fn find_exact_text_center(output: &egui::FullOutput, needle: &str) -> Option<egui::Pos2> {
        fn find_in_shape(shape: &egui::Shape, needle: &str) -> Option<egui::Pos2> {
            match shape {
                egui::Shape::Text(text_shape) => (text_shape.galley.text() == needle)
                    .then(|| text_shape.pos + text_shape.galley.size() / 2.0),
                egui::Shape::Vec(nested) => nested.iter().find_map(|s| find_in_shape(s, needle)),
                _ => None,
            }
        }
        output
            .shapes
            .iter()
            .find_map(|clipped| find_in_shape(&clipped.shape, needle))
    }

    /// Counts every `Shape::Text` whose laid-out string *exactly matches*
    /// `needle` - the exact-match counterpart of `rendered_text_contains`,
    /// used where "present" isn't precise enough (e.g. confirming a
    /// heading renders exactly once, not zero or two times).
    /// Like `find_exact_text_center`, but also returns the clip rect the
    /// shape was painted with - the boundary egui actually enforces at
    /// paint time. If the shape's own position falls outside that clip
    /// rect, the text is not actually visible on screen even though it
    /// was laid out and painted (a scroll area clips its content to its
    /// own viewport rect; a bottom panel overlapping that viewport would
    /// clip content the same way scrolling too little would).
    fn find_exact_text_position_and_clip(
        output: &egui::FullOutput,
        needle: &str,
    ) -> Option<(egui::Pos2, egui::Rect)> {
        fn find_in_shape(shape: &egui::Shape, needle: &str) -> Option<egui::Pos2> {
            match shape {
                egui::Shape::Text(text_shape) => (text_shape.galley.text() == needle)
                    .then(|| text_shape.pos + text_shape.galley.size() / 2.0),
                egui::Shape::Vec(nested) => nested.iter().find_map(|s| find_in_shape(s, needle)),
                _ => None,
            }
        }
        output.shapes.iter().find_map(|clipped| {
            find_in_shape(&clipped.shape, needle).map(|pos| (pos, clipped.clip_rect))
        })
    }

    fn fully_visible_exact_text_count(output: &egui::FullOutput, needles: &[String]) -> usize {
        fn find_rect(shape: &egui::Shape, needle: &str) -> Option<egui::Rect> {
            match shape {
                egui::Shape::Text(text) if text.galley.text() == needle => {
                    Some(egui::Rect::from_min_size(text.pos, text.galley.size()))
                }
                egui::Shape::Vec(nested) => {
                    nested.iter().find_map(|shape| find_rect(shape, needle))
                }
                _ => None,
            }
        }

        needles
            .iter()
            .filter(|needle| {
                output.shapes.iter().any(|clipped| {
                    find_rect(&clipped.shape, needle).is_some_and(|rect| {
                        rect.top() >= clipped.clip_rect.top()
                            && rect.bottom() <= clipped.clip_rect.bottom()
                    })
                })
            })
            .count()
    }

    fn count_exact_text_occurrences(output: &egui::FullOutput, needle: &str) -> usize {
        fn count_in_shape(shape: &egui::Shape, needle: &str) -> usize {
            match shape {
                egui::Shape::Text(text_shape) => usize::from(text_shape.galley.text() == needle),
                egui::Shape::Vec(nested) => nested.iter().map(|s| count_in_shape(s, needle)).sum(),
                _ => 0,
            }
        }
        output
            .shapes
            .iter()
            .map(|clipped| count_in_shape(&clipped.shape, needle))
            .sum()
    }

    fn library_app_with_test_rows(count: usize) -> (ArchiveFsApp, Vec<String>) {
        let paths: Vec<String> = (0..count)
            .map(|index| format!("/roms/library-row-{index:02}.zip"))
            .collect();
        let records = paths
            .iter()
            .map(|path| record(path, MountState::Pending))
            .collect();
        let mut app = app_for_operation_tests();
        app.state = LoadState::Ready(Box::new(loaded_data_with_records("/mount", records)));
        app.view = MainView::Library;
        app.library_tab = LibraryTab::Archives;
        // This helper exists to test Advanced View's Library table
        // rendering specifically (`show_loaded_data`'s full technical
        // columns, sort, multi-selection) - not Gamer View's compact
        // list. Every caller wants Advanced View's full `update()`
        // dispatch to run.
        app.ui_mode = GuiMode::AdvancedView;
        app.archive_context
            .select_only(PathBuf::from(paths[0].as_str()));
        (app, paths)
    }

    #[test]
    fn library_renders_multiple_complete_rows_at_desktop_and_small_viewports() {
        for (size, minimum_rows) in [
            (egui::vec2(1920.0, 1080.0), 6_usize),
            (egui::vec2(1024.0, 600.0), 2_usize),
        ] {
            let (mut app, paths) = library_app_with_test_rows(30);
            let ctx = egui::Context::default();
            let mut frame = eframe::Frame::_new_kittest();
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, size)),
                ..Default::default()
            };
            run_settle_frames(&ctx, &mut app, &mut frame, &input, 3);
            let output = ctx.run(input, |ctx| app.update(ctx, &mut frame));
            let visible = fully_visible_exact_text_count(&output, &paths);
            assert!(
                visible >= minimum_rows,
                "{size:?} must show at least {minimum_rows} complete Library rows, showed {visible}; first row rendered={}, geometry={:?}",
                rendered_text_contains(&output, &paths[0]),
                find_exact_text_position_and_clip(&output, &paths[0])
            );
        }
    }

    #[test]
    fn gamer_view_game_list_uses_the_remaining_height_not_two_or_three_rows() {
        // Manual QA layout finding: the Gamer View game list only showed
        // ~2-3 rows regardless of window size, with a large unused area
        // below it. The list must use all remaining height, be
        // independently scrollable, and keep the selected-game panel
        // fixed - mirroring the same desktop/1024x600 thresholds already
        // proven for Advanced View's Library table
        // (`library_renders_multiple_complete_rows_at_desktop_and_small_viewports`).
        for (size, minimum_rows) in [
            (egui::vec2(1920.0, 1080.0), 6_usize),
            (egui::vec2(1024.0, 600.0), 2_usize),
        ] {
            let mut app = app_for_operation_tests();
            app.ui_mode = GuiMode::GamerView;
            app.view = MainView::Library;
            let mut labels = Vec::new();
            let records: Vec<ArchiveRecord> = (0..30)
                .map(|index| {
                    let path = format!("/roms/gamer-row-{index:02}.zip");
                    let mut rec = record(&path, MountState::Pending);
                    let title = format!("Game {index:02}");
                    rec.metadata.title = Some(title.clone());
                    rec.metadata.platform = Some("GameCube".to_string());
                    labels.push(format!("{title} \u{2014} GameCube \u{b7} Ready to mount"));
                    rec
                })
                .collect();
            app.state = LoadState::Ready(Box::new(loaded_data_with_records("/mount", records)));

            let ctx = egui::Context::default();
            let mut frame = eframe::Frame::_new_kittest();
            let input = egui::RawInput {
                screen_rect: Some(egui::Rect::from_min_size(egui::Pos2::ZERO, size)),
                ..Default::default()
            };
            run_settle_frames(&ctx, &mut app, &mut frame, &input, 3);
            let output = ctx.run(input, |ctx| app.update(ctx, &mut frame));
            let visible = fully_visible_exact_text_count(&output, &labels);
            assert!(
                visible >= minimum_rows,
                "{size:?} must show at least {minimum_rows} complete Gamer View game rows, \
                 showed {visible}"
            );
        }
    }

    #[test]
    fn summary_counter_labels_never_collapse_into_vertical_text() {
        fn text_row_count(shape: &egui::Shape, needle: &str) -> Option<usize> {
            match shape {
                egui::Shape::Text(text) if text.galley.text() == needle => {
                    Some(text.galley.rows.len())
                }
                egui::Shape::Vec(nested) => nested
                    .iter()
                    .find_map(|shape| text_row_count(shape, needle)),
                _ => None,
            }
        }

        let ctx = egui::Context::default();
        let input = egui::RawInput {
            screen_rect: Some(egui::Rect::from_min_size(
                egui::Pos2::ZERO,
                egui::vec2(120.0, 100.0),
            )),
            ..Default::default()
        };
        let output = ctx.run(input, |ctx| {
            egui::CentralPanel::default().show(ctx, |ui| {
                ui.horizontal(|ui| summary_value(ui, "Total archives", 13_506));
            });
        });
        let rows = output
            .shapes
            .iter()
            .find_map(|shape| text_row_count(&shape.shape, "Total archives"));
        assert_eq!(rows, Some(1));
    }

